const E77_ATOMIC_PR: u64 = 598;
const E77_ATOMIC_BRANCH: &str = "cursor/e77-complete-tracer-4832";
const E77_ATOMIC_MARKER: &str = "ES-22-atomic-exception: E7-7 PR #598 (DEC-462)";

/// Pull requests a DEC names as atomic exceptions to ES-22's split, each with the exact marker its
/// description must carry (DEC-462's mechanism, DEC-2635's use of it). A pair whose spec change and
/// `src` change are mutually red — the new reference cases are refused by the old parser, and the
/// old reference cases by the new one — cannot be split at all, so it ships whole with a marker
/// that names its own DEC. The list is finite and each entry is one PR: nothing here is a standing
/// loosening, and deleting the entry restores the guard for that PR.
const ATOMIC_EXCEPTIONS: [(u64, &str); 2] = [
    (2022, "ES-22-atomic-exception: J1 PR #2022 (DEC-2635)"),
    (2200, "ES-22-atomic-exception: J2 PR #2200 (DEC-2335)"),
];

/// The verification skill's map of features to code, tests, and commands (AGENTS.md): one Markdown
/// file a feature, so a PR adding a feature adds a file and one changing a feature edits only
/// that feature's file. The directory is the map; `cargo xtask feature-map --index` lists it.
const FEATURE_MAP: &str = ".cursor/skills/verify-mandate/features";
/// Top-level entries a feature-map path may start with.
const REPO_ROOTS: [&str; 11] = [
    ".cargo/",
    ".cursor/",
    ".github/",
    "crates/",
    "docs/",
    "fixtures/",
    "python/",
    "reference/",
    "schemas/",
    "xtask/",
    "AGENTS.md",
];

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("xtask: {err:#}");
            ExitCode::FAILURE
        }
    }
}

fn run() -> Result<()> {
    let args: Vec<String> = env::args().skip(1).collect();
    let root = repo_root()?;
    let invoked = Command::new("git")
        .args(["rev-parse", "--show-toplevel"])
        .env_remove("GIT_DIR")
        .env_remove("GIT_WORK_TREE")
        .output()
        .ok()
        .filter(|out| out.status.success())
        .map(|out| PathBuf::from(String::from_utf8_lossy(&out.stdout).trim()));
    if let Some(why) = root_mismatch(&root, invoked.as_deref()) {
        bail!(why);
    }
    env::set_current_dir(&root).context("entering the repository root")?;
    match args
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>()
        .as_slice()
    {
        ["check"] => {
            for job in PR_JOBS {
                ci(job)?;
            }
            Ok(())
        }
        ["ci", "mutants", "--plan"] => {
            let history = mutant_costs::plan_history();
            let plan = mutants_plan_from(Path::new("."), base_ref()?.as_deref(), &history)?;
            eprintln!(
                "    mutants: {} mutant(s) over {} shard(s), up to {} a shard (DEC-2607)",
                plan.mutants, plan.shards, plan.per_shard
            );
            print!("{}", plan.outputs());
            Ok(())
        }
        ["ci", "sweep", "--plan"] => {
            let plan = sweep_plan(Path::new("."), sweep_night()?)?;
            eprintln!(
                "    sweep: {} mutant(s) over {} shard(s), {} of them tonight, every shard once in {} runs",
                plan.mutants,
                plan.total,
                plan.tonight.len(),
                plan.rotation
            );
            print!("{}", plan.outputs());
            Ok(())
        }
        ["ci", "schema-mutants", shard] => {
            eprintln!("==> ci schema-mutants {shard}");
            schema_mutants(Some(shard), &mut pinned_python)
        }
        ["ci", job] => ci(job),
        ["land-check"] => land_check_cmd(&root, LAND_CHECK_BASE),
        ["land-check", base] => land_check_cmd(&root, base),
        ["layers"] => layers(),
        ["markers"] => markers(),
        ["feature-map"] => feature_map(),
        ["feature-map", "--index"] => feature_map_index(),
        ["deps"] => deps(),
        ["deps", "--used-by"] => deps_used_by(),
        ["decisions"] => decision_numbers(Path::new(".")),
        ["leak-guard"] => leak::guard_in(&root),
        ["live-feature"] => live_feature_in(Path::new(".")),
        ["mail-guard"] => mail::guard_in(Path::new(".")),
        ["deferring-guard"] => deferring::guard_in(Path::new(".")),
        ["refcases"] => refcases(false),
        ["refcases", "--write"] => refcases(true),
        ["release", "tools"] => {
            release::tools(&release::Paths::from_env(&root)?.cargo_home).map(drop)
        }
        ["release", "build", out] => release::build(&root, Path::new(out)),
        ["trial", rest @ ..] => trial::run(&root, &trial::Trial::parse(rest)?),
        ["release", "compare", a, b] => release::compare(Path::new(a), Path::new(b)),
        ["release", "images", dist, out] => {
            release::images(&root, Path::new(dist), Path::new(out), false)
        }
        ["release", "images", dist, out, "--test-sign"] => {
            release::images(&root, Path::new(dist), Path::new(out), true)
        }
        ["release", "drill", dist, out] => release::drill(&root, Path::new(dist), Path::new(out)),
        ["release", "check-signed", dist, signatures] => {
            release::check_signed(&root, Path::new(dist), Path::new(signatures))
        }
        ["release", "publish", dist, out] => {
            release::publish(&root, Path::new(dist), Path::new(out))
        }
        ["release", "publish-index", out] => release::publish_index(&root, Path::new(out)),
        ["release", "publish-signed", dist, signatures, out] => release::publish_signed(
            &root,
            Path::new(dist),
            Path::new(signatures),
            Path::new(out),
        ),
        ["infra"] => infra(),
        ["infra", "close"] => infra_close(),
        ["release", "publish-signed-index", out] => {
            release::publish_signed_index(&root, Path::new(out))
        }
        ["release", "publish-charts", out] => release::publish_charts(&root, Path::new(out)),
        ["gitops", "bootstrap", environment] => {
            gitops::bootstrap(&root, gitops::Environment::parse(environment)?)
        }
        ["gitops", "promote", "staging", published] => promote::promote(
            &root,
            gitops::Environment::Staging,
            Some(Path::new(published)),
        ),
        ["gitops", "promote", "production"] => {
            promote::promote(&root, gitops::Environment::Production, None)
        }
        ["gitops", "secrets", environment] => {
            gitops::secrets(gitops::Environment::parse(environment)?)
        }
        ["cell", "up"] => cell::up(),
        ["cell", "down"] => cell::down(),
        ["cell", "hosted"] => cell::hosted(),
        ["cell", "demo"] => cell::demo(true),
        ["cell", "demo", "--no-web"] => cell::demo(false),
        ["cell", "demo", "--scenario", name] => cell::scenario::run(name),
        ["cell", "demo", "--scenario", name, "--dry-run", target @ ..] => {
            cell::scenario::dry_run(name, target)
        }
        ["cell", "journey"] => {
            let workspace = cell::scenario::run_in("demo")?;
            cell::scenario::accept_disclosure(&workspace)?;
            cell::journey(&workspace, cell::scenario::WEB_AGENT)
        }
        ["cell", "journey", workspace, agent] => {
            cell::scenario::accept_disclosure(workspace)?;
            cell::journey(workspace, agent)
        }
        ["cell", "web-setup", workspace] => cell::setup(workspace),
        ["cell", "web-kill-switch", workspace] => {
            cell::web::report(cell::web::kill_switch_from_web(workspace, None))
        }
        ["cell", "web-kill-switch", workspace, agent] => {
            cell::web::report(cell::web::kill_switch_from_web(workspace, Some(agent)))
        }
        ["cell", "generate"] => cell::generate(false),
        ["cell", "generate", "--write"] => cell::generate(true),
        ["cell", "drill", rest @ ..] => {
            let (seeded, names) = match rest {
                ["--seeded", names @ ..] => (true, names),
                names => (false, names),
            };
            let drills = if names.is_empty() {
                cell::DRILLS
                    .into_iter()
                    .chain(cell::JOURNAL_DRILLS)
                    .chain(cell::FAILOVER_DRILLS)
                    .chain(cell::KILL_SWITCH_DRILLS)
                    .chain(cell::EXECUTOR_DRILLS)
                    .chain(cell::VAULT_DRILLS)
                    .chain(cell::EXCHANGE_DRILLS)
                    .collect()
            } else {
                names
                    .iter()
                    .map(|n| cell::Drill::parse(n))
                    .collect::<Result<Vec<_>>>()?
            };
            cell::drill(&drills, seeded)
        }
        _ => {
            eprint!("{USAGE}");
            bail!("unknown command: {}", args.join(" "))
        }
    }
}

fn ci(job: &str) -> Result<()> {
    eprintln!("==> ci {job}");
    match job {
        "lint" => ci_lint(Path::new("."), |name| env::var(name).ok(), workspace_lint),
        "test" => {
            for part in TEST_PARTS {
                eprintln!("==> ci {part}");
                test_part(part, None)?;
            }
            Ok(())
        }
        "test-nextest" | "test-python" => {
            let partition = env::var(TEST_PARTITION_ENV).ok().filter(|s| !s.is_empty());
            test_part(job, partition.as_deref())
        }
        "test-doc" | "test-rh-sim" => test_part(job, None),
        "pending" => pending(),
        "portable" => portable(),
        "select" => ci_select(),
        "cell" => cell::ci(),
        "cell-seeded" => cell::ci_seeded(),
        "cell-upgrade" => cell::ci_upgrade(),
        "cell-demo" => cell::scenario::ci(),
        "cell-journal" => cell::ci_drills(job, &cell::JOURNAL_DRILLS),
        "cell-failover" => cell::ci_drills(job, &cell::FAILOVER_DRILLS),
        "cell-kill-switch" => cell::ci_drills(job, &cell::KILL_SWITCH_DRILLS),
        "cell-executor" => cell::ci_drills(job, &cell::EXECUTOR_DRILLS),
        "cell-vault" => cell::ci_drills(job, &cell::VAULT_DRILLS),
        "cell-exchange" => cell::ci_drills(job, &cell::EXCHANGE_DRILLS),
        "refcases" => refcases(false),
        "reference" => {
            reference(&["mandate/generate.py"])?;
            sh(
                "git",
                &[
                    "diff",
                    "--exit-code",
                    "--",
                    "docs/specs/reference-cases/mandate.yaml",
                ],
            )
            .context(
                "reference/mandate/generate.py changed mandate.yaml; regenerate and commit it",
            )?;
            reference(&["mandate/check_cases.py"])?;
            for seed in ["1", "2", "3"] {
                reference(&["mandate/fuzz.py", seed])?;
            }
            reference(&["journal/generate.py", "--check"]).context(
                "reference/journal/generate.py --check failed: a validator or seeded bug check failed, or journal.yaml is not what it generates; run it without --check and commit the result",
            )?;
            mutation_anchors()
        }
        "schemas" => schema_checks(&mut pinned_python),
        "schema-mutants" => {
            let shard = env::var(SCHEMA_SHARD_ENV).ok().filter(|s| !s.is_empty());
            schema_mutants(shard.as_deref(), &mut pinned_python)
        }
        "supply-chain" => {
            sh("cargo", &["deny", "--locked", "check"])?;
            deps()?;
            secrets()
        }
        "secrets" => secrets(),
        "spec-guard" => spec_guard(),
        "postgres" => postgres(),
        "openbao" => openbao(),
        "objectstore" => objectstore(),
        "tofu" => tofu_checks(),
        "stub-release" => stub_release(),
        "exchange-release" => exchange_release(),
        "provisionerd-release" => provisionerd_release(),
        "api-release" => api_release(),
        "mutants" => mutants(Path::new("."), base_ref()?.as_deref()),
        "mutants-costs" => mutant_costs::ci(),
        "sweep" => sweep(Path::new(".")),
        "fast" => {
            for part in FAST_JOB {
                ci(part)?;
            }
            Ok(())
        }
        "full" => {
            for part in FULL_JOB {
                ci(part)?;
            }
            Ok(())
        }
        "nightly" => {
            nightly_fuzz(None)?;
            reference(&["mandate/mutants.py"])?;
            nightly_gitleaks()
        }
        "nightly-fuzz" => {
            let shard = env::var(FUZZ_SHARD_ENV)
                .with_context(|| format!("{FUZZ_SHARD_ENV} names the fuzz shard, K/N"))?;
            nightly_fuzz(Some(&shard))
        }
        "nightly-mutants" => {
            let shard = env::var(REFERENCE_SHARD_ENV).with_context(|| {
                format!("{REFERENCE_SHARD_ENV} names the reference's mutant shard, K/N")
            })?;
            reference(&["mandate/mutants.py", "--shard", &shard])
        }
        "nightly-gitleaks" => nightly_gitleaks(),
        other => bail!("unknown CI job: {other}"),
    }
}

/// The runner on the host it runs on (DEC-954): clippy `-D warnings` over every target of
/// `mandate-paper`, then its core-dump hardening tests, which read the kernel's answer back.
/// CI's `fast-portable` job runs it on macOS, where the founder runs the CLIs, so a Linux-only
/// call in the runner fails a required check; on Linux it repeats what `lint` and `test` cover.
fn portable() -> Result<()> {
    if !selection()?.runner() {
        eprintln!(
            "    portable: the diff reaches no crate {RUNNER_CRATE} is built from (DEC-1190)"
        );
        return Ok(());
    }
    sh(
        "cargo",
        &[
            "clippy",
            "--locked",
            "--package",
            "mandate-paper",
            "--all-targets",
            "--",
            "-D",
            "warnings",
        ],
    )?;
    sh(
        "cargo",
        &[
            "test",
            "--locked",
            "--package",
            "mandate-paper",
            "--lib",
            "--test",
            "live_entry",
            "--",
            "harden",
        ],
    )
}

/// One of [`TEST_PARTS`], over the crates the diff selects (DEC-1190); `partition`, a `K/N`
/// counted from 1, runs only the `K`th of `N` slices of the nextest run (DEC-871) or of the
/// Python tests (DEC-2646).
fn test_part(part: &str, partition: Option<&str>) -> Result<()> {
    match part {
        "test-nextest" => {
            let selected = selection()?;
            if !selected.tests() {
                eprintln!("    test-nextest: no crate affected (DEC-1190)");
                return Ok(());
            }
            let mut args = nextest_args(partition, scoped_packages(&selected).as_deref())?;
            if env::var_os(NO_FAIL_FAST_ENV).is_some() {
                args.push("--no-fail-fast".to_owned());
            }
            if let Ok(filter) = env::var(NEXTEST_FILTER_ENV) {
                eprintln!(
                    "    test-nextest: {NEXTEST_FILTER_ENV} narrows this run to `{filter}` \
                     (DEC-2644); unset it to run every selected test"
                );
                filtered(&mut args, &filter);
            }
            let Ok(spec) = env::var(NEXTEST_RUNNER_ENV) else {
                return sh(
                    "cargo",
                    &args.iter().map(String::as_str).collect::<Vec<_>>(),
                );
            };
            let (name, runner) = nextest_runner(&spec)?;
            eprintln!(
                "    test-nextest: {NEXTEST_RUNNER_ENV} runs each test process through `{runner}` \
                 (DEC-2644)"
            );
            eprintln!("    $ {name}='{runner}' cargo {}", args.join(" "));
            let status = Command::new("cargo")
                .args(&args)
                .env(name, runner)
                .status()
                .context("starting `cargo`")?;
            if !status.success() {
                bail!("`cargo {}` failed with {status}", args.join(" "));
            }
            Ok(())
        }
        "test-doc" => {
            let selected = selection()?;
            let meta = metadata()?;
            let libraries: Vec<&str> = workspace_packages(&meta)
                .into_iter()
                .filter(|p| p.targets.iter().any(|t| t.kind.iter().any(|k| k == "lib")))
                .filter(|p| selected.crates.contains(&p.name))
                .map(|p| p.name.as_str())
                .collect();
            if libraries.is_empty() {
                eprintln!("    test-doc: no selected crate has a library (DEC-1190)");
                return Ok(());
            }
            let mut args = vec!["test", "--locked", "--doc"];
            if selected.everything.is_some() {
                args.push("--workspace");
            } else {
                for library in &libraries {
                    args.extend(["--package", library]);
                }
            }
            sh("cargo", &args)
        }
        "test-rh-sim" => rh_sim_tests(),
        "test-python" => uv_tools(&pytest_args(partition)?),
        other => bail!("unknown test part: {other}"),
    }
}

/// The `--package` list a scoped run passes, or `None` for a `--workspace` run, when the
/// selection is everything (DEC-1190).
fn scoped_packages(selected: &Selection) -> Option<Vec<String>> {
    selected
        .everything
        .is_none()
        .then(|| selected.crates.iter().cloned().collect())
}

/// The `rh-sim` rehearsal build's tests (DEC-922): `mandate-mcp` and the runner, `mandate-paper`,
/// each with the feature, which no workspace crate turns on, so the workspace's own run never
/// builds it; `mandate-mcp`'s login tests run the simulator binary built here. Each package runs
/// in its own build, so neither's feature is unified into the other's (DEC-963).
fn rh_sim_tests() -> Result<()> {
    let tested = selection()?.among(&REHEARSAL_TESTED);
    if tested.is_empty() {
        eprintln!("    test-rh-sim: no crate declaring `{REHEARSAL}` is affected (DEC-1190)");
        return Ok(());
    }
    sh(
        "cargo",
        &[
            "build",
            "--locked",
            "--package",
            "mandate-rh-sim",
            "--bin",
            "mandate-rh-sim",
        ],
    )?;
    let meta: serde_json::Value = serde_json::from_str(&output_in(
        Path::new("."),
        "cargo",
        &["metadata", "--format-version", "1", "--no-deps", "--locked"],
    )?)
    .context("parsing cargo metadata")?;
    let target = meta["target_directory"]
        .as_str()
        .context("cargo metadata names no target directory")?;
    let binary = Path::new(target).join("debug").join("mandate-rh-sim");
    rehearsal_runs(&tested, |args| {
        eprintln!(
            "    $ {RH_SIM_BIN_ENV}={} cargo {}",
            binary.display(),
            args.join(" ")
        );
        Command::new("cargo")
            .args(args)
            .env(RH_SIM_BIN_ENV, &binary)
            .status()
            .context("starting `cargo nextest`")
    })
}

/// The `rh-sim` test runs of `packages`, some of [`REHEARSAL_TESTED`], one `cargo nextest run` a
/// package, in order, each through `run`, which takes the `cargo` arguments and says how the run
/// exited; the first that fails stops the rest and is named in the error.
fn rehearsal_runs(
    packages: &[&str],
    mut run: impl FnMut(&[&str]) -> Result<ExitStatus>,
) -> Result<()> {
    for &package in packages {
        let args = [
            "nextest",
            "run",
            "--locked",
            "--no-tests=fail",
            "--package",
            package,
            "--features",
            REHEARSAL,
        ];
        let status = run(&args)?;
        if !status.success() {
            bail!("the rh-sim rehearsal build's tests of {package} failed with {status}");
        }
    }
    Ok(())
}

/// The packages `cargo xtask ci test-rh-sim` tests with the `rh-sim` feature, each in its own
/// build: every workspace crate that declares it (DEC-922, DEC-963, DEC-962 item 2).
const REHEARSAL_TESTED: [&str; 3] = ["mandate-mcp", "mandate-paper", "mandate-cli"];

/// The workspace's nextest settings, under `xtask/` rather than nextest's default `.config/`, a
/// top-level directory whose name the outside-path scan reads in any `.config` field access
/// (DEC-2325).
const NEXTEST_CONFIG: &str = "xtask/nextest.toml";

/// The arguments of the workspace's nextest run over `packages`, or the whole workspace when
/// there are none to scope it to (DEC-1190): every test of them or, with `partition` (`K/N`, `1
/// <= K <= N`, plain decimal), nextest's counted `K`th of `N` shards, which together run every
/// test once (DEC-871). Every run reads [`NEXTEST_CONFIG`], so its longest tests start first
/// (DEC-2325).
/// Narrows a nextest run to the tests `filter` selects (DEC-2644): land-check's one more run of a
/// test that failed as root, over the same packages, build and environment as the run it failed
/// in. Exactly the filtered tests, or it fails: a filter that selects none is no pass.
const NEXTEST_FILTER_ENV: &str = "MANDATE_NEXTEST_FILTER";

/// The target runner a nextest run's test processes start through (DEC-2644), as
/// `CARGO_TARGET_<HOST>_RUNNER=<command>`: `ci test-nextest` sets it on its `cargo nextest` alone.
/// Set on the `cargo xtask` that runs the job, the runner would start xtask itself too, which as
/// uid 65534 cannot start the toolchain under `/root` (lane DR's land-check of #2743).
const NEXTEST_RUNNER_ENV: &str = "MANDATE_NEXTEST_RUNNER";

/// [`NEXTEST_RUNNER_ENV`]'s value read as the target-runner variable's name and its command; any
/// other variable, or no command, is refused.
fn nextest_runner(spec: &str) -> Result<(&str, &str)> {
    match spec.split_once('=') {
        Some((name, runner))
            if name.starts_with("CARGO_TARGET_")
                && name.ends_with("_RUNNER")
                && !runner.trim().is_empty() =>
        {
            Ok((name, runner))
        }
        _ => bail!(
            "{NEXTEST_RUNNER_ENV} must read `CARGO_TARGET_<HOST>_RUNNER=<command>`, not `{spec}`"
        ),
    }
}

/// `args`, a nextest run's, narrowed to `filter`'s tests, refusing a run that selects none.
fn filtered(args: &mut Vec<String>, filter: &str) {
    for arg in args.iter_mut() {
        if arg == "--no-tests=pass" {
            "--no-tests=fail".clone_into(arg);
        }
    }
    args.extend(["-E".to_owned(), filter.to_owned()]);
}

fn nextest_args(partition: Option<&str>, packages: Option<&[String]>) -> Result<Vec<String>> {
    let config = repo_root()?.join(NEXTEST_CONFIG);
    let mut args: Vec<String> = ["nextest", "run", "--config-file"]
        .map(String::from)
        .to_vec();
    args.push(config.to_string_lossy().into_owned());
    match packages {
        None => args.push("--workspace".to_owned()),
        Some(packages) => {
            for package in packages {
                args.extend(["--package".to_owned(), package.clone()]);
            }
        }
    }
    args.extend(["--locked", "--no-tests=pass"].map(String::from));
    if let Some(partition) = partition {
        let (k, n) = partition_of(partition)?;
        args.push(format!("--partition=count:{k}/{n}"));
    }
    Ok(args)
}

/// A test part's shard, [`TEST_PARTITION_ENV`]'s `K/N`: plain decimals with no leading zero,
/// `1 <= K <= N`, counted from 1 (DEC-871). The nextest run and the Python tests read it alike.
fn partition_of(partition: &str) -> Result<(u32, u32)> {
    let parsed = partition.split_once('/').and_then(|(k, n)| {
        let plain = |s: &str| !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit());
        if !plain(k) || !plain(n) || k.starts_with('0') || n.starts_with('0') {
            return None;
        }
        Some((k.parse::<u32>().ok()?, n.parse::<u32>().ok()?))
    });
    match parsed {
        Some((k, n)) if k <= n => Ok((k, n)),
        _ => bail!(
            "{TEST_PARTITION_ENV} must be K/N with 1 <= K <= N, counted from 1; got {partition:?}"
        ),
    }
}

/// The pytest plugin that keeps one shard of the collected tests (DEC-2646): every shard collects
/// the same tests and keeps every `N`-th of their sorted node ids from `K-1`, reading `K/N` from
/// [`TEST_PARTITION_ENV`] itself (`python/mandate_tools/src/mandate_tools/pytest_shard.py`).
const PYTEST_SHARD_PLUGIN: &str = "mandate_tools.pytest_shard";

/// The pytest arguments of the Python tests, or of one shard of them when `partition` is given:
/// the shard plugin loaded, `K/N` checked here first so a malformed one fails before pytest runs.
fn pytest_args(partition: Option<&str>) -> Result<Vec<&'static str>> {
    let mut args = vec!["pytest", "-q"];
    if let Some(partition) = partition {
        partition_of(partition)?;
        args.extend(["-p", PYTEST_SHARD_PLUGIN]);
    }
    Ok(args)
}

/// The Postgres journal tests against a real database (ADR-0001 ES-08), `mandate-journal-pg`'s,
/// the CLI's control journal's (P0, DEC-520), and the dispatcher's (DEC-2500 item 8). `test` runs
/// them too, but they skip there unless
/// `MANDATE_PG_URL` is set; here they must run.
fn postgres() -> Result<()> {
    if env::var_os(PG_URL).is_none() {
        if env::var_os(PG_REQUIRED).is_some() {
            bail!("{PG_REQUIRED} is set but {PG_URL} is not");
        }
        eprintln!(
            "    postgres: {PG_URL} is unset; skipping (see crates/mandate-journal-pg/README.md)"
        );
        return Ok(());
    }
    let tested = selection()?.among(&PG_TESTED);
    if tested.is_empty() {
        eprintln!("    postgres: no crate with Postgres tests is affected (DEC-1190)");
        return Ok(());
    }
    let mut args = vec!["nextest", "run"];
    for package in &tested {
        args.extend(["--package", package]);
    }
    args.extend(["--locked", "--no-tests=pass"]);
    eprintln!("    $ {PG_REQUIRED}=1 cargo {}", args.join(" "));
    let status = Command::new("cargo")
        .args(args)
        .env(PG_REQUIRED, "1")
        .status()
        .context("starting `cargo nextest`")?;
    if !status.success() {
        bail!("the Postgres journal tests failed with {status}");
    }
    Ok(())
}

/// `mandate-vault`'s conformance suite against a real OpenBao dev server (E21-32, DEC-977). `test`
/// runs it too, but it skips there unless `MANDATE_OPENBAO_ADDR` is set; here it must run, when
/// the diff selects `mandate-vault` (DEC-1190).
fn openbao() -> Result<()> {
    if env::var_os(OPENBAO_ADDR).is_none() {
        if env::var_os(OPENBAO_REQUIRED).is_some() {
            bail!("{OPENBAO_REQUIRED} is set but {OPENBAO_ADDR} is not");
        }
        eprintln!(
            "    openbao: {OPENBAO_ADDR} is unset; skipping (see .github/scripts/start-openbao.sh)"
        );
        return Ok(());
    }
    let packages = selection()?.among(&OPENBAO_TESTED);
    if packages.is_empty() {
        eprintln!("    openbao: neither mandate-vault nor mandate-cli is affected (DEC-1190)");
        return Ok(());
    }
    for package in packages {
        let mut args = vec!["nextest", "run", "--package", package];
        args.extend_from_slice(openbao_tests(package));
        args.push("--locked");
        eprintln!("    $ {OPENBAO_REQUIRED}=1 cargo {}", args.join(" "));
        let status = Command::new("cargo")
            .args(&args)
            .env(OPENBAO_REQUIRED, "1")
            .status()
            .context("starting `cargo nextest`")?;
        if !status.success() {
            bail!("{package}'s OpenBao tests failed with {status}");
        }
    }
    Ok(())
}

/// The stub token issuer's crate and binary (E21-52, DEC-2100).
const STUB_ISSUER: &str = "mandate-stub-issuer";

/// All a build of the stub without debug assertions may write, to standard error (DEC-2100 item 2).
const STUB_NOT_BUILT: &str = "stub_issuer_not_built\n";

/// How many 20 ms waits the release stub gets to exit before it is killed and the check fails: a
/// stub that holds an issuer serves instead of exiting.
const STUB_RELEASE_WAITS: u32 = 250;

/// DEC-2100 item 2: a build without debug assertions holds no issuer. Builds the stub with
/// `--release` once, only when the diff selects its crate (DEC-1190), runs it as a `dev` cell
/// would, and requires [`release_stub_refused`]. It runs here rather than as a crate test, so the
/// mutation gate never rebuilds the crate in release.
fn stub_release() -> Result<()> {
    if !selection()?.crates.contains(STUB_ISSUER) {
        eprintln!("    stub-release: {STUB_ISSUER} is not affected (DEC-1190)");
        return Ok(());
    }
    let output = released(
        STUB_ISSUER,
        &["--bind", "127.0.0.1:8899"],
        &[("MANDATE_DEPLOYMENT_TIER", "dev")],
    )?
    .with_context(|| {
        format!(
            "the release build of {STUB_ISSUER} kept running instead of refusing: it holds an \
             issuer (DEC-2100 item 2)"
        )
    })?;
    release_stub_refused(&output)
}

/// The token-exchange process's crate and binary (E10-13 slice 5b-3, DEC-2633).
const TOKEN_EXCHANGE: &str = "mandate-token-exchange";

/// All the release token exchange may write, to standard error, when it is given a token URL
/// (DEC-2633 item 2).
const TOKEN_URL_IN_RELEASE: &str = "token_exchange_token_url_in_release\n";

/// DEC-2633 item 2: a build without debug assertions refuses to start when `MANDATE_TOKEN_URL` is
/// set at all. Builds the exchange with `--release` once, only when the diff selects its crate
/// (DEC-1190), and runs it as a cell would: a dev tier with a token URL its debug build admits, a
/// dev tier with an empty one, and a production tier with one. Each run must be
/// [`release_exchange_refused`]. It first refuses an environment that turns debug assertions back
/// on in the release profile (DEC-2322), which would make the build it checks not the one
/// the image ships.
fn exchange_release() -> Result<()> {
    if !selection()?.crates.contains(TOKEN_EXCHANGE) {
        eprintln!("    exchange-release: {TOKEN_EXCHANGE} is not affected (DEC-1190)");
        return Ok(());
    }
    release_profile_untouched(|name| env::var(name).ok())?;
    for (tier, url) in [
        ("dev", "http://127.0.0.1:8091/alpaca/oauth/token"),
        ("dev", ""),
        ("production", "http://127.0.0.1:8091/alpaca/oauth/token"),
    ] {
        let output = released(
            TOKEN_EXCHANGE,
            &[],
            &[
                ("MANDATE_DEPLOYMENT_TIER", tier),
                ("MANDATE_SUBJECT", "conn_01JB3K6F0C9R2V7N4M8Q1T5W50"),
                ("MANDATE_TOKEN_URL", url),
            ],
        )?
        .with_context(|| {
            format!(
                "the release build of {TOKEN_EXCHANGE} kept running instead of refusing its \
                 token URL in tier {tier} (DEC-2633 item 2)"
            )
        })?;
        release_exchange_refused(&output)
            .with_context(|| format!("tier {tier}, token URL {url:?}"))?;
    }
    Ok(())
}

/// The role provisioner's process's crate and binary (E21-33, DEC-2350).
const PROVISIONERD: &str = "mandate-provisionerd";

/// All the release role provisioner may write, to standard error, when it is asked for its
/// fixture.
const FIXTURE_NOT_BUILT: &str = "role_provisioner_start_failed: fixture_not_built\n";

/// A build without debug assertions holds no fixture vault, so it never makes or removes a role
/// against a vault that keeps nothing. Builds the provisioner with `--release` once, only when the
/// diff selects its crate (DEC-1190), runs it with `--fixture` and every other flag a start needs,
/// and requires [`release_provisionerd_refused`]. It first refuses an environment that turns
/// debug assertions back on in the release profile (DEC-2322).
fn provisionerd_release() -> Result<()> {
    if !selection()?.crates.contains(PROVISIONERD) {
        eprintln!("    provisionerd-release: {PROVISIONERD} is not affected (DEC-1190)");
        return Ok(());
    }
    release_profile_untouched(|name| env::var(name).ok())?;
    let socket = env::temp_dir().join(format!("provisionerd-release-{}.sock", std::process::id()));
    let socket = socket
        .to_str()
        .context("the probe socket's path is not UTF-8")?;
    let output = released(
        PROVISIONERD,
        &[
            "run",
            "--probe",
            socket,
            "--workspace",
            "ws_1",
            "--namespace",
            "ws-1",
            "--fixture",
        ],
        &[],
    )?
    .with_context(|| {
        format!(
            "the release build of {PROVISIONERD} kept running instead of refusing its fixture: \
             it holds a fixture vault"
        )
    })?;
    release_provisionerd_refused(&output)
}

/// Whether a release provisioner's run is the fixture's refusal: exit 2, [`FIXTURE_NOT_BUILT`]
/// alone on standard error, and nothing on standard output.
fn release_provisionerd_refused(output: &std::process::Output) -> Result<()> {
    let stderr = String::from_utf8_lossy(&output.stderr);
    if output.status.code() != Some(2) || stderr != FIXTURE_NOT_BUILT || !output.stdout.is_empty() {
        bail!(
            "the release build of {PROVISIONERD} must exit 2 writing only \
             {FIXTURE_NOT_BUILT:?} to standard error; it exited {} with stdout {:?} and stderr \
             {stderr:?}",
            output.status,
            String::from_utf8_lossy(&output.stdout)
        );
    }
    Ok(())
}

/// The workspace API server's crate and binary (E21-31, DEC-978).
const API_SERVER: &str = "mandate-api-server";

/// All a release API may write, to standard error, when it is given an authorization page
/// (DEC-2633 item 3, DEC-2338 item 5).
const AUTHORIZE_URL_REFUSED: &str = "refused: MANDATE_ALPACA_AUTHORIZE_URL is set outside a dev or ci \
debug build, or names no cell page\n";

/// The refusal an unsigned release binary meets first in a tier that requires a signature.
const RELEASE_UNSIGNED: &str = "release_unsigned\n";

/// DEC-2338 item 5: a build without debug assertions refuses to start whenever
/// `MANDATE_ALPACA_AUTHORIZE_URL` is set, in every tier. Builds the API with `--release` once, only
/// when the diff selects its crate (DEC-1190), and runs it with a cell's page, a loopback page and
/// an empty one, in each tier. Each run must be [`release_api_refused`]. The page is judged before
/// any other setting, so the run needs no database, key or address. An unsigned binary in staging
/// or production meets `release_unsigned` first, so it also runs the crate's `config` tests built
/// with `--release`, whose release-only test asserts every tier refuses any set page. Together
/// they, not a debug unit test, cover `config::authorize_page`'s release arm.
fn api_release() -> Result<()> {
    if !selection()?.crates.contains(API_SERVER) {
        eprintln!("    api-release: {API_SERVER} is not affected (DEC-1190)");
        return Ok(());
    }
    release_profile_untouched(|name| env::var(name).ok())?;
    sh(
        "cargo",
        &[
            "test",
            "--locked",
            "--release",
            "--package",
            API_SERVER,
            "--test",
            "config",
        ],
    )?;
    for tier in ["dev", "ci", "staging", "production"] {
        for page in [
            "http://oauth-fixture:8091/alpaca/oauth/authorize",
            "http://127.0.0.1:8091/alpaca/oauth/authorize",
            "",
        ] {
            let output = released(
                API_SERVER,
                &["--bind", "127.0.0.1:0", "--probe-bind", "127.0.0.1:0"],
                &[
                    ("MANDATE_DEPLOYMENT_TIER", tier),
                    ("MANDATE_ALPACA_AUTHORIZE_URL", page),
                ],
            )?
            .with_context(|| {
                format!(
                    "the release build of {API_SERVER} kept running instead of refusing its \
                     authorization page in tier {tier} (DEC-2338 item 5)"
                )
            })?;
            release_api_refused(&output, matches!(tier, "dev" | "ci"))
                .with_context(|| format!("tier {tier}, page {page:?}"))?;
        }
    }
    Ok(())
}

/// Whether a release API's run is the refusal of its authorization page: exit 2, nothing on
/// standard output, and [`AUTHORIZE_URL_REFUSED`] alone on standard error. Where the tier is not
/// `lenient`, an unsigned binary is refused [`RELEASE_UNSIGNED`] before any setting is read, and
/// that refusal is accepted too.
fn release_api_refused(output: &std::process::Output, lenient: bool) -> Result<()> {
    let stderr = String::from_utf8_lossy(&output.stderr);
    let refusal_named = stderr == AUTHORIZE_URL_REFUSED || (!lenient && stderr == RELEASE_UNSIGNED);
    if output.status.code() != Some(2) || !refusal_named || !output.stdout.is_empty() {
        bail!(
            "the release build of {API_SERVER} must exit 2 writing only \
             {AUTHORIZE_URL_REFUSED:?} to standard error (DEC-2338 item 5); it exited {} with \
             stdout {:?} and stderr {stderr:?}",
            output.status,
            String::from_utf8_lossy(&output.stdout)
        );
    }
    Ok(())
}

/// DEC-2322: the release profile's debug assertions stay off. Refuses an environment that
/// sets `CARGO_PROFILE_RELEASE_DEBUG_ASSERTIONS` at all, or passes `debug-assertions` through
/// `RUSTFLAGS` or `CARGO_ENCODED_RUSTFLAGS`.
fn release_profile_untouched(var: impl Fn(&str) -> Option<String>) -> Result<()> {
    if var("CARGO_PROFILE_RELEASE_DEBUG_ASSERTIONS").is_some() {
        bail!(
            "CARGO_PROFILE_RELEASE_DEBUG_ASSERTIONS is set: the release build must keep debug \
             assertions off (DEC-2322)"
        );
    }
    for name in ["RUSTFLAGS", "CARGO_ENCODED_RUSTFLAGS"] {
        if var(name).is_some_and(|flags| flags.contains("debug-assertions")) {
            bail!(
                "{name} names debug-assertions: the release build must keep them off \
                 (DEC-2322)"
            );
        }
    }
    Ok(())
}

/// Whether a release exchange's run is DEC-2633 item 2's refusal: exit 2,
/// [`TOKEN_URL_IN_RELEASE`] alone on standard error, and nothing on standard output.
fn release_exchange_refused(output: &std::process::Output) -> Result<()> {
    let stderr = String::from_utf8_lossy(&output.stderr);
    if output.status.code() != Some(2)
        || stderr != TOKEN_URL_IN_RELEASE
        || !output.stdout.is_empty()
    {
        bail!(
            "the release build of {TOKEN_EXCHANGE} must exit 2 writing only \
             {TOKEN_URL_IN_RELEASE:?} to standard error (DEC-2633 item 2); it exited {} with \
             stdout {:?} and stderr {stderr:?}",
            output.status,
            String::from_utf8_lossy(&output.stdout)
        );
    }
    Ok(())
}

/// Builds `package`'s binary of the same name with `--release`, runs it with `args` and only
/// `envs` in its environment, and returns its output once it exits; `None` when it is still
/// running after [`STUB_RELEASE_WAITS`] waits of 20 ms, and it is killed.
fn released(
    package: &str,
    args: &[&str],
    envs: &[(&str, &str)],
) -> Result<Option<std::process::Output>> {
    sh(
        "cargo",
        &[
            "build",
            "--locked",
            "--release",
            "--package",
            package,
            "--bin",
            package,
        ],
    )?;
    let meta: serde_json::Value = serde_json::from_str(&output_in(
        Path::new("."),
        "cargo",
        &["metadata", "--format-version", "1", "--no-deps", "--locked"],
    )?)
    .context("parsing cargo metadata")?;
    let target = meta["target_directory"]
        .as_str()
        .context("cargo metadata names no target directory")?;
    let binary = Path::new(target).join("release").join(package);
    let shown: Vec<String> = envs.iter().map(|(k, v)| format!("{k}={v}")).collect();
    eprintln!(
        "    $ {} {} {}",
        shown.join(" "),
        binary.display(),
        args.join(" ")
    );
    let mut child = Command::new(&binary)
        .args(args)
        .env_clear()
        .envs(envs.iter().copied())
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .with_context(|| format!("starting {}", binary.display()))?;
    let mut exited = false;
    for _ in 0..STUB_RELEASE_WAITS {
        std::thread::sleep(std::time::Duration::from_millis(20));
        if child.try_wait()?.is_some() {
            exited = true;
            break;
        }
    }
    if !exited {
        child.kill()?;
    }
    let output = child.wait_with_output()?;
    Ok(exited.then_some(output))
}

/// Whether a release stub's run is DEC-2100 item 2's refusal: exit 2, [`STUB_NOT_BUILT`] alone on
/// standard error, and nothing on standard output.
fn release_stub_refused(output: &std::process::Output) -> Result<()> {
    let stderr = String::from_utf8_lossy(&output.stderr);
    if output.status.code() != Some(2) || stderr != STUB_NOT_BUILT || !output.stdout.is_empty() {
        bail!(
            "the release build of {STUB_ISSUER} must exit 2 writing only {STUB_NOT_BUILT:?} to \
             standard error (DEC-2100 item 2); it exited {} with stdout {:?} and stderr {stderr:?}",
            output.status,
            String::from_utf8_lossy(&output.stdout)
        );
    }
    Ok(())
}

/// The object store's conformance suite against a real S3-compatible store (E21-40, DEC-973),
/// run only when the selection holds `mandate-objectstore` (DEC-1190). `test` runs it too, but it
/// skips there unless `MANDATE_S3_URL` is set; here it must run.
fn objectstore() -> Result<()> {
    if env::var_os(S3_URL).is_none() {
        if env::var_os(S3_REQUIRED).is_some() {
            bail!("{S3_REQUIRED} is set but {S3_URL} is not");
        }
        eprintln!(
            "    objectstore: {S3_URL} is unset; skipping (see crates/mandate-objectstore/README.md)"
        );
        return Ok(());
    }
    let tested = selection()?.among(&S3_TESTED);
    if tested.is_empty() {
        eprintln!("    objectstore: no crate with object-store tests is affected (DEC-1190)");
        return Ok(());
    }
    let mut args = vec!["nextest", "run"];
    for package in &tested {
        args.extend(["--package", package]);
    }
    args.extend(["--locked", "--no-tests=pass"]);
    eprintln!("    $ {S3_REQUIRED}=1 cargo {}", args.join(" "));
    let status = Command::new("cargo")
        .args(args)
        .env(S3_REQUIRED, "1")
        .status()
        .context("starting `cargo nextest`")?;
    if !status.success() {
        bail!("the object store conformance suite failed with {status}");
    }
    Ok(())
}

/// The credential-free checks of `deploy/tofu/` (E21-56, DEC-2012 item 8, DEC-2013): `tofu fmt
/// -check`, tflint with its bundled ruleset, and in every module and environment root `tofu init
/// -backend=false` against the committed lock file, `tofu validate` and `tofu test`, whose mocked
/// providers are the policy check. Nothing here reads a credential or reaches a cloud API; the
/// providers come from the OpenTofu registry, by the lock file's hashes. The working directories
/// and the provider cache live under `target/tofu`, so the tree stays clean. It runs only when
/// the diff changes `deploy/tofu/` or selects everything (DEC-1190), and skips without the tools
/// unless [`TOFU_REQUIRED`] is set.
fn tofu_checks() -> Result<()> {
    if !selection()?.tofu {
        eprintln!("    tofu: nothing under {TOFU_DIR} changed (DEC-1190)");
        return Ok(());
    }
    let tofu_root = repo_root()?.join(TOFU_DIR);
    let mut forbidden = tofu_symlinks(&tofu_root)?;
    forbidden.extend(tofu_committed_working_dirs(&tofu_root)?);
    forbidden.extend(tofu_forbidden_blocks(&tofu_sources(&tofu_root)?));
    if !forbidden.is_empty() {
        bail!("tofu:\n  {}", forbidden.join("\n  "));
    }
    eprintln!(
        "    tofu: no provisioner, external or http data source, or remote module (DEC-2014)"
    );
    let installed = |tool: &str| {
        Command::new(tool)
            .arg("--version")
            .output()
            .is_ok_and(|out| out.status.success())
    };
    if !installed("tofu") || !installed("tflint") {
        if env::var_os(TOFU_REQUIRED).is_some() {
            bail!("{TOFU_REQUIRED} is set but tofu or tflint is not installed");
        }
        eprintln!(
            "    tofu: tofu or tflint is not installed; skipping (`bash .cursor/install.sh` installs both)"
        );
        return Ok(());
    }
    let root = repo_root()?;
    let tofu_dir = root.join(TOFU_DIR);
    let used = tofu_audit::used_types(&tofu_sources(&tofu_dir)?);
    let work = root.join("target").join("tofu");
    let cache = work.join("plugins");
    fs::create_dir_all(&cache).with_context(|| format!("creating {}", cache.display()))?;
    sh("tofu", &["fmt", "-check", "-recursive", "-diff", TOFU_DIR])?;
    let config = tofu_dir.join(".tflint.hcl");
    sh(
        "tflint",
        &[
            "--chdir",
            TOFU_DIR,
            "--recursive",
            "--config",
            &config.to_string_lossy(),
        ],
    )?;
    let mut covered = BTreeSet::new();
    for dir in tofu_roots(&tofu_dir)? {
        let name = dir
            .strip_prefix(&tofu_dir)
            .with_context(|| format!("{} is outside {TOFU_DIR}", dir.display()))?
            .to_string_lossy()
            .replace('/', "-");
        let data = work.join(&name);
        let chdir = format!("-chdir={}", dir.display());
        let tofu = |args: &[&str]| {
            let mut command = Command::new("tofu");
            command
                .args(args)
                .env("TF_DATA_DIR", &data)
                .env("TF_PLUGIN_CACHE_DIR", &cache)
                .env("TF_IN_AUTOMATION", "1");
            command
        };
        for args in [
            vec![
                chdir.as_str(),
                "init",
                "-backend=false",
                "-input=false",
                "-lockfile=readonly",
            ],
            vec![chdir.as_str(), "validate"],
            vec![chdir.as_str(), "test"],
        ] {
            eprintln!("    $ tofu {}", args.join(" "));
            let status = tofu(&args).status().context("starting `tofu`")?;
            if !status.success() {
                bail!("`tofu {}` failed with {status}", args.join(" "));
            }
            if args.get(1) == Some(&"init") && dir.starts_with(tofu_dir.join("modules")) {
                covered.extend(provider_schemas_mask(&tofu, &chdir, &used)?);
            }
        }
    }
    let unchecked: Vec<String> = used
        .iter()
        .filter(|(kind, name)| !(kind == "resource" && name == "terraform_data"))
        .filter(|used| !covered.contains(*used))
        .map(|(kind, name)| {
            format!("{kind} {name}: no module's provider schema was checked for it")
        })
        .collect();
    if !unchecked.is_empty() {
        bail!("tofu:\n  {}", unchecked.join("\n  "));
    }
    sh(
        "python3",
        &["deploy/tofu/modules/ci-runners/tests/manager_test.py"],
    )?;
    Ok(())
}

/// The audit's provider check (DEC-2030 item 6): in one initialised module, every
/// credential-named attribute of a type the tree uses whose provider the module installs is
/// `sensitive` in that provider's schema ([`tofu_audit::unmasked_attributes`]), so no plan diff
/// prints one. Returns the types it checked. Roots carry an `s3` backend, which `providers schema`
/// will not read uninitialised, so the modules, whose providers are the same pinned ones, stand in
/// for them, and the caller fails any used type no module checked. The placeholder passphrase
/// only satisfies configuration loading.
fn provider_schemas_mask(
    tofu: &dyn Fn(&[&str]) -> Command,
    chdir: &str,
    used: &BTreeSet<(String, String)>,
) -> Result<BTreeSet<(String, String)>> {
    eprintln!("    $ tofu {chdir} providers schema -json");
    let out = tofu(&[chdir, "providers", "schema", "-json"])
        .env(
            "TF_VAR_state_passphrase",
            "a-placeholder-the-schema-read-needs-and-encrypts-nothing-with",
        )
        .output()
        .context("starting `tofu`")?;
    if !out.status.success() {
        bail!(
            "`tofu {chdir} providers schema -json` failed: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        );
    }
    let schema: serde_json::Value =
        serde_json::from_slice(&out.stdout).context("tofu's provider schema is not JSON")?;
    let used_here: BTreeSet<(String, String)> = used
        .iter()
        .filter(|(_, name)| {
            name == "terraform_data"
                || schema
                    .get("provider_schemas")
                    .and_then(serde_json::Value::as_object)
                    .is_some_and(|providers| {
                        providers.keys().any(|source| {
                            name.split('_')
                                .next()
                                .is_some_and(|prefix| source.ends_with(&format!("/{prefix}")))
                        })
                    })
        })
        .cloned()
        .collect();
    let problems = tofu_audit::unmasked_attributes(&schema, &used_here);
    if !problems.is_empty() {
        bail!("tofu:\n  {}", problems.join("\n  "));
    }
    Ok(used_here)
}

/// OpenTofu's functions that read a file from disk: refused in `deploy/tofu/` as whole words,
/// anywhere, since what they load (a template, a script, a key) would reach OpenTofu and not the
/// raw scan, and HCL calls a function across a line break or a comment before its `(`
/// (DEC-2014 item 6). A prose use of the word is reworded.
const TOFU_FILE_FUNCTIONS: [&str; 12] = [
    "file",
    "fileexists",
    "fileset",
    "filebase64",
    "filebase64sha256",
    "filebase64sha512",
    "filemd5",
    "filesha1",
    "filesha256",
    "filesha512",
    "templatefile",
    "templatestring",
];

/// The provider sources `deploy/tofu/` may name (DEC-2012 item 4).
const TOFU_PROVIDER_SOURCES: [&str; 2] = ["digitalocean/digitalocean", "cloudflare/cloudflare"];

/// Whether `word` occurs in `text` at `at` as a whole word: no letter, digit or `_` on either side.
fn whole_word_at(text: &str, at: usize, word: &str) -> bool {
    let word_char = |c: char| c.is_ascii_alphanumeric() || c == '_';
    let before = text.get(..at).and_then(|head| head.chars().last());
    let after = text
        .get(at.saturating_add(word.len())..)
        .and_then(|tail| tail.chars().next());
    !before.is_some_and(word_char) && !after.is_some_and(word_char)
}

/// The byte offsets where `word` occurs in `text` as a whole word.
fn whole_words<'a>(text: &'a str, word: &'a str) -> impl Iterator<Item = usize> + 'a {
    text.match_indices(word)
        .map(|(at, _)| at)
        .filter(move |at| whole_word_at(text, *at, word))
}

/// Whether one line, its runs of whitespace collapsed, is a `source` this tree allows: a pinned
/// provider, a sibling module (`../<name>`), or, from a root, a module of `deploy/tofu/modules`
/// (`../../modules/<name>`), each name lower-case letters, digits, `_` and `-`.
fn allowed_source_line(line: &str) -> bool {
    let collapsed = line.split_whitespace().collect::<Vec<_>>().join(" ");
    let Some(value) = collapsed
        .strip_prefix("source = \"")
        .and_then(|rest| rest.strip_suffix('"'))
    else {
        return false;
    };
    let plain = |name: &str| {
        !name.is_empty()
            && name
                .chars()
                .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || matches!(c, '_' | '-'))
    };
    TOFU_PROVIDER_SOURCES.contains(&value)
        || value.strip_prefix("../").is_some_and(plain)
        || value.strip_prefix("../../modules/").is_some_and(plain)
}

/// Every reason `files` (each a path and its raw text) fail DEC-2014 item 6, read as raw text
/// with no parser: comments, strings and heredocs count the same as code, so no syntax can hide a
/// construct, and a false refusal is fixed by rewording. Refused, as whole words, case aside:
/// `provisioner` anywhere; `external` anywhere; `http` unless `://` follows it at once; and
/// `source` on any line that is not exactly an allowed `source = "..."` ([`allowed_source_line`]).
/// A JSON file (`.tf.json` and the like) is refused outright, since `deploy/tofu/` holds none.
fn tofu_forbidden_blocks(files: &[(String, String)]) -> Vec<String> {
    let mut problems = Vec::new();
    for (path, text) in files {
        if path.ends_with(".json") {
            problems.push(format!(
                "{path}: deploy/tofu holds no JSON-syntax file, which the scan does not read \
                 (DEC-2014)"
            ));
            continue;
        }
        for (number, raw) in (1_usize..).zip(text.lines()) {
            let line = raw.to_ascii_lowercase();
            let mut refuse = |why: &str| {
                problems.push(format!("{path}:{number}: {why} (DEC-2014)"));
            };
            if raw.contains('\\') {
                refuse("holds a backslash, an escape the scan would not decode");
            }
            if whole_words(&line, "provisioner").next().is_some() {
                refuse("names `provisioner`, which deploy/tofu never may");
            }
            if whole_words(&line, "external").next().is_some() {
                refuse("names `external`, the data source deploy/tofu never may use");
            }
            if whole_words(&line, "http").any(|at| {
                !line
                    .get(at.saturating_add(4)..)
                    .is_some_and(|t| t.starts_with("://"))
            }) {
                refuse(
                    "names `http` other than in a URL, the data source deploy/tofu never may use",
                );
            }
            if TOFU_FILE_FUNCTIONS
                .iter()
                .any(|name| whole_words(&line, name).next().is_some())
            {
                refuse(
                    "names a function that reads a file, as a whole word wherever it appears, \
                     since a line break or a comment between the name and its `(` still calls it",
                );
            }
            if whole_words(&line, "terraform_remote_state")
                .next()
                .is_some()
            {
                refuse(
                    "names `terraform_remote_state`, which reads another state deploy/tofu never may",
                );
            }
            if whole_words(&line, "source").next().is_some() && !allowed_source_line(&line) {
                refuse(
                    "names `source` on a line that is not a pinned provider or a module of this \
                     tree",
                );
            }
        }
    }
    problems
}

/// Every symlink under `dir`, real `.terraform` working directories aside: a link could point the
/// raw scan at one file and OpenTofu at another, so `deploy/tofu/` holds none (DEC-2014 item 6).
/// A `.terraform` that is itself a link is refused like any other, since the raw scan skips what
/// it holds. Whether a `.terraform` is committed is [`tofu_committed_working_dirs`]'s.
fn tofu_symlinks(dir: &Path) -> Result<Vec<String>> {
    let mut links = Vec::new();
    let mut pending = vec![dir.to_path_buf()];
    while let Some(dir) = pending.pop() {
        for entry in fs::read_dir(&dir).with_context(|| format!("reading {}", dir.display()))? {
            let path = entry?.path();
            let kind = fs::symlink_metadata(&path)
                .with_context(|| format!("reading {}", path.display()))?
                .file_type();
            if kind.is_dir() && path.file_name().is_some_and(|name| name == ".terraform") {
                continue;
            }
            if kind.is_symlink() {
                links.push(format!(
                    "{}: a symlink, which deploy/tofu never holds (DEC-2014)",
                    path.display()
                ));
            } else if kind.is_dir() {
                pending.push(path);
            }
        }
    }
    links.sort();
    Ok(links)
}

/// Every path git tracks under `dir` that sits in a `.terraform` working directory: the raw scan
/// skips those directories, so one committed would carry configuration past it (DEC-2014 item 6).
fn tofu_committed_working_dirs(dir: &Path) -> Result<Vec<String>> {
    let out = Command::new("git")
        .arg("-C")
        .arg(dir)
        .args(["ls-files", "-z", "--", "."])
        .output()
        .context("starting `git ls-files`")?;
    if !out.status.success() {
        bail!(
            "`git ls-files` under {} failed: {}",
            dir.display(),
            String::from_utf8_lossy(&out.stderr).trim()
        );
    }
    Ok(committed_working_dirs(&String::from_utf8_lossy(
        &out.stdout,
    )))
}

/// The paths of a NUL-separated `git ls-files` listing that sit in a `.terraform` directory.
fn committed_working_dirs(listing: &str) -> Vec<String> {
    listing
        .split('\0')
        .filter(|path| path.split('/').any(|part| part == ".terraform"))
        .map(|path| {
            format!("{path}: committed inside a .terraform working directory, which the scan skips (DEC-2014)")
        })
        .collect()
}

/// Every file under `dir` the raw scan reads, with its text: `.tf`, `.tofu`, `.hcl` and `.json`,
/// outside `.terraform` working directories and OpenTofu's own lock files, which it writes.
fn tofu_sources(dir: &Path) -> Result<Vec<(String, String)>> {
    files_by_extension(dir, &["tf", "tofu", "hcl", "json"])?
        .into_iter()
        .filter(|path| {
            !path
                .components()
                .any(|part| part.as_os_str() == ".terraform")
                && path
                    .file_name()
                    .is_none_or(|name| name != ".terraform.lock.hcl")
        })
        .map(|path| {
            let text =
                fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
            Ok((path.display().to_string(), text))
        })
        .collect()
}

/// Every OpenTofu root under `tofu_dir` that the checks run in: each directory directly under
/// `modules/` and `environments/` holding a `.tf` file, in path order. A module with no root of
/// its own, or a directory the checks would miss, fails here rather than passing unchecked.
fn tofu_roots(tofu_dir: &Path) -> Result<Vec<PathBuf>> {
    let mut roots = Vec::new();
    for group in ["modules", "environments"] {
        let parent = tofu_dir.join(group);
        for entry in
            fs::read_dir(&parent).with_context(|| format!("reading {}", parent.display()))?
        {
            let dir = entry?.path();
            if !dir.is_dir() {
                continue;
            }
            let has_tf = fs::read_dir(&dir)?
                .filter_map(Result::ok)
                .any(|file| file.path().extension().is_some_and(|ext| ext == "tf"));
            if !has_tf {
                bail!("{} holds no .tf file", dir.display());
            }
            roots.push(dir);
        }
    }
    roots.sort();
    if roots.is_empty() {
        bail!("{} holds no OpenTofu root", tofu_dir.display());
    }
    Ok(roots)
}

/// The workflow that alone plans and applies the hosted environments (E21-56, DEC-2014).
const INFRA_WORKFLOW: &str = ".github/workflows/infra.yml";
/// The one command `infra.yml`'s secret-holding step runs: the binary an earlier step built with
/// no secret in its environment, so no build script runs beside one.
const INFRA_RUN: &str = "target/debug/xtask infra";
/// The command `infra.yml`'s last step runs, once the build succeeded and however the step before
/// it ended, with only the DigitalOcean token: the same built binary.
const INFRA_CLOSE: &str = "target/debug/xtask infra close";
/// The condition that last step runs under, exactly.
const INFRA_CLOSE_IF: &str = "      - if: always() && steps.build.outcome == 'success'";
/// The only arguments the closed world lets a workflow run the built xtask binary with rather than
/// through cargo: [`INFRA_RUN`]'s and [`INFRA_CLOSE`]'s, which an earlier step of the same job
/// built from the checkout with `cargo build --locked --package xtask --package mandate-cli`.
const INFRA_BINARY_ARGS: [&[&str]; 2] = [&["infra"], &["infra", "close"]];
/// The only secrets [`INFRA_CLOSE`]'s step may read: the DigitalOcean token, to delete the run's
/// Spaces key and close the window, and the founder's CIDRs, which the closed window keeps.
const INFRA_CLOSE_SECRETS: [&str; 2] = ["DIGITAL_OCEAN_API_KEY", "KUBE_API_ALLOWED_CIDRS"];
/// The secrets that step reads, each from the environment `infra-<environment>` the founder
/// approves; no other workflow, job or step may name one (ES-12, DEC-2014). The Spaces key is
/// minted per run, never stored (DEC-2030 item 4). The Cloudflare token goes to OpenTofu as a
/// variable under a `CF_` name, since `web/scripts/workers.mjs` keeps every `CLOUDFLARE_` name
/// to `web-deploy.yml`'s deploy step (DEC-1005 item 2); the account id is read from Cloudflare,
/// never configured (DEC-2030 item 1). Production's Access emails and the founder's CIDRs are
/// secrets, since GitHub prints a variable in a step's environment in the public log (DEC-2030
/// items 2 and 6). The model provider's key, staging's alone, goes to the vault on the CLI's
/// stdin under a `MANDATE_` name, never `TF_VAR_`, so OpenTofu never reads it (DEC-2630). So does
/// the founder's identity-provider subject, staging's alone, to the built CLI's stdin (DEC-2114),
/// and the Alpaca OAuth client secret, staging's alone, to the vault like the model key (DEC-2636),
/// and the news reader's Alpaca paper data key id and secret, likewise (DEC-2277).
const INFRA_SECRETS: [&str; 10] = [
    "DIGITAL_OCEAN_API_KEY",
    "CF_INFRA_API_TOKEN",
    "TOFU_STATE_PASSPHRASE",
    "ACCESS_ALLOWED_EMAILS",
    "KUBE_API_ALLOWED_CIDRS",
    "OPENROUTER_API_KEY",
    "FOUNDER_OIDC_SUBJECT",
    "ALPACA_OAUTH_CLIENT_SECRET",
    "ALPACA_NEWS_KEY_ID",
    "ALPACA_NEWS_SECRET",
];
/// The infra step's environment variables holding the news reader's Alpaca paper data key id and
/// secret (DEC-2277).
const NEWS_KEY_ID_VAR: &str = "MANDATE_ALPACA_NEWS_KEY_ID";
const NEWS_SECRET_VAR: &str = "MANDATE_ALPACA_NEWS_SECRET";
/// The infra step's environment variable holding the Alpaca OAuth client secret (DEC-2636).
const ALPACA_CLIENT_SECRET_VAR: &str = "MANDATE_ALPACA_OAUTH_CLIENT_SECRET";

/// The list inputs `infra.yml` hands OpenTofu as JSON, which `infra` leaves out of `tofu`'s
/// environment when blank or empty, so a root with a default takes it and a root without one
/// fails on the missing variable by name, never on `""`, which is no list (DEC-2030 item 3).
const INFRA_LIST_INPUTS: [&str; 2] = [
    "TF_VAR_kube_api_allowed_addresses",
    "TF_VAR_access_allowed_emails",
];

/// Whether `value`, a JSON list as `infra.yml` hands it on, names nothing: unset, blank, or an
/// empty list.
fn names_nothing(value: Option<&str>) -> bool {
    value.is_none_or(|value| {
        value
            .chars()
            .all(|c| c.is_whitespace() || c == '[' || c == ']')
    })
}
/// The environment variables `infra.yml` hands `cargo xtask infra`: which environment and
/// whether to apply, from the dispatch's choice inputs.
const INFRA_ENVIRONMENT_ENV: &str = "MANDATE_INFRA_ENVIRONMENT";
const INFRA_ACTION_ENV: &str = "MANDATE_INFRA_ACTION";

/// The `tofu` commands, in order, that `action` runs for `environment` (E21-56, DEC-2014), each
/// with its arguments, in the environment's root: init against the remote state and the committed
/// lock file, a plan saved to `plan_file` (encrypted, DEC-2012 item 3), and for `apply` that
/// same saved plan applied, so what is applied is exactly what the log showed.
fn infra_commands(environment: &str, action: &str, plan_file: &str) -> Result<Vec<Vec<String>>> {
    if !matches!(environment, "staging" | "production") {
        bail!("{INFRA_ENVIRONMENT_ENV} must be staging or production, not `{environment}`");
    }
    if !matches!(action, "preflight" | "plan" | "apply") {
        bail!("{INFRA_ACTION_ENV} must be preflight, plan or apply, not `{action}`");
    }
    if action == "preflight" {
        return Ok(Vec::new());
    }
    let chdir = format!("-chdir={TOFU_DIR}environments/{environment}");
    let mut commands = vec![
        vec![
            chdir.clone(),
            "init".to_owned(),
            "-input=false".to_owned(),
            "-no-color".to_owned(),
            "-lockfile=readonly".to_owned(),
        ],
        vec![
            chdir.clone(),
            "plan".to_owned(),
            "-input=false".to_owned(),
            "-no-color".to_owned(),
            "-compact-warnings".to_owned(),
            format!("-out={plan_file}"),
        ],
    ];
    if action == "apply" {
        commands.push(vec![
            chdir,
            "apply".to_owned(),
            "-input=false".to_owned(),
            "-no-color".to_owned(),
            "-compact-warnings".to_owned(),
            plan_file.to_owned(),
        ]);
    }
    Ok(commands)
}

/// `cargo xtask infra` (E21-56, DEC-2014): checks, plans, or plans and applies, one hosted
/// environment. It refuses to run anywhere but a GitHub Actions run on `main`, so the only place it
/// reaches a cloud account is `infra.yml`'s job, which the founder approves; agents never run it
/// (AGENTS.md rule 8). Every action starts with the preflight, which prints what is missing by
/// name and stops before `init` if anything is (DEC-2030 item 5). `plan` and `apply` then run with
/// the Spaces key the preflight minted, deleted again however they end (DEC-2030 item 4).
fn infra() -> Result<()> {
    let actions = env::var("GITHUB_ACTIONS").unwrap_or_default();
    let reference = env::var("GITHUB_REF").unwrap_or_default();
    if actions != "true" || reference != "refs/heads/main" {
        bail!(
            "infra runs only in {INFRA_WORKFLOW}'s job on main (GITHUB_ACTIONS=true, \
             GITHUB_REF=refs/heads/main), never by hand (E21-56, DEC-2014)"
        );
    }
    let environment = env::var(INFRA_ENVIRONMENT_ENV).unwrap_or_default();
    let action = env::var(INFRA_ACTION_ENV).unwrap_or_default();
    let run = env::var("GITHUB_RUN_ID").unwrap_or_default();
    if run.is_empty() || !run.chars().all(|c| c.is_ascii_digit()) {
        bail!("GITHUB_RUN_ID must be the run's number, which names its Spaces key");
    }
    let named = env::var(INFRA_SHA_ENV).unwrap_or_default();
    let sha = run_commit(
        &action,
        &named,
        &env::var("GITHUB_SHA").unwrap_or_default(),
        &head_commit()?,
    )?;
    eprintln!("==> infra {action} of {environment} at commit {sha}");
    if named.is_empty() {
        eprintln!(
            "    no sha was given, so this run uses the commit main was at when it started; to \
             apply this plan, dispatch apply with sha={sha} (DEC-2042)"
        );
    }
    let work = repo_root()?.join("target").join("tofu");
    fs::create_dir_all(&work).with_context(|| format!("creating {}", work.display()))?;
    let plan_file = work.join(format!("{environment}.tfplan"));
    let commands = infra_commands(&environment, &action, &plan_file.to_string_lossy())?;
    for name in [infra_preflight::KUBE_CIDRS_ENV, infra_preflight::EMAILS_ENV] {
        for value in tofu_audit::list_items(&env::var(name).unwrap_or_default()) {
            mask::add_mask(&value);
        }
    }
    let read = |name: &str| env::var(name).ok();
    let preflight = infra_preflight::preflight(&environment, &run, !commands.is_empty(), &read)?;
    eprint!("{}", preflight.checklist.render(&environment));
    let mut window = None;
    let outcome = if preflight.checklist.complete() {
        match opens_window(&environment, &action)
            .then(|| infra_window::open_window(&infra_window::Curl))
            .transpose()
        {
            Ok(opened) => {
                window = opened;
                run_tofu(
                    &commands,
                    preflight.key.key(),
                    &sha,
                    &plan_file,
                    window.as_deref(),
                    &run,
                )
            }
            Err(error) => Err(error),
        }
    } else {
        Err(anyhow::anyhow!(
            "infra preflight: each MISSING line above is a step in deploy/tofu/README.md; nothing \
             was planned"
        ))
    };
    let closed = window.is_some().then(|| {
        let token = env::var("DIGITALOCEAN_TOKEN").unwrap_or_default();
        let founder = env::var(infra_preflight::KUBE_CIDRS_ENV).ok();
        infra_window::close_window(
            &infra_window::Curl,
            &token,
            &environment,
            founder.as_deref(),
        )
    });
    let applied = outcome.is_ok();
    let keys = match preflight.key.release() {
        Ok(true) => Ok(()),
        Ok(false) => Err(anyhow::anyhow!(
            "this run's Spaces key was not deleted; `infra close` and the next run of \
             {environment} delete it (DEC-2030 item 4)"
        )),
        Err(error) => Err(error),
    };
    settle(outcome, closed, applied, keys)
}

/// How a run that may have opened a window ends (the review of #1771, B1 and B2): the window's
/// close and the Spaces key's deletion are each attempted and reported, whatever came before, and
/// the first error is returned. A close reports the window closed only when the cluster was read
/// back admitting exactly the closed addresses, or had no such cluster when none was expected;
/// `cluster_expected` makes a missing cluster an error, as after a successful apply.
fn settle(
    outcome: Result<()>,
    closed: Option<Result<infra_window::Window>>,
    cluster_expected: bool,
    keys: Result<()>,
) -> Result<()> {
    let window = match closed {
        None => Ok(()),
        Some(Ok(infra_window::Window::Closed | infra_window::Window::AlreadyClosed)) => {
            eprintln!("    the control plane's window is closed (DEC-2028 item 3)");
            Ok(())
        }
        Some(Ok(infra_window::Window::NoCluster)) if !cluster_expected => {
            eprintln!("    no cluster exists, so no window is open (DEC-2028 item 3)");
            Ok(())
        }
        Some(Ok(infra_window::Window::NoCluster)) => Err(anyhow::anyhow!(
            "the apply succeeded but DigitalOcean lists no such cluster, so the window's close \
             could not be confirmed"
        )),
        Some(Err(error)) => Err(error),
    }
    .context("the control plane's window may be open; `infra close` and the next run close it");
    let mut first = None;
    for result in [outcome, window, keys] {
        if let Err(error) = result {
            if first.is_some() {
                eprintln!("    also: {error:#}");
            } else {
                first = Some(error);
            }
        }
    }
    first.map_or(Ok(()), Err)
}

/// The dispatch's `sha` input, which the founder approves the run for (the audit's item 5).
const INFRA_SHA_ENV: &str = "MANDATE_INFRA_SHA";

/// The commit `git` has checked out.
fn head_commit() -> Result<String> {
    let out = founding::without_step_secrets(&mut Command::new("git"))
        .args(["rev-parse", "HEAD"])
        .output()
        .context("starting `git`")?;
    if !out.status.success() {
        bail!("`git rev-parse HEAD` failed");
    }
    Ok(String::from_utf8_lossy(&out.stdout).trim().to_owned())
}

/// Refuses a run unless `sha`, the commit the founder named when dispatching, is a full commit and
/// is both the run's commit and the one checked out, so an approval binds to a reviewed commit and
/// never to whatever `main` became while the run waited for it.
fn reviewed_commit(sha: &str, run_sha: &str, head: &str) -> Result<()> {
    if sha.len() != 40
        || !sha
            .chars()
            .all(|c| c.is_ascii_digit() || ('a'..='f').contains(&c))
    {
        bail!("{INFRA_SHA_ENV} must be the full 40-character commit you reviewed");
    }
    if sha != run_sha || sha != head {
        bail!(
            "the dispatch names commit {sha}, but the run is at {run_sha} with {head} checked \
             out: GitHub fixes a run's commit when it is dispatched, so dispatch again naming \
             the commit main is at"
        );
    }
    Ok(())
}

/// The commit a run proceeds at (DEC-2042). With `sha` given, [`reviewed_commit`] holds: it must
/// be the run's commit and the checkout. With `sha` empty, `preflight` and `plan` proceed at the
/// checkout, once it is the run's commit and a full commit, since main moves between the founder
/// reading a commit and dispatching; `apply` never does, so an apply still binds to the commit the
/// founder named. An action other than those three is refused first, whatever `sha` is.
fn run_commit(action: &str, sha: &str, run_sha: &str, head: &str) -> Result<String> {
    if !matches!(action, "preflight" | "plan" | "apply") {
        bail!("no infra action {action:?} (DEC-2042)");
    }
    if !sha.is_empty() {
        reviewed_commit(sha, run_sha, head)?;
        return Ok(sha.to_owned());
    }
    if action == "apply" {
        bail!(
            "apply needs {INFRA_SHA_ENV}, the full commit you reviewed, so the approval binds to \
             it; plan first and dispatch apply naming the commit the plan printed (DEC-2042)"
        );
    }
    reviewed_commit(head, run_sha, head).context(
        "no sha was given, so the run proceeds at the checkout, which must be the run's full \
         commit (DEC-2042)",
    )?;
    Ok(head.to_owned())
}

/// The paths a change to which changes what `infra.yml` does: the OpenTofu tree, the workflow, and
/// everything the secret-holding binary is built from.
const INFRA_PATHS: [&str; 7] = [
    TOFU_DIR,
    INFRA_WORKFLOW,
    "xtask/",
    "Cargo.lock",
    "Cargo.toml",
    "rust-toolchain.toml",
    ".cargo/",
];

/// `cargo xtask infra close` (DEC-2030 item 4, DEC-2028 item 3): `infra.yml`'s last step, which
/// runs `if: always()` with only the DigitalOcean token and the founder's CIDRs, closes staging's
/// window first and then deletes every Spaces key this environment's runs minted, each attempted
/// whatever the other did, so a run killed before its own guard ran leaves neither. Like `infra`,
/// it runs only in that job on `main`.
fn infra_close() -> Result<()> {
    let actions = env::var("GITHUB_ACTIONS").unwrap_or_default();
    let reference = env::var("GITHUB_REF").unwrap_or_default();
    if actions != "true" || reference != "refs/heads/main" {
        bail!("infra close runs only in {INFRA_WORKFLOW}'s job on main, never by hand (DEC-2030)");
    }
    let environment = env::var(INFRA_ENVIRONMENT_ENV).unwrap_or_default();
    let token = env::var("DIGITALOCEAN_TOKEN").unwrap_or_default();
    if token.trim().is_empty() {
        eprintln!("    infra close: DIGITAL_OCEAN_API_KEY is not set, so no key was minted");
        return Ok(());
    }
    let closed = opens_window(&environment, "apply").then(|| {
        let founder = env::var(infra_preflight::KUBE_CIDRS_ENV).ok();
        for value in tofu_audit::list_items(founder.as_deref().unwrap_or_default()) {
            mask::add_mask(&value);
        }
        infra_window::close_window(
            &infra_window::Curl,
            &token,
            &environment,
            founder.as_deref(),
        )
    });
    let keys = infra_preflight::close(&environment, &token).map(|deleted| {
        eprintln!(
            "    infra close: deleted {deleted} Spaces key(s) this environment's runs minted"
        );
    });
    settle(Ok(()), closed, false, keys)
}

/// Whether `action` on `environment` opens the control plane to its own runner and bootstraps
/// the cluster (DEC-2028): an `apply` on staging, the one environment lane GO's bootstrap runs in
/// from CI today.
fn opens_window(environment: &str, action: &str) -> bool {
    environment == "staging" && action == "apply"
}

/// Lane GO's bootstrap after staging's apply (DEC-2018 item 7, DEC-2028), then its verify
/// (DEC-2050), which reads staging until it is up and fails the run if it never is: the workload secrets
/// from OpenTofu's outputs, each wrapped in a [`gitops::Secret`], which masks it, the moment it is
/// read; a kubeconfig that expires in 900 seconds, at mode 0600 in `$RUNNER_TEMP` and deleted
/// however the bootstrap ends; and the bootstrap itself, which confirms the context first.
fn bootstrap_staging(tofu: &dyn Fn(&[String]) -> Command, chdir: &str, run: &str) -> Result<()> {
    let output = |name: &str| -> Result<String> {
        let out = tofu(&[
            chdir.to_owned(),
            "output".to_owned(),
            "-no-color".to_owned(),
            "-raw".to_owned(),
            name.to_owned(),
        ])
        .output()
        .context("starting `tofu`")?;
        if !out.status.success() {
            bail!("`tofu output {name}` failed");
        }
        String::from_utf8(out.stdout)
            .ok()
            .with_context(|| format!("`tofu output {name}` is not UTF-8"))
    };
    let secrets = gitops::WorkloadSecrets {
        archive_access_key_id: gitops::Secret::new(output("archive_access_key_id")?),
        archive_secret_access_key: gitops::Secret::new(output("archive_secret_access_key")?),
        tunnel_token: gitops::Secret::new(output("tunnel_token")?),
        archive_endpoint: gitops::Secret::new(output("archive_endpoint")?),
    };
    let cluster_id = output("cluster_id")?;
    let connections = vault_provision::staging_connections(&repo_root()?)?;
    let cli = repo_root()?.join(vault_provision::CLI);
    ensure!(
        cli.is_file(),
        "{} is not built: infra.yml's build step builds it",
        vault_provision::CLI
    );
    let model_key = env::var("MANDATE_OPENROUTER_API_KEY").unwrap_or_default();
    if !model_key.is_empty() {
        mask::add_mask(&model_key);
    }
    let alpaca_client_secret = env::var(ALPACA_CLIENT_SECRET_VAR).unwrap_or_default();
    if !alpaca_client_secret.is_empty() {
        mask::add_mask(&alpaca_client_secret);
    }
    let news_key = vault_provision::news_data_key(
        &env::var(NEWS_KEY_ID_VAR).unwrap_or_default(),
        &env::var(NEWS_SECRET_VAR).unwrap_or_default(),
    )?;
    if !news_key.is_empty() {
        mask::add_mask(&news_key);
    }
    let founder_subject = env::var(founding::SUBJECT_VAR).unwrap_or_default();
    if !founder_subject.is_empty() {
        mask::add_mask(&founder_subject);
    }
    let founder = founding::staging_founder(&repo_root()?)?;
    let token = env::var("DIGITALOCEAN_TOKEN").unwrap_or_default();
    let temp = env::var("RUNNER_TEMP").context("RUNNER_TEMP is not set")?;
    let (_, context) = infra_window::cluster_names("staging");
    let kubeconfig = infra_window::fetch_kubeconfig(
        &infra_window::Curl,
        &token,
        cluster_id.trim(),
        &context,
        Path::new(&temp),
        run,
    )?;
    gitops::bootstrap_from_infra(
        &repo_root()?,
        gitops::Environment::Staging,
        kubeconfig.path(),
        &context,
        &secrets,
    )?;
    let in_cluster = |args: &[&str], stdin: Option<&str>| -> Result<(bool, String)> {
        let mut child = gitops::tool("kubectl")
            .args(["--v=0", "--kubeconfig"])
            .arg(kubeconfig.path())
            .args(["--context", &context])
            .args(args)
            .stdin(if stdin.is_some() {
                Stdio::piped()
            } else {
                Stdio::null()
            })
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
            .context("starting kubectl")?;
        if let Some(text) = stdin {
            child
                .stdin
                .take()
                .context("kubectl's stdin")?
                .write_all(text.as_bytes())?;
        }
        let out = child.wait_with_output().context("waiting for kubectl")?;
        Ok((
            out.status.success(),
            String::from_utf8(out.stdout).context("kubectl printed non-UTF-8")?,
        ))
    };
    let new_key = || -> Result<String> {
        let mut key = [0_u8; 32];
        fs::File::open("/dev/urandom")
            .and_then(|mut random| random.read_exact(&mut key))
            .context("reading /dev/urandom")?;
        Ok(key.iter().map(|byte| format!("{byte:02x}")).collect())
    };
    let words = vault_init::vault_init(&vault_init::Steps {
        kubectl: &in_cluster,
        new_key: &new_key,
        pause: &|| std::thread::sleep(Duration::from_secs(5)),
    })?;
    for word in words {
        eprintln!("    vault-init: {word} (DEC-2052)");
    }
    let base = || {
        let mut command = gitops::tool("kubectl");
        command
            .args(["--v=0", "--kubeconfig"])
            .arg(kubeconfig.path())
            .args(["--context", &context]);
        command
    };
    let listed: Vec<&str> = connections.iter().map(String::as_str).collect();
    let in_vault_cli = |command: &[String], stdin: &str| {
        vault_provision::run_cli(&base, &in_cluster, &cli, Path::new(&temp), command, stdin)
    };
    let words = vault_provision::vault_provision(
        &vault_provision::Steps {
            kubectl: &in_cluster,
            provision: &|command, stdin| in_vault_cli(command, stdin),
            put: &|secret, stdin| in_vault_cli(&vault_provision::put_command(secret), stdin),
            pause: &std::thread::sleep,
        },
        &listed,
        &model_key,
        &alpaca_client_secret,
        &news_key,
    )?;
    for word in words {
        eprintln!("    vault-provision: {word} (DEC-2630)");
    }
    let linked = founding::link_founder(
        &founding::Steps {
            kubectl: &in_cluster,
            mandate: &|args, stdin| founding::run_mandate(&cli, args, stdin),
            scratch: Path::new(&temp),
        },
        &founder,
        &founder_subject,
    )?;
    eprintln!("    founding: {linked} (DEC-2114)");
    let account = output("cloudflare_account_id")?;
    mask::add_mask(account.trim());
    let (tunnel_id, api_hostname) = (output("tunnel_id")?, output("api_hostname")?);
    mask::add_mask(tunnel_id.trim());
    let get = |args: &[&str]| -> Result<String> {
        let out = gitops::tool("kubectl")
            .args(["--v=0", "--kubeconfig"])
            .arg(kubeconfig.path())
            .args(["--context", &context, "--request-timeout=30s"])
            .args(args)
            .output()
            .context("starting kubectl")?;
        ensure!(out.status.success(), "kubectl get failed");
        String::from_utf8(out.stdout).context("kubectl printed non-UTF-8")
    };
    let cloudflare_token = env::var("TF_VAR_cloudflare_api_token").unwrap_or_default();
    let checklist = infra_verify::verify(
        &get,
        &infra_window::Curl,
        &infra_verify::Edge {
            cloudflare_token: &cloudflare_token,
            account: account.trim(),
            tunnel_id: tunnel_id.trim(),
            api_hostname: api_hostname.trim(),
        },
    )?;
    eprint!("{}", checklist.render_titled("infra verify (staging)"));
    ensure!(
        checklist.complete(),
        "staging is not up after {} seconds: each MISSING line above names what is not (DEC-2050)",
        infra_verify::SECONDS
    );
    Ok(())
}

/// Runs each `tofu` command in turn, with the run's Spaces key in the child's environment alone,
/// as both of the names the provider and the backend read, and `sha` as the commit the plan
/// records. A blank or empty `KUBE_API_ALLOWED_CIDRS` is left out, so staging's root takes its
/// empty default, and so is a blank `ACCESS_ALLOWED_EMAILS`, which only production's root
/// declares. The public log gets no `tofu` output (DEC-2014 item 4, the audit's item 1): each command's
/// output is captured, and only a failure's diagnostics, which OpenTofu redacts for every
/// sensitive value, are printed. After `init` the log lists what changed since the commit state
/// last applied; after `plan`, the saved plan's addresses and actions alone.
fn run_tofu(
    commands: &[Vec<String>],
    key: Option<&infra_preflight::SpacesKey>,
    sha: &str,
    plan_file: &Path,
    window: Option<&str>,
    run: &str,
) -> Result<()> {
    let tofu = |args: &[String]| {
        let mut command = Command::new("tofu");
        founding::without_step_secrets(&mut command)
            .args(args)
            .env("TF_IN_AUTOMATION", "1")
            .env("TF_VAR_commit_sha", sha);
        if let Some(window) = window {
            command.env("TF_VAR_bootstrap_runner_cidr", window);
        }
        if let Some(key) = key {
            for name in ["SPACES_ACCESS_KEY_ID", "AWS_ACCESS_KEY_ID"] {
                command.env(name, &key.access_key);
            }
            for name in ["SPACES_SECRET_ACCESS_KEY", "AWS_SECRET_ACCESS_KEY"] {
                command.env(name, &key.secret_key);
            }
        }
        for name in INFRA_LIST_INPUTS {
            if names_nothing(env::var(name).ok().as_deref()) {
                command.env_remove(name);
            }
        }
        command
    };
    for args in commands {
        eprintln!("    $ tofu {}", args.join(" "));
        let out = tofu(args).output().context("starting `tofu`")?;
        if !out.status.success() {
            eprintln!("{}", String::from_utf8_lossy(&out.stderr).trim());
            bail!("`tofu {}` failed with {}", args.join(" "), out.status);
        }
        let chdir = args.first().cloned().unwrap_or_default();
        match args.get(1).map(String::as_str) {
            Some("init") => changed_since_applied(&tofu, &chdir, sha)?,
            Some("plan") => {
                let shown = tofu(&[
                    chdir,
                    "show".to_owned(),
                    "-json".to_owned(),
                    plan_file.to_string_lossy().into_owned(),
                ])
                .output()
                .context("starting `tofu`")?;
                if !shown.status.success() {
                    bail!("`tofu show -json` of the saved plan failed");
                }
                let plan: serde_json::Value = serde_json::from_slice(&shown.stdout)
                    .context("the saved plan's JSON could not be read")?;
                eprintln!("    the plan, by address (values stay out of the log):");
                for line in tofu_audit::plan_summary(&plan) {
                    eprintln!("      {line}");
                }
            }
            Some("apply") => {
                eprintln!("    applied exactly the plan above");
                if window.is_some() {
                    bootstrap_staging(&tofu, &chdir, run)?;
                    eprintln!("    the cluster is bootstrapped (lane GO, DEC-2018)");
                }
            }
            _ => {}
        }
    }
    Ok(())
}

/// Prints the files under [`INFRA_PATHS`] that changed between the commit this environment's
/// state last applied and `sha`, so the founder approves a diff they can see. A first run, or a
/// commit the checkout does not hold, says so instead.
fn changed_since_applied(
    tofu: &dyn Fn(&[String]) -> Command,
    chdir: &str,
    sha: &str,
) -> Result<()> {
    let out = tofu(&[
        chdir.to_owned(),
        "output".to_owned(),
        "-no-color".to_owned(),
        "-raw".to_owned(),
        "applied_commit".to_owned(),
    ])
    .output()
    .context("starting `tofu`")?;
    let applied = String::from_utf8_lossy(&out.stdout).trim().to_owned();
    if !out.status.success()
        || applied.len() != 40
        || !applied.chars().all(|c| c.is_ascii_hexdigit())
    {
        eprintln!("    no applied commit in state yet: this is the environment's first apply");
        return Ok(());
    }
    if applied == sha {
        eprintln!("    state was last applied at this same commit");
        return Ok(());
    }
    let diff = founding::without_step_secrets(&mut Command::new("git"))
        .args(["diff", "--name-status", &applied, sha, "--"])
        .args(INFRA_PATHS)
        .output()
        .context("starting `git`")?;
    if !diff.status.success() {
        eprintln!("    state was last applied at {applied}, which this checkout does not hold");
        return Ok(());
    }
    eprintln!("    changed since the last apply ({applied}):");
    for line in String::from_utf8_lossy(&diff.stdout).lines() {
        eprintln!("      {line}");
    }
    Ok(())
}

/// [`infra_workflow_problems`] over the repository at `root`'s workflows, failing on any.
fn infra_workflow_in(root: &Path) -> Result<()> {
    eprintln!("    infra-workflow: checking {INFRA_WORKFLOW}'s shape and who names its secrets");
    let dir = root.join(".github/workflows");
    let mut files = Vec::new();
    if dir.is_dir() {
        for path in files_by_extension(&dir, &["yml", "yaml"])? {
            let text =
                fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
            let relative = path
                .strip_prefix(root)
                .unwrap_or(&path)
                .to_string_lossy()
                .into_owned();
            files.push(CiFile {
                path: relative,
                text,
            });
        }
    }
    let problems = infra_workflow_problems(&files);
    if !problems.is_empty() {
        bail!("infra-workflow:\n  {}", problems.join("\n  "));
    }
    Ok(())
}

