/// The only workflow lines that may hold a backslash, exactly, after trimming (DEC-2014 item 7):
/// a backslash in a quoted YAML scalar is an escape (`\x73ecrets`) the raw scan would not decode,
/// and a multi-line double-quoted scalar can carry one on a line that holds no quote and no
/// `${{` at all, so outside these reviewed shell lines every backslash is refused.
const BACKSLASH_WORKFLOW_LINES: &[(&str, &str)] = &[
    (
        ".github/workflows/ci.yml",
        r##"printf 'Affected-set selection (DEC-1190): %s\n' "$REASONS" | tee -a "$GITHUB_STEP_SUMMARY""##,
    ),
    (
        ".github/workflows/ci.yml",
        r##"printf 'mutants=0\nshards=[]\ntotal=0\nper_shard=1\n' >> "$GITHUB_OUTPUT""##,
    ),
    (
        ".github/workflows/codeql.yml",
        r##"echo 'If you are using a "manual" build mode for one or more of the' \"##,
    ),
    (
        ".github/workflows/codeql.yml",
        r##"'languages you are analyzing, replace this with the commands to build' \"##,
    ),
    (
        ".github/workflows/merge.yml",
        r##"prs=$(gh pr list --repo "$GITHUB_REPOSITORY" --state open --base main \"##,
    ),
    (".github/workflows/merge.yml", r##"printf '%s\n' "$out""##),
    (
        ".github/workflows/merge.yml",
        r##"if printf '%s\n' "$out" | grep -q '^merged as '; then"##,
    ),
    (
        ".github/workflows/ci.yml",
        r##"run: grep -rls 'packages\.microsoft\.com' /etc/apt/sources.list /etc/apt/sources.list.d/ | tee /dev/stderr | xargs -r sudo rm -f"##,
    ),
    (
        ".github/workflows/web-e2e.yml",
        r##"run: grep -rls 'packages\.microsoft\.com' /etc/apt/sources.list /etc/apt/sources.list.d/ | tee /dev/stderr | xargs -r sudo rm -f"##,
    ),
];

/// Every line of `file` that names `secrets`, `environment` or `inherit` as a whole word, case
/// aside and comments included, and is not one of [`GUARDED_WORKFLOW_LINES`] for that file: raw
/// text, no parser (DEC-2014 item 7). `inherit` is never allowed, since it passes every secret on
/// unnamed.
fn guarded_word_problems(file: &CiFile) -> Vec<String> {
    let mut problems = Vec::new();
    for (number, raw) in (1_usize..).zip(file.text.lines()) {
        let line = raw.to_ascii_lowercase();
        let names = |word: &str| whole_words(&line, word).next().is_some();
        if names("inherit") {
            problems.push(format!(
                "{}:{number}: names `inherit`, which passes every secret on unnamed (DEC-2014)",
                file.path
            ));
        }
        let allowed = GUARDED_WORKFLOW_LINES
            .iter()
            .any(|(path, allowed)| *path == file.path && *allowed == raw.trim());
        let escaped = raw.contains('\\')
            && !BACKSLASH_WORKFLOW_LINES
                .iter()
                .any(|(path, allowed)| *path == file.path && *allowed == raw.trim());
        if escaped {
            problems.push(format!(
                "{}:{number}: a backslash, which YAML or the shell may decode as an escape the \
                 scan would not, on a line xtask's BACKSLASH_WORKFLOW_LINES has not reviewed \
                 (DEC-2014)",
                file.path
            ));
        }
        if (names("secrets") || names("environment")) && !allowed {
            problems.push(format!(
                "{}:{number}: names `secrets` or `environment` on a line xtask's \
                 GUARDED_WORKFLOW_LINES has not reviewed (DEC-2014)",
                file.path
            ));
        }
    }
    problems
}

/// Every way the workflows break DEC-2014's shape for plan and apply: `infra.yml` must run on
/// `workflow_dispatch` alone; grant nothing at the top; hold one job, `tofu`, which runs only on
/// `refs/heads/main`, under `environment: infra-${{ inputs.environment }}`, reading contents only,
/// with a checkout that keeps no credential; offer exactly `staging` and `production`; and read a
/// secret only in the one step that runs [`INFRA_RUN`], and only [`INFRA_SECRETS`]. No other
/// workflow may read any of [`INFRA_SECRETS`], name `infra-staging` or `infra-production`, or
/// compute an `environment:` name, which could resolve to one of them. No workflow, `infra.yml`
/// included, may reach secrets by a form the check cannot name: an index (`secrets['x']`), the
/// whole context (`toJSON(secrets)`), or `secrets: inherit`.
fn infra_workflow_problems(files: &[CiFile]) -> Vec<String> {
    let secret_names = |text: &str| {
        text.match_indices("secrets.")
            .map(|(at, _)| {
                text.get(at.saturating_add("secrets.".len())..)
                    .unwrap_or_default()
                    .chars()
                    .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
    };
    let mut problems = Vec::new();
    for file in files {
        problems.extend(guarded_word_problems(file));
    }
    for file in files.iter().filter(|file| file.path != INFRA_WORKFLOW) {
        for (number, line) in (1_usize..).zip(file.text.lines()) {
            let code = uncommented(line);
            if secret_names(code)
                .iter()
                .any(|name| INFRA_SECRETS.contains(&name.as_str()))
                || code.contains("infra-staging")
                || code.contains("infra-production")
            {
                problems.push(format!(
                    "{}:{number}: reads an infrastructure secret or names its environment, \
                     which only {INFRA_WORKFLOW} may (DEC-2014)",
                    file.path
                ));
            }
        }
    }
    let Some(infra) = files.iter().find(|file| file.path == INFRA_WORKFLOW) else {
        return problems;
    };
    let lines: Vec<&str> = infra.text.lines().map(uncommented).collect();
    let has = |wanted: &str| lines.iter().any(|line| line.trim_end() == wanted);
    let mut fail = |why: &str| problems.push(format!("{INFRA_WORKFLOW}: {why} (DEC-2014)"));
    let top: Vec<&str> = lines
        .iter()
        .filter(|line| line.starts_with(|c: char| c.is_ascii_alphabetic()))
        .map(|line| line.split(':').next().unwrap_or_default().trim())
        .collect();
    if top != ["name", "on", "permissions", "concurrency", "jobs"] {
        fail("its top-level keys must be exactly name, on, permissions, concurrency and jobs");
    }
    let on: Vec<&str> = lines
        .iter()
        .skip_while(|line| line.trim_end() != "on:")
        .skip(1)
        .take_while(|line| !line.starts_with(|c: char| c.is_ascii_alphabetic()))
        .filter(|line| line.starts_with("  ") && !line.starts_with("   "))
        .map(|line| line.trim().trim_end_matches(':'))
        .collect();
    if on != ["workflow_dispatch"] {
        fail("it must run on workflow_dispatch alone, never on a push or a pull request");
    }
    if !has("permissions: {}") {
        fail("it must grant nothing at the top (`permissions: {}`)");
    }
    for wanted in [
        "        options: [staging, production]",
        "        options: [preflight, plan, apply]",
    ] {
        if !has(wanted) {
            fail(&format!(
                "its dispatch inputs must offer exactly `{}`",
                wanted.trim()
            ));
        }
    }
    let jobs: Vec<&str> = lines
        .iter()
        .skip_while(|line| line.trim_end() != "jobs:")
        .skip(1)
        .filter(|line| line.starts_with("  ") && !line.starts_with("   ") && line.ends_with(':'))
        .copied()
        .collect();
    if jobs != ["  tofu:"] {
        fail("it must hold one job, `tofu`");
    }
    for (wanted, why) in [
        (
            "    if: github.ref == 'refs/heads/main'",
            "the job must run only on refs/heads/main",
        ),
        (
            "    environment: infra-${{ inputs.environment }}",
            "the job must run under the environment infra-<environment>, which the founder approves",
        ),
        ("    permissions:", "the job must read contents only"),
        ("      contents: read", "the job must read contents only"),
        (
            "          persist-credentials: false",
            "the checkout must keep no credential",
        ),
        (
            "          MANDATE_INFRA_SHA: ${{ inputs.sha }}",
            "the secret step must receive the reviewed commit, which it checks against the checkout",
        ),
    ] {
        if !has(wanted) {
            fail(why);
        }
    }
    let steps: Vec<Vec<usize>> = {
        let mut steps: Vec<Vec<usize>> = Vec::new();
        let mut in_steps = false;
        for (index, line) in lines.iter().enumerate() {
            if line.trim_end() == "    steps:" {
                in_steps = true;
            } else if in_steps && line.starts_with("      - ") {
                steps.push(vec![index]);
            } else if in_steps && !line.trim().is_empty() && !line.starts_with("       ") {
                in_steps = false;
            } else if let Some(step) = steps.last_mut().filter(|_| in_steps) {
                step.push(index);
            }
        }
        steps
    };
    let text_of = |step: &[usize]| {
        step.iter()
            .filter_map(|index| lines.get(*index).copied())
            .collect::<Vec<_>>()
            .join("\n")
    };
    let run_of = |step: &[usize]| {
        step.iter().find_map(|index| {
            lines
                .get(*index)?
                .trim()
                .trim_start_matches("- ")
                .strip_prefix("run: ")
                .map(str::trim)
        })
    };
    let running: Vec<usize> = (0..steps.len())
        .filter(|at| steps.get(*at).and_then(|step| run_of(step)) == Some(INFRA_RUN))
        .collect();
    let closing: Vec<usize> = (0..steps.len())
        .filter(|at| steps.get(*at).and_then(|step| run_of(step)) == Some(INFRA_CLOSE))
        .collect();
    if running.len() != 1 || running.first().copied() != steps.len().checked_sub(2) {
        fail(&format!(
            "its job must run `{INFRA_RUN}` once, in the step before the last"
        ));
    }
    let closes_always = closing.len() == 1
        && closing.first().copied() == steps.len().checked_sub(1)
        && closing
            .first()
            .and_then(|at| steps.get(*at))
            .and_then(|step| step.first())
            .and_then(|index| lines.get(*index))
            .is_some_and(|line| line.trim_end() == INFRA_CLOSE_IF);
    if !closes_always {
        fail(&format!(
            "its job must end with one `if: always()` step that runs `{INFRA_CLOSE}`"
        ));
    }
    let in_a_step: BTreeSet<usize> = steps.iter().flatten().copied().collect();
    if lines
        .iter()
        .enumerate()
        .any(|(index, line)| !in_a_step.contains(&index) && !secret_names(line).is_empty())
    {
        fail("only a step may read a secret, never the workflow or the job");
    }
    for (at, step) in steps.iter().enumerate() {
        let allowed: &[&str] = if running == [at] {
            &INFRA_SECRETS
        } else if closing == [at] {
            &INFRA_CLOSE_SECRETS
        } else {
            &[]
        };
        if secret_names(&text_of(step))
            .iter()
            .any(|name| !allowed.contains(&name.as_str()))
        {
            fail(&format!(
                "only the step that runs `{INFRA_RUN}` may read a secret, and only {}; the \
                 closing step reads {} alone",
                INFRA_SECRETS.join(", "),
                INFRA_CLOSE_SECRETS.join(" and ")
            ));
        }
    }
    problems.sort();
    problems.dedup();
    problems
}

/// The packages whose tests need the S3 test store (E21-40): `cargo xtask ci objectstore` runs
/// those of them the selection holds.
const S3_TESTED: [&str; 1] = ["mandate-objectstore"];

/// The paths whose change selects every crate and every job (DEC-1190 item 3): the workspace's
/// build inputs, its tool configuration, CI itself, and xtask, which runs every check. Every
/// `Cargo.toml` is one too, wherever it is ([`selects_everything`]): a manifest can change a
/// feature or a dependency other crates are built with. An entry ending in `/` is a directory.
const EVERY_JOB_PATHS: [&str; 11] = [
    "Cargo.lock",
    "rust-toolchain.toml",
    "rust-toolchain",
    "deny.toml",
    "clippy.toml",
    ".cargo/",
    ".config/",
    ".github/",
    "xtask/",
    ".gitignore",
    ".python-version",
];

/// The paths outside every crate that the selection knows (DEC-1190 item 3): each is read by a
/// job that runs on every change outside the documentation (`fast-lint`, `full-checks`,
/// `fast-python`), by `web.yml`, or by the crates whose sources name it ([`source_references`]).
/// Markdown anywhere is known too. A changed path outside every crate and outside this list
/// selects everything, so a new top-level directory is never assumed unread.
const KNOWN_OUTSIDE_CRATES: [&str; 18] = [
    "docs/",
    "web/",
    "python/",
    "reference/",
    "schemas/",
    "fixtures/",
    "migrations/",
    "config/",
    "deploy/",
    "scripts/",
    "assets/",
    ".cursor/",
    ".claude/",
    "_typos.toml",
    ".gitleaks.toml",
    ".gitleaksignore",
    "CODEOWNERS",
    "LICENSE*",
];

/// The paths the workspace API schema checkers and their mutation sweep read besides `schemas/`
/// (DEC-1190 item 2): every spec, `check_planned.py` globbing `docs/specs/*.md` (the journal
/// spec among them), the backlog it checks planned operations against, and the requirements file
/// that pins their Python environment ([`pinned_python`]).
const SCHEMA_SWEEP_INPUTS: [&str; 5] = [
    "schemas/",
    "docs/specs/",
    "docs/project/06-backlog-v1.md",
    "docs/project/backlog/",
    "reference/mandate/requirements.txt",
];

/// The paths outside every crate that the cell jobs read (DEC-2609): the charts, images, compose
/// files and drills under `deploy/`, and the Python environment `cargo xtask ci cell` runs the
/// charts' invariant tests (`deploy/tests`) in. With the crates the cell's images hold
/// ([`cell::IMAGE_PACKAGES`]) they are everything a cell job builds or reads that `xtask/` and
/// `.github/`, which select everything, do not already cover.
const CELL_INPUTS: [&str; 3] = ["deploy/", "python/pyproject.toml", "python/uv.lock"];

/// The runner, the one crate whose `live` build the founder runs (DEC-529): `fast-portable` lints
/// and tests it on macOS (DEC-954) and `fast-rh-sim-live` runs its rehearsal build (DEC-964), so
/// both run exactly when it is selected.
const RUNNER_CRATE: &str = "mandate-paper";

/// The binaries a test runs by a path an environment variable names, each with the crate that
/// builds it (DEC-1190 item 2): `mandate-mcp`'s rehearsal tests run the simulator `test-rh-sim`
/// builds (DEC-922 item 3) without depending on its crate. A crate whose sources name the variable
/// is selected whenever the binary's crate is, as if it depended on it.
const BINARY_COUPLINGS: [(&str, &str); 1] = [(RH_SIM_BIN_ENV, "mandate-rh-sim")];

/// The prefix [`source_references`] gives a [`BINARY_COUPLINGS`] reference, a crate rather than a
/// path, so no path matches it.
const BINARY_REFERENCE: &str = "bin:";

/// The packages whose tests need the database (ADR-0001 ES-08, DEC-520), the dispatcher's journal
/// adapter among them (E8-10 slice D10a, DEC-2500 item 8): `cargo xtask ci postgres` runs those of
/// them the selection holds.
const PG_TESTED: [&str; 3] = ["mandate-journal-pg", "mandate-cli", "mandate-dispatcher"];

/// The packages whose tests need the OpenBao dev server (E21-32, DEC-977, DEC-2022): `cargo xtask
/// ci openbao` runs each one's server tests when the selection holds it.
const OPENBAO_TESTED: [&str; 2] = ["mandate-vault", "mandate-cli"];

/// Which of `package`'s tests need the OpenBao dev server, as nextest arguments.
fn openbao_tests(package: &str) -> &'static [&'static str] {
    match package {
        "mandate-cli" => &["--test", "vault_provision"],
        _ => &["--lib", "--filterset", "test(/^tests::openbao_server::/)"],
    }
}

/// Whether `path` is `entry`, lies under it when `entry` names a directory (ends in `/`), or
/// starts with it when `entry` ends in `*`.
fn path_under(path: &str, entry: &str) -> bool {
    if let Some(prefix) = entry.strip_suffix('*') {
        path.starts_with(prefix)
    } else if entry.ends_with('/') {
        path.starts_with(entry)
    } else {
        path == entry
    }
}

/// Whether a change to `path` selects every crate and every job (DEC-1190 item 3).
fn selects_everything(path: &str) -> bool {
    EVERY_JOB_PATHS.iter().any(|entry| path_under(path, entry))
        || path == "Cargo.toml"
        || path.ends_with("/Cargo.toml")
}

/// The documentation the short path of DEC-112 skips, exactly as `.github/scripts/docs-only.sh`
/// classifies it: Markdown anywhere, `docs/`, `CODEOWNERS` and `LICENSE*`, except the feature
/// map, the reference-case YAML and the workspace API spec, which checks read. xtask's tests run
/// the script over the same paths and require the same answer.
fn is_docs_path(path: &str) -> bool {
    if path.starts_with(".cursor/skills/verify-mandate/features/")
        || path.starts_with("docs/specs/reference-cases/")
        || path == "docs/specs/workspace-api.md"
    {
        return false;
    }
    path.ends_with(".md")
        || path.starts_with("docs/")
        || path == "CODEOWNERS"
        || path.starts_with("LICENSE")
}

/// The workspace's crates as the selection reads them (DEC-1190 item 2).
#[derive(Clone, Debug, Default)]
struct CrateGraph {
    /// Each member's directory, relative to the repository root.
    dirs: BTreeMap<String, String>,
    /// The members each member depends on directly, of every kind (normal, dev and build): a
    /// dependent's tests link what it depends on.
    deps: BTreeMap<String, BTreeSet<String>>,
    /// Whether some member turns a feature of another member on, directly or by forwarding one of
    /// its own (`x = ["member/feat"]`), or turns its defaults off: a `--package` build would then
    /// unify that member's features differently from the `--workspace` build, so the selection
    /// takes everything rather than reason about it.
    member_features: bool,
}

/// The [`CrateGraph`] of the workspace at `root`.
fn crate_graph(root: &Path) -> Result<CrateGraph> {
    let meta = metadata_in(root)?;
    let dirs: BTreeMap<String, String> = package_dirs(root)?.into_iter().collect();
    let members = member_dirs(&meta);
    let mut graph = CrateGraph {
        dirs,
        ..CrateGraph::default()
    };
    for pkg in workspace_packages(&meta) {
        let on: Vec<&Dependency> = pkg
            .dependencies
            .iter()
            .filter(|dep| on_member(dep, &members))
            .collect();
        graph.member_features |= on
            .iter()
            .any(|dep| !dep.features.is_empty() || !dep.uses_default_features)
            || pkg.features.values().flatten().any(|value| {
                let named = value.trim_start_matches("dep:");
                let named = named
                    .split('/')
                    .next()
                    .unwrap_or(named)
                    .trim_end_matches('?');
                value.contains('/') && on.iter().any(|dep| dep.name == named)
            });
        graph.deps.insert(
            pkg.name.clone(),
            on.iter().map(|dep| dep.name.clone()).collect(),
        );
    }
    Ok(graph)
}

/// `seeds` and every member that depends on one of them, directly or through other members.
fn dependents_closure(graph: &CrateGraph, seeds: &BTreeSet<String>) -> BTreeSet<String> {
    let mut dependents: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for (krate, deps) in &graph.deps {
        for dep in deps {
            dependents
                .entry(dep.as_str())
                .or_default()
                .push(krate.as_str());
        }
    }
    let mut reached = BTreeSet::new();
    let mut pending: Vec<&str> = seeds.iter().map(String::as_str).collect();
    while let Some(next) = pending.pop() {
        if reached.insert(next.to_owned()) {
            pending.extend(dependents.get(next).into_iter().flatten().copied());
        }
    }
    reached
}

/// The member whose directory holds `path`, the innermost when directories nest.
fn owning_crate<'g>(graph: &'g CrateGraph, path: &str) -> Option<&'g str> {
    graph
        .dirs
        .iter()
        .filter(|(_, dir)| path_under(path, &format!("{dir}/")))
        .max_by_key(|(_, dir)| dir.len())
        .map(|(name, _)| name.as_str())
}

/// The repository paths each member's Rust sources name (DEC-1190 item 2): every piece of every
/// string literal that could be a path, a leading `/` dropped (`concat!(env!(..), "/../..")`),
/// resolved against the file's directory (`include_str!`), the crate's directory
/// (`CARGO_MANIFEST_DIR`), `crates/` (a sibling crate named from a computed `crates` directory)
/// and the repository root, so a test reading `docs/specs/identity.md`, another crate's fixtures
/// or another crate's source is selected when that file changes. A
/// piece with `*` is kept as a prefix ending in `*`. The scan over-approximates on purpose: a
/// literal that is not a path costs at most a crate selected more, never one selected less. The
/// one reading it drops is a directory above the crate's own, `crates` itself: a `..` piece read
/// against the crate's directory names it, and path-traversal tests are full of `..`. A crate that
/// reads other crates' files names them below `crates/`, as `mandate-paper` names
/// `mandate-shell`'s fixtures; xtask, which reads them all, selects everything when it changes.
fn source_references(
    root: &Path,
    graph: &CrateGraph,
) -> Result<BTreeMap<String, BTreeSet<String>>> {
    let mut args = vec![
        "ls-files",
        "--cached",
        "--others",
        "--exclude-standard",
        "--",
    ];
    args.extend(graph.dirs.values().map(String::as_str));
    let files = output_in(root, "git", &args)?;
    let mut references: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    for file in files.lines().filter(|f| f.ends_with(".rs")) {
        let Some(owner) = owning_crate(graph, file) else {
            continue;
        };
        let Ok(text) = fs::read_to_string(root.join(file)) else {
            continue;
        };
        let crate_dir = graph.dirs.get(owner).cloned().unwrap_or_default();
        let file_dir = file.rsplit_once('/').map(|(dir, _)| dir).unwrap_or("");
        let named = references.entry(owner.to_owned()).or_default();
        for (token, _) in tokens(&text) {
            if let Token::Str(literal) = token {
                named.extend(
                    BINARY_COUPLINGS
                        .iter()
                        .filter(|(var, _)| literal == *var)
                        .map(|(_, binary)| format!("{BINARY_REFERENCE}{binary}")),
                );
                named.extend(
                    literal_paths(&literal, file_dir, &crate_dir)
                        .into_iter()
                        .filter(|path| !path_under(&crate_dir, &format!("{path}/"))),
                );
            }
        }
    }
    Ok(references)
}

/// The repository paths `literal`, found in a file in `file_dir` of the crate in `crate_dir`,
/// could name ([`source_references`]).
fn literal_paths(literal: &str, file_dir: &str, crate_dir: &str) -> BTreeSet<String> {
    let path_char = |c: char| c.is_ascii_alphanumeric() || "-_./*@+".contains(c);
    let mut found = BTreeSet::new();
    for piece in literal.split(|c: char| !path_char(c)) {
        if piece.is_empty() || piece.contains("//") {
            continue;
        }
        let (piece, glob) = match piece.split_once('*') {
            Some((before, _)) => (before, true),
            None => (piece, false),
        };
        let piece = piece.trim_start_matches('/');
        for base in [file_dir, crate_dir, "crates", ""] {
            if let Some(mut path) = normalized_join(base, piece) {
                if glob {
                    path.push('*');
                }
                found.insert(path);
            }
        }
    }
    found
}

/// `piece` joined to `base`, both relative to the repository root, with `.` and `..` resolved:
/// `None` when the result is the root itself or would leave it.
fn normalized_join(base: &str, piece: &str) -> Option<String> {
    let mut parts: Vec<&str> = Vec::new();
    for part in base.split('/').chain(piece.split('/')) {
        match part {
            "" | "." => {}
            ".." => {
                parts.pop()?;
            }
            part => parts.push(part),
        }
    }
    (!parts.is_empty()).then(|| parts.join("/"))
}

/// Whether `reference`, one of [`source_references`]' paths, names `path`: the path itself, a
/// directory above it, or, ending in `*`, a prefix of it.
fn references_path(reference: &str, path: &str) -> bool {
    match reference.strip_suffix('*') {
        Some(prefix) => path.starts_with(prefix),
        None => path == reference || path_under(path, &format!("{reference}/")),
    }
}

/// What one diff runs (DEC-1190): the crates whose tests, doctests, pending tests and rehearsal
/// builds run, and whether the jobs scoped by path run at all. Lint, the spec guard and the
/// mutation gate are not here: they run on every change as before.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Selection {
    /// Why every crate and every job runs, when they do.
    everything: Option<String>,
    /// The selected crates: those owning a changed path or naming one in their sources, and every
    /// member depending on one of those, directly or not.
    crates: BTreeSet<String>,
    /// Whether `fast-python` runs: a path changed outside every crate, the documentation and `web/`.
    python: bool,
    /// Whether `full-checks` runs: a path changed outside the documentation and `web/` (DEC-112).
    full_checks: bool,
    /// Whether `schema-mutants` runs: a path the schema sweep reads changed ([`SCHEMA_SWEEP_INPUTS`]).
    schema_mutants: bool,
    /// Whether `full-checks`' `tofu` part runs: a path under [`TOFU_DIR`] changed (E21-56).
    tofu: bool,
    /// Whether the cell jobs run (DEC-2609): a path they read changed ([`CELL_INPUTS`]), or the
    /// selection holds a crate the cell's images hold ([`cell::IMAGE_PACKAGES`]), which it does
    /// whenever any crate those are built on changed.
    cell: bool,
    /// Whether `cell-demo-web` runs: the cell jobs do, or a path under `web/` other than its
    /// Markdown changed, since the job drives `web/` against the cell (DEC-2609 item 5). A pull
    /// request's run then never starts it (DEC-2634), in [`selection_in`]: the job is in neither
    /// `fast`'s nor `full`'s `needs`, so nothing requires it, and while its gesture was failing on
    /// every run it made the whole `ci` run conclude `failure`, which is what the merge gate reads.
    cell_web: bool,
}

impl Selection {
    /// Every crate of `graph` and every job, for `reason`.
    fn everything(graph: &CrateGraph, reason: String) -> Self {
        Self {
            everything: Some(reason),
            crates: graph.dirs.keys().cloned().collect(),
            python: true,
            full_checks: true,
            schema_mutants: true,
            tofu: true,
            cell: true,
            cell_web: true,
        }
    }

    /// Whether any crate's tests run.
    fn tests(&self) -> bool {
        !self.crates.is_empty()
    }

    /// Whether the runner's macOS check (DEC-954) and its rehearsal build's tests (DEC-964) run.
    fn runner(&self) -> bool {
        self.crates.contains(RUNNER_CRATE)
    }

    /// The selected crates among `packages`, in their order.
    fn among<'p>(&self, packages: &[&'p str]) -> Vec<&'p str> {
        packages
            .iter()
            .copied()
            .filter(|package| self.crates.contains(*package))
            .collect()
    }

    /// One line saying what runs and why, for the job summaries and the aggregates' logs.
    fn reasons(&self) -> String {
        let yes = |on: bool| if on { "runs" } else { "skipped" };
        let scope = match &self.everything {
            Some(reason) => format!("everything selected: {reason}"),
            None if self.crates.is_empty() => "no crate affected".to_owned(),
            None => format!(
                "{} crate(s) affected: {}",
                self.crates.len(),
                self.crates.iter().cloned().collect::<Vec<_>>().join(", ")
            ),
        };
        format!(
            "{scope}; tests {}; python {}; portable and rh-sim-live {}; full-checks {} \
             (tofu {}); schema-mutants {}; cell {}; cell-demo-web {}; lint, the spec guard and \
             mutants run as always (DEC-1190)",
            yes(self.tests()),
            yes(self.python),
            yes(self.runner()),
            yes(self.full_checks),
            yes(self.tofu),
            yes(self.schema_mutants),
            yes(self.cell),
            yes(self.cell_web),
        )
    }

    /// The selection as `GITHUB_OUTPUT` lines, one boolean a gated job and its line in the
    /// `reasons` the aggregates print.
    fn outputs(&self) -> String {
        format!(
            "tests={}\npython={}\nportable={}\nrh_sim_live={}\nfull_checks={}\nschema_mutants={}\n\
             cell={}\ncell_web={}\nreasons={}\n",
            self.tests(),
            self.python,
            self.runner(),
            self.runner(),
            self.full_checks,
            self.schema_mutants,
            self.cell,
            self.cell_web,
            self.reasons(),
        )
    }
}

/// What the diff of `changed` paths runs (DEC-1190 items 2 and 3); `None` means there is no base
/// to compare against (a run on main, the nightly), which runs everything. When in doubt it
/// selects more: a path it does not know, any build input, and a member turning on another
/// member's feature all select everything.
fn select(
    changed: Option<&[String]>,
    graph: &CrateGraph,
    references: &BTreeMap<String, BTreeSet<String>>,
) -> Selection {
    let Some(changed) = changed else {
        return Selection::everything(graph, "no diff base, so nothing is scoped".to_owned());
    };
    if graph.member_features {
        return Selection::everything(
            graph,
            "a member turns on another member's feature, which a --package build unifies \
             differently"
                .to_owned(),
        );
    }
    let mut seeds = BTreeSet::new();
    let mut python = false;
    let mut full_checks = false;
    let mut schema_mutants = false;
    let mut tofu = false;
    let mut cell = false;
    let mut web_changed = false;
    for path in changed {
        if selects_everything(path) {
            return Selection::everything(graph, format!("{path} changed"));
        }
        let owner = owning_crate(graph, path);
        let docs = is_docs_path(path);
        let web = path_under(path, "web/");
        if owner.is_none()
            && !path.ends_with(".md")
            && !KNOWN_OUTSIDE_CRATES
                .iter()
                .any(|entry| path_under(path, entry))
        {
            return Selection::everything(graph, format!("{path} is outside every known path"));
        }
        seeds.extend(owner.map(str::to_owned));
        seeds.extend(
            references
                .iter()
                .filter(|(_, named)| {
                    named
                        .iter()
                        .any(|reference| references_path(reference, path))
                })
                .map(|(krate, _)| krate.clone()),
        );
        full_checks |= !docs && !web;
        python |= owner.is_none() && !docs && !web;
        schema_mutants |= SCHEMA_SWEEP_INPUTS
            .iter()
            .any(|entry| path_under(path, entry));
        tofu |= path_under(path, TOFU_DIR) && !docs;
        cell |= CELL_INPUTS.iter().any(|entry| path_under(path, entry));
        web_changed |= web && !path.ends_with(".md");
    }
    let mut crates = dependents_closure(graph, &seeds);
    loop {
        let coupled: BTreeSet<String> = references
            .iter()
            .filter(|(krate, named)| {
                !crates.contains(*krate)
                    && named.iter().any(|reference| {
                        reference
                            .strip_prefix(BINARY_REFERENCE)
                            .is_some_and(|binary| crates.contains(binary))
                    })
            })
            .map(|(krate, _)| krate.clone())
            .collect();
        if coupled.is_empty() {
            break;
        }
        seeds.extend(coupled);
        crates = dependents_closure(graph, &seeds);
    }
    cell |= cell::IMAGE_PACKAGES
        .iter()
        .any(|package| crates.contains(*package));
    Selection {
        everything: None,
        crates,
        python,
        full_checks,
        schema_mutants,
        tofu,
        cell,
        cell_web: cell || web_changed,
    }
}

/// The paths a change touches against `base`, renames as a deletion and an addition so both
/// sides count: the working tree against the merge base of `base` and HEAD, so a local run counts
/// what is not committed yet, and untracked files too. In CI the tree is the commit, so this is
/// `base...HEAD`.
fn changed_paths(root: &Path, base: &str) -> Result<Vec<String>> {
    let merge_base = output_in(root, "git", &["merge-base", base, "HEAD"])?;
    let mut changed: BTreeSet<String> = output_in(
        root,
        "git",
        &["diff", "--name-only", "--no-renames", merge_base.trim()],
    )?
    .lines()
    .map(str::to_owned)
    .collect();
    changed.extend(
        output_in(root, "git", &["ls-files", "--others", "--exclude-standard"])?
            .lines()
            .map(str::to_owned),
    );
    Ok(changed.into_iter().collect())
}

/// The selection for the repository at `root` against `base` ([`select`]).
fn selection_in(root: &Path, base: Option<&str>) -> Result<Selection> {
    let graph = crate_graph(root)?;
    let changed = base.map(|base| changed_paths(root, base)).transpose()?;
    let references = source_references(root, &graph)?;
    Ok(select(changed.as_deref(), &graph, &references))
}

/// The selection for this run, from the base [`base_ref`] chooses, said on stderr.
fn selection() -> Result<Selection> {
    let mut selected = selection_in(Path::new("."), base_ref()?.as_deref())?;
    withhold_web_demo(&mut selected, env::var("GITHUB_EVENT_NAME").ok().as_deref());
    eprintln!("    select: {}", selected.reasons());
    Ok(selected)
}

/// DEC-2634: a pull request's run withholds `cell-demo-web`. The job is in neither `fast`'s nor
/// `full`'s `needs`, so no aggregate requires it, yet its `web/` gesture had failed on every run
/// since it merged and made the whole `ci` run conclude `failure` — which the merge gate reads as
/// "not green", blocking every merge. `main`'s own push, the nightly's dispatch and a local run
/// keep it, where a failure is a finding rather than a merge blocker.
fn withhold_web_demo(selected: &mut Selection, event: Option<&str>) {
    if event == Some("pull_request") {
        selected.cell_web = false;
    }
}

/// `cargo xtask ci select`: the selection as `GITHUB_OUTPUT` lines on stdout, and as a table in
/// the job's summary when GitHub gives it one (DEC-1190 item 4).
fn ci_select() -> Result<()> {
    let selected = selection()?;
    print!("{}", selected.outputs());
    if let Some(summary) = env::var_os("GITHUB_STEP_SUMMARY") {
        let mut file = fs::OpenOptions::new()
            .append(true)
            .create(true)
            .open(summary)
            .context("opening the job summary")?;
        writeln!(
            file,
            "### Affected-set selection (DEC-1190)\n\n{}\n",
            selected.reasons()
        )?;
    }
    Ok(())
}

/// The base [`land_check_cmd`] merges when it is given none.
const LAND_CHECK_BASE: &str = "origin/main";

/// The `ci` jobs [`land_check`] runs on the merged tree, in order: the spec guard (ES-22), gitleaks
/// over the diff (`secrets`, DEC-2645), lint, and each part of `ci test`, which run over the crates
/// the diff from the base selects (DEC-1190). The parts run as jobs of their own, so a failing
/// nextest run never keeps the doctests, the rehearsal or the Python tests from running. No cell
/// and no mutants, so the check stays fast enough to run before every landing (DEC-2642).
const LAND_CHECK_JOBS: [&str; 7] = [
    "spec-guard",
    "secrets",
    "lint",
    "test-nextest",
    "test-doc",
    "test-rh-sim",
    "test-python",
];

/// The user a test that failed as root is run again as (DEC-2644): `nobody`'s uid and gid,
/// which file permissions apply to, so a test that refuses to run as root can run.
const UNPRIVILEGED_ID: &str = "65534";

/// Where [`land_check`] keeps its scratch worktree, `work/`, and its builds, `target/`, under the
/// repository root. Both paths are fixed: cargo names a workspace crate's artifacts by its source
/// path, so a worktree at a new path each run would add a whole workspace's build every time, and
/// a target directory of its own never replaces the checkout's own `target/debug/xtask` with one
/// rooted at the worktree. `rm -rf target/land-check` gives the space back.
const LAND_CHECK_DIR: &str = "target/land-check";

/// What [`land_check_cmd`]'s builds leave out to fit a lane's disk: incremental artifacts and
/// debuginfo. A change to `xtask/` or `Cargo.lock` selects every crate (DEC-1190), and with both
/// on, building the whole workspace's tests filled a 40 GB session disk in lane DR's first run
/// (2026-10-26). Neither changes what a test checks.
const LAND_CHECK_BUILD: [(&str, &str); 3] = [
    ("CARGO_INCREMENTAL", "0"),
    ("CARGO_PROFILE_DEV_DEBUG", "0"),
    ("CARGO_PROFILE_TEST_DEBUG", "0"),
];

/// The `cargo xtask ci <job>` child [`land_check_cmd`] runs in the merged tree `dir`: diffed
/// against the base it merged (`MANDATE_BASE_REF`), built into `target` as [`LAND_CHECK_BUILD`]
/// says, and running every test after a failure ([`NO_FAIL_FAST_ENV`]), so the check names them
/// all. `MANDATE_PR_BODY` and `MANDATE_PR_NUMBER`, which spec-guard reads for a DEC the PR
/// description cites, pass through from the caller's environment.
fn land_check_job(dir: &Path, base_sha: &str, target: &Path, job: &str) -> Command {
    let mut cargo = Command::new("cargo");
    cargo
        .current_dir(dir)
        .args(["xtask", "ci", job])
        .env("MANDATE_BASE_REF", base_sha)
        .env(CARGO_TARGET_DIR, target)
        .env(NO_FAIL_FAST_ENV, "1")
        .env_remove(TEST_PARTITION_ENV)
        .env_remove(NEXTEST_FILTER_ENV)
        .env_remove(NEXTEST_RUNNER_ENV)
        .envs(LAND_CHECK_BUILD);
    cargo
}

/// `cargo xtask land-check [BASE]` (DEC-2642): fetches BASE first when it names a branch of
/// `origin`, then runs [`land_check`] with each job as [`land_check_job`], and prints the summary
/// line on stdout. Run as root, a nextest job that failed only by tests that failed runs each of
/// them once more as an unprivileged user (DEC-2644).
fn land_check_cmd(root: &Path, base: &str) -> Result<()> {
    let fetched = base
        .strip_prefix("origin/")
        .map(|branch| output_in(root, "git", &["fetch", "-q", "origin", branch]).is_ok());
    let target = root.join(LAND_CHECK_DIR).join("target");
    let root_user = output("id", &["-u"]).is_ok_and(|uid| uid.trim() == "0");
    let host = output("rustc", &["-vV"]).ok().and_then(|said| {
        said.lines()
            .find_map(|line| line.strip_prefix("host: ").map(str::to_owned))
    });
    let (line, verdict) = land_check(root, base, fetched, |dir, base_sha, job| {
        eprintln!("==> land-check: ci {job}");
        let mut command = land_check_job(dir, base_sha, &target, job);
        if job != "test-nextest" {
            let status = command.status().context("starting `cargo xtask`")?;
            if !status.success() {
                bail!("`cargo xtask ci {job}` failed with {status}");
            }
            return Ok(Vec::new());
        }
        let (status, said) = streamed(&mut command)?;
        if status.success() {
            return Ok(Vec::new());
        }
        if !root_user {
            bail!("`cargo xtask ci {job}` failed with {status}");
        }
        let failed = nextest_failures(&said).with_context(|| {
            format!(
                "`cargo xtask ci {job}` failed with {status}, and not only by tests that failed, \
                 so none is run again"
            )
        })?;
        let host = host
            .as_deref()
            .context("`rustc -vV` names no host, so no runner can be set")?;
        let scratch = root.join(LAND_CHECK_DIR).join("tmp-unprivileged");
        fs::remove_dir_all(&scratch).ok();
        fs::create_dir_all(&scratch).context("making the unprivileged run's TMPDIR")?;
        sh(
            "chown",
            &[
                &format!("{UNPRIVILEGED_ID}:{UNPRIVILEGED_ID}"),
                &scratch.display().to_string(),
            ],
        )?;
        if let Some(reason) = rerun_blocked(&[&target, dir, &scratch], unprivileged_reaches) {
            fs::remove_dir_all(&scratch).ok();
            return Err(anyhow::Error::new(RerunUnavailable(reason)).context(format!(
                "`cargo xtask ci {job}` failed with {status} as root, and no test can run again \
                 as uid {UNPRIVILEGED_ID} here: give land-check a checkout that user can reach \
                 (DEC-2644)"
            )));
        }
        let rerun = || -> Result<Vec<String>> {
            let mut passed = Vec::new();
            for (binary, test) in &failed {
                eprintln!(
                    "==> land-check: {binary} {test} failed as root; once more as uid {UNPRIVILEGED_ID}"
                );
                let status = unprivileged_rerun(
                    land_check_job(dir, base_sha, &target, job),
                    host,
                    &scratch,
                    binary,
                    test,
                )
                .status()
                .context("starting `cargo xtask`")?;
                if !status.success() {
                    bail!("{binary} {test} failed as root and again as uid {UNPRIVILEGED_ID}");
                }
                passed.push(format!("{binary}:{test}"));
            }
            Ok(passed)
        };
        let outcome = rerun();
        fs::remove_dir_all(&scratch).ok();
        outcome
    });
    println!("{line}");
    verdict
}

/// Why no test that failed as root can run again here, as land-check's summary names it
/// (`rerun_unavailable=`): the paths the run needs are not traversable by uid [`UNPRIVILEGED_ID`],
/// or `setpriv` cannot run. The test stays red (DEC-2644).
#[derive(Debug)]
struct RerunUnavailable(&'static str);

impl fmt::Display for RerunUnavailable {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "rerun_unavailable={}", self.0)
    }
}

impl std::error::Error for RerunUnavailable {}

/// Why a re-run as uid [`UNPRIVILEGED_ID`] cannot reach `paths` (the build, the merged tree, its
/// TMPDIR), or `None` when it can: `reaches` answers for one path, `None` when it could not ask.
/// Checked before any test runs again, so an unreachable path reads as itself and never as the
/// test failing (lane NE's `identity_link`, 2026-10-26).
fn rerun_blocked(paths: &[&Path], reaches: impl Fn(&Path) -> Option<bool>) -> Option<&'static str> {
    for path in paths {
        match reaches(path) {
            None => return Some("setpriv_unavailable"),
            Some(false) => return Some("path_not_traversable"),
            Some(true) => {}
        }
    }
    None
}

/// Whether uid and gid [`UNPRIVILEGED_ID`] can search `path`, every directory above it included:
/// `setpriv` runs `test -x` as that user. `None` when `setpriv` cannot start.
fn unprivileged_reaches(path: &Path) -> Option<bool> {
    Command::new("setpriv")
        .args([
            &format!("--reuid={UNPRIVILEGED_ID}"),
            &format!("--regid={UNPRIVILEGED_ID}"),
            "--clear-groups",
            "--",
            "test",
            "-x",
        ])
        .arg(path)
        .status()
        .ok()
        .map(|status| status.success())
}

/// Runs `command` with its stderr read as it comes, each line echoed, and returns its status beside
/// everything it said there, read lossily so no byte a test prints can fail the read: nextest's
/// progress and its status lines. The child is always waited for.
fn streamed(command: &mut Command) -> Result<(ExitStatus, String)> {
    let mut child = command
        .stderr(Stdio::piped())
        .spawn()
        .context("starting `cargo xtask`")?;
    let mut said = String::new();
    let mut read = Ok(());
    if let Some(stderr) = child.stderr.take() {
        let mut reader = BufReader::new(stderr);
        let mut bytes = Vec::new();
        loop {
            bytes.clear();
            match reader.read_until(b'\n', &mut bytes) {
                Ok(0) => break,
                Ok(_) => {
                    let line = String::from_utf8_lossy(&bytes);
                    eprint!("{line}");
                    said.push_str(&line);
                }
                Err(err) => {
                    read = Err(err);
                    break;
                }
            }
        }
    }
    let status = child.wait().context("waiting for `cargo xtask`")?;
    read.context("reading the job's stderr")?;
    Ok((status, said))
}

/// The labels of nextest's status lines a run whose failures are all tests that failed may print:
/// every other label (`ABORT`, `TIMEOUT`, `FAIL + LEAK`, a signal, a failure to execute) is a
/// failure that is not a test that failed, and stops any test running again (DEC-2644).
const NEXTEST_PLAIN_LABELS: [&str; 6] = ["PASS", "FAIL", "SKIP", "SLOW", "START", "RETRY"];

/// The tests a nextest run reports failed, each as its binary id and test name from its `FAIL`
/// lines, or `None` unless those are the whole of what did not pass (DEC-2644):
/// - every status line's label is one of [`NEXTEST_PLAIN_LABELS`];
/// - the last summary reads `N tests run: P passed …, F failed …, S skipped` and nothing else,
///   with `P + F = N`, so no run was cancelled, timed out, aborted or failed to execute;
/// - `F` is the number of distinct tests the `FAIL` lines name, and is not zero.
///
/// It fails closed: a summary part or a status label it cannot read stops any test running again.
fn nextest_failures(said: &str) -> Option<BTreeSet<(String, String)>> {
    let plain = |line: &str| {
        let mut out = String::with_capacity(line.len());
        let mut chars = line.chars();
        while let Some(c) = chars.next() {
            if c == '\u{1b}' {
                for c in chars.by_ref() {
                    if c.is_ascii_alphabetic() {
                        break;
                    }
                }
            } else {
                out.push(c);
            }
        }
        out
    };
    let label_of = |line: &str| {
        let (label, rest) = line.split_once(" [")?;
        let label = label.trim();
        let shouted = !label.is_empty()
            && label
                .chars()
                .all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || " +-".contains(c));
        (shouted && rest.contains(']')).then(|| label.to_owned())
    };
    let mut failed = BTreeSet::new();
    let mut summary = None;
    for line in said.lines().map(plain) {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix("Summary [") {
            summary = Some(rest.split_once(']')?.1.trim().to_owned());
            continue;
        }
        let Some(label) = label_of(line) else {
            continue;
        };
        if !NEXTEST_PLAIN_LABELS.contains(&label.as_str()) {
            return None;
        }
        if label == "FAIL" {
            let rest = line.split_once(']')?.1.trim();
            let rest = match rest.strip_prefix('(') {
                Some(numbered) => numbered.split_once(')')?.1.trim(),
                None => rest,
            };
            let mut words = rest.split_whitespace();
            failed.insert((words.next()?.to_owned(), words.next()?.to_owned()));
        }
    }
    let summary = summary?;
    let (run, parts) = summary.split_once(" tests run: ")?;
    let run: usize = run.trim().parse().ok()?;
    let (mut passed, mut failures) = (0, 0);
    for part in parts.split(", ") {
        let part = match part.split_once(" (") {
            Some((count, aside)) if aside.ends_with(" slow)") => count,
            Some(_) => return None,
            None => part,
        };
        let (count, word) = part.trim().split_once(' ')?;
        let count: usize = count.parse().ok()?;
        match word {
            "passed" => passed = count,
            "failed" => failures = count,
            "skipped" => {}
            _ => return None,
        }
    }
    (passed + failures == run && failures == failed.len() && failures > 0).then_some(failed)
}

/// `job`, the job that failed, run once more narrowed to `test` of `binary` ([`NEXTEST_FILTER_ENV`]),
/// its test process run as uid and gid [`UNPRIVILEGED_ID`] by `host`'s target runner, with `scratch`
/// as its TMPDIR: the same packages, build and environment the test failed in, as the user file
/// permissions apply to. The build stays root's (DEC-2644).
fn unprivileged_rerun(
    mut job: Command,
    host: &str,
    scratch: &Path,
    binary: &str,
    test: &str,
) -> Command {
    let runner = format!(
        "CARGO_TARGET_{}_RUNNER",
        host.to_uppercase().replace(['-', '.'], "_")
    );
    job.env(
        NEXTEST_FILTER_ENV,
        format!("binary_id(={binary}) & test(={test})"),
    )
    .env(
        NEXTEST_RUNNER_ENV,
        format!(
            "{runner}=setpriv --reuid={UNPRIVILEGED_ID} --regid={UNPRIVILEGED_ID} --clear-groups --"
        ),
    )
    .env("TMPDIR", scratch);
    job
}

/// `git` in `dir` as a committer with no hooks or signing, so the merge a check makes depends on
/// nothing in the caller's git configuration.
fn land_check_git(dir: &Path, args: &[&str]) -> Result<String> {
    let mut all = vec![
        "-c",
        "user.name=land-check",
        "-c",
        "user.email=land-check@example.invalid",
        "-c",
        "commit.gpgsign=false",
        "-c",
        "core.hooksPath=/dev/null",
    ];
    all.extend_from_slice(args);
    output_in(dir, "git", &all).map(|out| out.trim().to_owned())
}

/// Removes [`land_check`]'s scratch worktree at `dir`, whatever state an earlier run left it in.
fn land_check_clear(root: &Path, dir: &Path) {
    land_check_git(
        root,
        &["worktree", "remove", "--force", &dir.display().to_string()],
    )
    .ok();
    fs::remove_dir_all(dir).ok();
    land_check_git(root, &["worktree", "prune"]).ok();
}

/// Merges `base` into the committed HEAD of the repository at `root` in a scratch worktree,
/// [`LAND_CHECK_DIR`]`/work`, runs each of [`LAND_CHECK_JOBS`] there with `run(dir, base_sha, job)`,
/// every one even after a failure so the summary names them all, removes the worktree, and returns
/// the one `land-check summary:` line beside the verdict (DEC-2642). It passes only when the base
/// was fetched or names no branch of `origin` (`fetched`), the merge succeeded, and every job
/// passed: a base that could not be fetched may be stale, which is what the check exists to
/// rule out. A merge that conflicts, or a worktree that cannot be made, fails before any job.
fn land_check(
    root: &Path,
    base: &str,
    fetched: Option<bool>,
    mut run: impl FnMut(&Path, &str, &str) -> Result<Vec<String>>,
) -> (String, Result<()>) {
    let short = |sha: &str| sha.chars().take(12).collect::<String>();
    let fetched_word = match fetched {
        Some(true) => "yes",
        Some(false) => "no",
        None => "skipped",
    };
    let resolved = land_check_git(root, &["rev-parse", "HEAD"]).and_then(|head| {
        land_check_git(root, &["rev-parse", &format!("{base}^{{commit}}")])
            .map(|base_sha| (head, base_sha))
    });
    let (head, base_sha) = match resolved {
        Ok(pair) => pair,
        Err(err) => {
            let line = format!("land-check summary: base={base} verdict=fail unresolved");
            return (line, Err(err.context("resolving HEAD and the base")));
        }
    };
    if land_check_git(root, &["rev-parse", "--is-shallow-repository"]).is_ok_and(|s| s == "true") {
        let line = format!("land-check summary: base={base} verdict=fail shallow");
        return (
            line,
            Err(anyhow::anyhow!(
                "this clone is shallow, and the checks read main's history (the gitops pins, the \
                 diff base), so they would fail for the clone rather than the change; run `git \
                 fetch --unshallow origin` and land-check again (DEC-2644)"
            )),
        );
    }
    let dir = root.join(LAND_CHECK_DIR).join("work");
    land_check_clear(root, &dir);
    let mut results: Vec<(&str, Option<bool>)> =
        LAND_CHECK_JOBS.iter().map(|job| (*job, None)).collect();
    let mut rerun = Vec::new();
    let mut unavailable = None;
    let made = land_check_git(
        root,
        &[
            "worktree",
            "add",
            "--detach",
            &dir.display().to_string(),
            &head,
        ],
    );
    let (merge_word, merged) = match made {
        Err(err) => {
            eprintln!("    land-check: no scratch worktree: {err:#}");
            ("failed", None)
        }
        Ok(_) => match land_check_git(&dir, &["merge", "--no-edit", "--no-ff", &base_sha])
            .and_then(|_| land_check_git(&dir, &["rev-parse", "HEAD"]))
        {
            Err(err) => {
                eprintln!("    land-check: the merge of {base} did not succeed: {err:#}");
                land_check_git(&dir, &["merge", "--abort"]).ok();
                ("conflict", None)
            }
            Ok(merged) => {
                for (job, passed) in &mut results {
                    match run(&dir, &base_sha, job) {
                        Ok(again) => {
                            rerun.extend(again);
                            *passed = Some(true);
                        }
                        Err(err) => {
                            eprintln!("    land-check: {job}: {err:#}");
                            unavailable = unavailable.or_else(|| {
                                err.chain()
                                    .find_map(|cause| cause.downcast_ref::<RerunUnavailable>())
                                    .map(|why| why.0)
                            });
                            *passed = Some(false);
                        }
                    }
                }
                ("clean", Some(merged))
            }
        },
    };
    land_check_clear(root, &dir);
    let passed = fetched != Some(false)
        && merged.is_some()
        && results.iter().all(|(_, passed)| *passed == Some(true));
    let jobs: Vec<String> = results
        .iter()
        .map(|(job, passed)| {
            let word = match passed {
                Some(true) => "pass",
                Some(false) => "fail",
                None => "not-run",
            };
            format!("{job}={word}")
        })
        .collect();
    let line = format!(
        "land-check summary: head={} base={base}@{} fetched={fetched_word} merged={} \
         merge={merge_word} {} rerun_unprivileged=[{}]{} verdict={}",
        short(&head),
        short(&base_sha),
        merged.as_deref().map_or_else(|| "none".to_owned(), short),
        jobs.join(" "),
        rerun.join(","),
        unavailable.map_or_else(String::new, |why| format!(" rerun_unavailable={why}")),
        if passed { "pass" } else { "fail" },
    );
    let verdict = if passed {
        Ok(())
    } else {
        Err(anyhow::anyhow!("land-check failed: {line}"))
    };
    (line, verdict)
}

fn sh(program: &str, args: &[&str]) -> Result<()> {
    eprintln!("    $ {program} {}", args.join(" "));
    let status = Command::new(program)
        .args(args)
        .status()
        .with_context(|| format!("starting `{program}` (is it installed? see AGENTS.md)"))?;
    if !status.success() {
        bail!("`{program} {}` failed with {status}", args.join(" "));
    }
    Ok(())
}

fn output(program: &str, args: &[&str]) -> Result<String> {
    output_in(Path::new("."), program, args)
}

fn output_in(dir: &Path, program: &str, args: &[&str]) -> Result<String> {
    let out = Command::new(program)
        .current_dir(dir)
        .args(args)
        .output()
        .with_context(|| format!("starting `{program}`"))?;
    if !out.status.success() {
        bail!(
            "`{program} {}` failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&out.stderr)
        );
    }
    String::from_utf8(out.stdout).context("non-UTF-8 output")
}

/// `ci lint`: the lint job over the repository at `root`, its backlog check against the diff base
/// that `var` reads from `MANDATE_BASE_REF` and `GITHUB_EVENT_NAME`, as every diff-based job
/// resolves it (DEC-2373). `ci` passes the process environment, which a test pins.
fn ci_lint(
    root: &Path,
    var: impl Fn(&str) -> Option<String>,
    workspace_checks: impl FnOnce() -> Result<()>,
) -> Result<()> {
    let base = base_ref_in(
        root,
        var("MANDATE_BASE_REF").as_deref(),
        var("GITHUB_EVENT_NAME").as_deref(),
    )?;
    lint(root, base.as_deref(), workspace_checks)
}

/// The lint job over the repository at `root` (ADR-0001 ES-12): ShellCheck over its
/// `.github/scripts/` (DEC-329), `deploy/` (the demo host's runbook, DEC-822) and `scripts/` (the
/// founder's runbooks, R0's rehearsal first), actionlint over its `.github/workflows/` (DEC-330), then
/// `workspace_checks`, the checks that need the Cargo and uv workspaces, which `ci lint` passes as
/// [`workspace_lint`]. The job takes the repository it runs in, so a fixture repository drives it
/// and neither tool's result can be dropped without a test failing (DEC-331, the DEC-139 pattern).
/// `base` is the diff base the backlog check compares against, `None` to skip it (DEC-2373).
fn lint(
    root: &Path,
    base: Option<&str>,
    workspace_checks: impl FnOnce() -> Result<()>,
) -> Result<()> {
    shellcheck_scripts(&root.join(".github/scripts"))?;
    shellcheck_scripts(&root.join("deploy"))?;
    shellcheck_scripts(&root.join("scripts"))?;
    actionlint_workflows(&root.join(".github/workflows"))?;
    live_feature_in(root)?;
    infra_workflow_in(root)?;
    mail::guard_in(root)?;
    leak::guard_in(root)?;
    deferring::guard_in(root)?;
    backlog_rows_in(root, base)?;
    workspace_checks()
}

/// The conflict-marker check, the one script both CI paths run: the docs-only path's
/// `docs-checks.sh` and this lint job, since a conflict left in a Markdown file reaches only the
/// first (`deploy/cell/README.md` after #2622).
const CONFLICT_MARKERS: &str = ".github/scripts/conflict-markers.sh";

/// [`CONFLICT_MARKERS`] over the git repository at `root`: refuses every tracked file with a line
/// that starts with one of git's conflict markers, naming its path and line.
fn conflict_markers_in(root: &Path) -> Result<()> {
    let script = repo_root()?.join(CONFLICT_MARKERS);
    eprintln!("    $ bash {CONFLICT_MARKERS}");
    let out = Command::new("bash")
        .arg(&script)
        .current_dir(root)
        .output()
        .context("starting `bash`")?;
    let stderr = String::from_utf8_lossy(&out.stderr);
    eprint!("{}{stderr}", String::from_utf8_lossy(&out.stdout));
    if !out.status.success() {
        bail!("{}", stderr.trim());
    }
    Ok(())
}

/// The backlog every story and debt row was written to until DEC-2373.
const BACKLOG: &str = "docs/project/06-backlog-v1.md";

/// Where a new backlog row goes since DEC-2373: one file each, so two PRs adding rows never touch
/// the same lines.
const BACKLOG_ROWS: &str = "docs/project/backlog/";

/// DEC-2373: a change adds no row to [`BACKLOG`]; a new row is a file under [`BACKLOG_ROWS`]. A
/// row is folded in, not new, only when a row file the change deletes, not moves, held that very
/// row at `base` under a name that starts with its story. Skipped with no diff base, as on a push
/// to `main`.
fn backlog_rows_in(root: &Path, base: Option<&str>) -> Result<()> {
    eprintln!("    backlog: checking that new rows go one file each under {BACKLOG_ROWS}");
    let Some(base) = base else {
        return Ok(());
    };
    let before =
        output_in(root, "git", &["show", &format!("{base}:{BACKLOG}")]).unwrap_or_default();
    let after = fs::read_to_string(root.join(BACKLOG)).context("reading the backlog")?;
    let changed = output_in(
        root,
        "git",
        &["diff", "--name-status", "--find-renames", base],
    )?;
    let mut folded = Vec::new();
    for path in changed
        .lines()
        .filter_map(|line| line.strip_prefix("D\t"))
        .filter(|path| is_backlog_row(path))
    {
        let held = output_in(root, "git", &["show", &format!("{base}:{path}")])?;
        folded.push((path.to_owned(), held));
    }
    if let Some(problem) = backlog_row_problem(&before, &after, &folded) {
        bail!("backlog: {problem}");
    }
    Ok(())
}

/// The rows a backlog text holds, each as its key and its trimmed opening line. A row is a bullet
/// opening in bold at the margin, an indented bold bullet naming a story, or a table row naming
/// one. Its key is the story it names in bold, else its bold lead, else a table row's first cell,
/// so editing a row's text keeps its key and only a row new to the text adds one.
fn backlog_rows(text: &str) -> Vec<(String, String)> {
    text.lines()
        .filter_map(|line| {
            let trimmed = line.trim();
            let indented = line.starts_with(char::is_whitespace);
            let key = if let Some(lead) = trimmed
                .strip_prefix("- **")
                .or_else(|| trimmed.strip_prefix("* **"))
            {
                match story_id(lead) {
                    Some(story) if lead.starts_with(story.as_str()) => Some(story),
                    _ if indented => None,
                    _ => Some(lead.split("**").next().unwrap_or(lead).to_owned()),
                }
            } else if trimmed.starts_with('|') && story_id(trimmed).is_some() {
                trimmed.split('|').nth(1).map(|cell| cell.trim().to_owned())
            } else {
                None
            };
            key.map(|key| (key, trimmed.to_owned()))
        })
        .collect()
}

/// The first story id, `E<n>-<n>`, that `text` names.
fn story_id(text: &str) -> Option<String> {
    let digits = |s: &str| s.len() - s.trim_start_matches(|c: char| c.is_ascii_digit()).len();
    text.match_indices('E').find_map(|(at, _)| {
        let rest = &text[at + 1..];
        let epic = digits(rest);
        let story = rest[epic..].strip_prefix('-').map(digits)?;
        let before_ok = !text[..at].ends_with(|c: char| c.is_ascii_alphanumeric());
        (epic > 0 && story > 0 && before_ok).then(|| text[at..at + 2 + epic + story].to_owned())
    })
}

/// Whether `path` is a row file under [`BACKLOG_ROWS`], not its README.
fn is_backlog_row(path: &str) -> bool {
    path.strip_prefix(BACKLOG_ROWS)
        .is_some_and(|name| name.ends_with(".md") && name != "README.md" && !name.contains('/'))
}

/// The refusal for a backlog that went from `before` to `after` while the change deleted the row
/// files `folded`, each its path and the text it held at the base, or `None` when every row new
/// to the backlog is one of those files' rows, each file's row folded once, under a file name
/// that starts with the row's story.
fn backlog_row_problem(before: &str, after: &str, folded: &[(String, String)]) -> Option<String> {
    let mut known: Vec<String> = backlog_rows(before)
        .into_iter()
        .map(|(key, _)| key)
        .collect();
    let mut files: Vec<(&str, (String, String))> = folded
        .iter()
        .flat_map(|(path, held)| {
            let name = path.rsplit('/').next().unwrap_or(path);
            backlog_rows(held).into_iter().map(move |row| (name, row))
        })
        .collect();
    let mut unfolded = Vec::new();
    for (key, line) in backlog_rows(after) {
        if let Some(at) = known.iter().position(|old| *old == key) {
            known.swap_remove(at);
            continue;
        }
        let names_story =
            |name: &str| story_id(&key).is_none_or(|story| name.starts_with(&format!("{story}-")));
        match files
            .iter()
            .position(|(name, (_, held))| *held == line && names_story(name))
        {
            Some(at) => {
                files.swap_remove(at);
            }
            None => unfolded.push(key),
        }
    }
    (!unfolded.is_empty()).then(|| {
        format!(
            "{BACKLOG} gains {} row(s) no deleted row file held ({}); add a new row as its own \
             file under {BACKLOG_ROWS}, and fold one in only by deleting the file that holds it \
             (DEC-2373)",
            unfolded.len(),
            unfolded.join(", ")
        )
    })
}

/// The lint job's checks over the Cargo and uv workspaces in the current directory: fmt, clippy
/// `-D warnings`, crate layering, the decision numbers, conflict markers, markers, saved proptest
/// seeds, the feature map, typos, and ruff.
fn workspace_lint() -> Result<()> {
    sh("cargo", &["fmt", "--all", "--check"])?;
    sh(
        "cargo",
        &[
            "clippy",
            "--workspace",
            "--all-targets",
            "--locked",
            "--",
            "-D",
            "warnings",
        ],
    )?;
    layers()?;
    decision_numbers(Path::new("."))?;
    conflict_markers_in(Path::new("."))?;
    markers()?;
    proptest_seeds()?;
    feature_map()?;
    cell::generate(false)?;
    sh("typos", &[])?;
    uv_tools(&["ruff", "check", "."])?;
    uv_tools(&["ruff", "format", "--check", "."])
}

/// The decision-number check (DEC-2600 item 3), the one script both CI paths run: the docs-only
/// path's `docs-checks.sh` and this lint job.
const DECISION_NUMBERS: &str = ".github/scripts/decision-numbers.sh";

/// [`DECISION_NUMBERS`] over the repository at `root`: refuses two decision files anywhere in the
/// tree that take one number, and a decision whose heading names a number other than its file's.
fn decision_numbers(root: &Path) -> Result<()> {
    let script = repo_root()?.join(DECISION_NUMBERS);
    eprintln!("    $ bash {DECISION_NUMBERS}");
    let out = Command::new("bash")
        .arg(&script)
        .current_dir(root)
        .output()
        .context("starting `bash`")?;
    let stderr = String::from_utf8_lossy(&out.stderr);
    eprint!("{}{stderr}", String::from_utf8_lossy(&out.stdout));
    if !out.status.success() {
        bail!("decisions: {}", stderr.trim());
    }
    Ok(())
}

/// Every file under `dir` whose extension is one of `extensions`, sorted by path so the linter's
/// command line and report order are stable (E1-4, DEC-329). Directory symlinks are not followed.
fn files_by_extension(dir: &Path, extensions: &[&str]) -> Result<Vec<PathBuf>> {
    let mut files = Vec::new();
    let mut pending = vec![dir.to_path_buf()];
    while let Some(dir) = pending.pop() {
        let mut entries: Vec<_> = fs::read_dir(&dir)
            .with_context(|| format!("reading {}", dir.display()))?
            .collect::<Result<Vec<_>, _>>()?;
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries {
            let path = entry.path();
            if entry
                .file_type()
                .with_context(|| format!("reading {}", path.display()))?
                .is_dir()
            {
                pending.push(path);
            } else if path
                .extension()
                .is_some_and(|e| extensions.contains(&e.to_string_lossy().as_ref()))
            {
                files.push(path);
            }
        }
    }
    files.sort();
    Ok(files)
}

/// Runs a linter over paths and embeds its findings in the failure, so a planted `SC2086` or an
/// unknown workflow key fails the job naming its code. Both tools report their findings on stdout
/// and keep stderr for their own errors, so both streams travel with the failure. A missing
/// binary is the loud error [`sh`] reports, never a silent skip (E1-4, DEC-330).
fn lint_paths(program: &str, args: &[String]) -> Result<()> {
    eprintln!("    $ {program} {}", args.join(" "));
    let out = Command::new(program)
        .args(args)
        .output()
        .with_context(|| format!("starting `{program}` (is it installed? see AGENTS.md)"))?;
    if !out.status.success() {
        let mut findings = String::from_utf8_lossy(&out.stdout).into_owned();
        let stderr = String::from_utf8_lossy(&out.stderr);
        if !stderr.trim().is_empty() {
            if !findings.trim().is_empty() {
                findings.push('\n');
            }
            findings.push_str(&stderr);
        }
        bail!(
            "`{program} {}` failed: {}",
            args.join(" "),
            findings.trim_end()
        );
    }
    Ok(())
}

/// ShellCheck over every `*.sh` under `.github/scripts/` (E1-4, DEC-329), the shell that CI's
/// short path and the merge gate run as they are on the default branch. A directory holding no
/// scripts still runs the version check, so an uninstalled tool fails the job it belongs to.
fn shellcheck_scripts(dir: &Path) -> Result<()> {
    let scripts = files_by_extension(dir, &["sh"])?;
    if scripts.is_empty() {
        return sh("shellcheck", &["--version"]);
    }
    let args: Vec<String> = scripts
        .iter()
        .map(|path| path.to_string_lossy().into_owned())
        .collect();
    lint_paths("shellcheck", &args)
}

/// actionlint over every `*.yml` and `*.yaml` under `.github/workflows/` (E1-4, DEC-330), so a
/// workflow mistake fails `fast` instead of waiting for a reviewer. A directory holding no
/// workflows still runs the version check, so an uninstalled tool fails the job it belongs to.
fn actionlint_workflows(dir: &Path) -> Result<()> {
    let workflows = files_by_extension(dir, &["yml", "yaml"])?;
    if workflows.is_empty() {
        return sh("actionlint", &["--version"]);
    }
    let args: Vec<String> = workflows
        .iter()
        .map(|path| path.to_string_lossy().into_owned())
        .collect();
    lint_paths("actionlint", &args)
}

#[derive(Deserialize)]
struct Finding {
    #[serde(rename = "File")]
    file: String,
    #[serde(rename = "RuleID")]
    rule_id: String,
    /// The commit a `gitleaks git` finding is in; a `gitleaks dir` finding has none.
    #[serde(rename = "Commit", default)]
    commit: String,
    #[serde(rename = "StartLine", default)]
    start_line: u64,
}

