/// `ci secrets`, a part of `supply-chain` that land-check also runs (DEC-2645): gitleaks over the
/// commits since the diff base, or over the tree with none, then the `.gitleaks.toml` exceptions'
/// own cases, so a secret, or an exception that stopped working, is caught before a landing.
fn secrets() -> Result<()> {
    match base_ref()? {
        Some(base) => sh(
            "gitleaks",
            &[
                "git",
                "--no-banner",
                "--redact",
                &format!("--log-opts={base}..HEAD"),
            ],
        ),
        None => sh("gitleaks", &["dir", "--no-banner", "--redact", "."]),
    }?;
    gitleaks_exceptions()?;
    gitleaks_ignore()
}

/// Scans [`gitleaks_plants`], written to a temporary directory, with the repository's
/// `.gitleaks.toml`: exactly the expected findings must be reported.
fn gitleaks_exceptions() -> Result<()> {
    let dir = unique_temp_path("mandate-gitleaks", "");
    let report_path = dir.with_extension("json");
    let mut expected = BTreeMap::new();
    for (path, line, rule) in gitleaks_plants() {
        let file = dir.join(&path);
        fs::create_dir_all(file.parent().context("planted file has no parent")?)?;
        let mut out = fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&file)?;
        writeln!(out, "{line}")?;
        if let Some(rule) = rule {
            *expected.entry((path, rule.to_owned())).or_insert(0) += 1;
        }
    }
    let config = repo_root()?.join(".gitleaks.toml");
    eprintln!("    $ (in a temporary directory) gitleaks dir --config .gitleaks.toml .");
    let status = Command::new("gitleaks")
        .current_dir(&dir)
        .args([
            "dir",
            "--no-banner",
            "--exit-code",
            "0",
            "--report-format",
            "json",
        ])
        .arg("--config")
        .arg(&config)
        .arg("--report-path")
        .arg(&report_path)
        .arg(".")
        .status()
        .context("starting `gitleaks` (is it installed? see AGENTS.md)")?;
    let report_text = fs::read_to_string(&report_path);
    fs::remove_dir_all(&dir)?;
    if !status.success() {
        bail!("gitleaks failed on the planted cases with {status}");
    }
    fs::remove_file(&report_path)?;
    let findings: Vec<Finding> = serde_json::from_str(&report_text?)?;
    let mut found = BTreeMap::new();
    for f in findings {
        *found.entry((f.file, f.rule_id)).or_insert(0) += 1;
    }
    let keys: BTreeSet<_> = expected.keys().chain(found.keys()).collect();
    let problems: Vec<String> = keys
        .into_iter()
        .filter_map(|key @ (file, rule)| {
            let (want, got) = (
                expected.get(key).unwrap_or(&0),
                found.get(key).unwrap_or(&0),
            );
            (want != got)
                .then(|| format!("{file}: {rule} reported {got} finding(s), expected {want}"))
        })
        .collect();
    report(problems, "gitleaks-exceptions")?;
    eprintln!(
        "    gitleaks-exceptions: {} planted findings reported",
        expected.values().sum::<usize>()
    );
    Ok(())
}

/// The fingerprints gitleaks skips (DEC-2647): each names one finding, one rule on one line of
/// one file in one commit, for a test-fixture value that only the history still holds.
const GITLEAKS_IGNORE: &str = ".gitleaksignore";

/// `.gitleaksignore`'s lines that are neither a comment, blank, nor a commit-pinned fingerprint.
/// A fingerprint without its commit, `<path>:<rule>:<line>`, makes gitleaks skip that line of that
/// file in every commit, so a key later written there would pass unreported.
fn gitleaks_ignore_problems(text: &str) -> Vec<String> {
    text.lines()
        .enumerate()
        .filter(|(_, line)| !line.trim().is_empty() && !line.starts_with('#'))
        .filter(|(_, line)| !is_pinned_fingerprint(line))
        .map(|(index, line)| {
            format!(
                "{GITLEAKS_IGNORE}:{}: `{line}` is not `<40-hex commit>:<path>:<rule>:<line>`",
                index + 1
            )
        })
        .collect()
}

/// Whether `line` is `<40 lower-case hex>:<path>:<rule>:<line number from 1>`, with no space.
fn is_pinned_fingerprint(line: &str) -> bool {
    let parts: Vec<&str> = line.split(':').collect();
    let [commit, path, rule, number] = parts.as_slice() else {
        return false;
    };
    commit.len() == 40
        && commit
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
        && !path.is_empty()
        && !path.contains(char::is_whitespace)
        && !rule.is_empty()
        && rule
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
        && !number.starts_with('0')
        && !number.is_empty()
        && number.bytes().all(|b| b.is_ascii_digit())
}

/// The repository's [`GITLEAKS_IGNORE`] must hold only commit-pinned fingerprints, and
/// [`gitleaks_ignore_case`] must show one skipping exactly its own finding.
fn gitleaks_ignore() -> Result<()> {
    let path = repo_root()?.join(GITLEAKS_IGNORE);
    if path.exists() {
        report(
            gitleaks_ignore_problems(&fs::read_to_string(&path)?),
            "gitleaks-ignore",
        )?;
    }
    gitleaks_ignore_case()
}

/// A planted two-commit repository, scanned with the repository's `.gitleaks.toml`: the first
/// commit adds a key-ID-shaped line and the second another in the same file. Without a
/// [`GITLEAKS_IGNORE`] both are reported, so the case is not vacuous; with the first commit's
/// fingerprint only the second is.
fn gitleaks_ignore_case() -> Result<()> {
    let dir = unique_temp_path("mandate-gitleaks-ignore", "");
    fs::create_dir_all(&dir)?;
    let outcome = gitleaks_ignore_case_in(&dir);
    fs::remove_dir_all(&dir)?;
    outcome
}

fn gitleaks_ignore_case_in(dir: &Path) -> Result<()> {
    let git = |args: &[&str]| {
        let mut full = vec![
            "-c",
            "user.name=xtask",
            "-c",
            "user.email=xtask@example.invalid",
            "-c",
            "commit.gpgsign=false",
        ];
        full.extend_from_slice(args);
        output_in(dir, "git", &full)
    };
    let file = "planted.rs";
    let first = format!("const FIRST: &str = \"PK{}\";", "PLANTEDKEYID000000");
    let second = format!("const SECOND: &str = \"PK{}\";", "PLANTEDKEYID000001");
    git(&["init", "-q"])?;
    fs::write(dir.join(file), format!("{first}\n"))?;
    git(&["add", file])?;
    git(&["commit", "-q", "-m", "first"])?;
    let first_commit = git(&["rev-parse", "HEAD"])?.trim().to_owned();
    fs::write(dir.join(file), format!("{first}\n{second}\n"))?;
    git(&["commit", "-q", "-a", "-m", "second"])?;
    let second_commit = git(&["rev-parse", "HEAD"])?.trim().to_owned();
    let rule = "alpaca-key-id";
    let mut problems = Vec::new();
    let unignored = gitleaks_git_findings(dir)?;
    if unignored.len() != 2 {
        problems.push(format!(
            "with no fingerprint, {} finding(s), expected both planted keys",
            unignored.len()
        ));
    }
    fs::write(
        dir.join(GITLEAKS_IGNORE),
        format!("{first_commit}:{file}:{rule}:1\n"),
    )?;
    let ignored: Vec<(String, String, String, u64)> = gitleaks_git_findings(dir)?
        .into_iter()
        .map(|f| (f.file, f.rule_id, f.commit, f.start_line))
        .collect();
    let expected = vec![(file.to_owned(), rule.to_owned(), second_commit, 2)];
    if ignored != expected {
        problems.push(format!(
            "with the first commit's fingerprint, {ignored:?}, expected only {expected:?}"
        ));
    }
    report(problems, "gitleaks-ignore")?;
    eprintln!("    gitleaks-ignore: a fingerprint skips its own finding and no other");
    Ok(())
}

/// `gitleaks git` over the repository at `dir`, with the repository's `.gitleaks.toml` and the
/// `.gitleaksignore` in `dir`, if any: its findings.
fn gitleaks_git_findings(dir: &Path) -> Result<Vec<Finding>> {
    let report_path = dir.with_extension("json");
    eprintln!("    $ (in a planted repository) gitleaks git --config .gitleaks.toml .");
    let status = Command::new("gitleaks")
        .current_dir(dir)
        .args([
            "git",
            "--no-banner",
            "--redact",
            "--exit-code",
            "0",
            "--report-format",
            "json",
        ])
        .arg("--config")
        .arg(repo_root()?.join(".gitleaks.toml"))
        .arg("--report-path")
        .arg(&report_path)
        .arg(".")
        .status()
        .context("starting `gitleaks` (is it installed? see AGENTS.md)")?;
    let report_text = fs::read_to_string(&report_path);
    fs::remove_file(&report_path).ok();
    if !status.success() {
        bail!("gitleaks failed on the planted repository with {status}");
    }
    Ok(serde_json::from_str(&report_text?)?)
}

/// Runs a tool from the `python/` uv workspace (ruff, pytest, the exporter).
fn uv_tools(args: &[&str]) -> Result<()> {
    let mut full = vec!["run", "--locked", "--directory", "python"];
    full.extend_from_slice(args);
    sh("uv", &full)
}

/// Runs a frozen reference script, named relative to `reference/`, in the reference
/// implementations' own pinned environment (ADR-0001 ES-10): `reference/mandate/requirements.txt`
/// pins the PyYAML and jsonschema that `reference/journal/` needs too, so one environment serves
/// both. The per-PR `reference` job runs the mandate reference's generator, case check and three
/// fuzz seeds, the journal generator's `--check` (its self-test, validators, independent
/// recomputation and seeded bugs, then the committed `journal.yaml` must match what it generates;
/// #443 round 3, #476 round 1), and [`mutation_anchors`]; the nightly adds seven fuzz seeds and the
/// mutant sweep.
fn reference(script_and_args: &[&str]) -> Result<()> {
    let Some((script, rest)) = script_and_args.split_first() else {
        bail!("no reference script given");
    };
    pinned_python(&format!("reference/{script}"), rest)
}

/// How the schema jobs run a script: its repository path and its arguments ([`pinned_python`]).
type ScriptRunner<'a> = dyn FnMut(&str, &[&str]) -> Result<()> + 'a;

/// The `schemas` job: each of [`SCHEMA_CHECKERS`], by its repository path, through `run`.
fn schema_checks(run: &mut ScriptRunner) -> Result<()> {
    for checker in SCHEMA_CHECKERS {
        run(&format!("{SCHEMA_DIR}/{checker}"), &[])?;
    }
    Ok(())
}

/// The `schema-mutants` job: the sweep counts a mutant caught when any checker fails, so it first
/// runs [`schema_checks`] on the unmutated tree, and runs no mutant unless all three pass; a
/// failing baseline would otherwise report every mutant caught (DEC-688). With `shard`, `K/N`, the
/// sweep runs only that shard (`mutate_schemas.py --shard K/N`, which validates it); every shard
/// checks the baseline itself, so CI's matrix needs no job of its own for it.
fn schema_mutants(shard: Option<&str>, run: &mut ScriptRunner) -> Result<()> {
    schema_checks(run)
        .context("baseline fails: fix the schemas before mutants mean anything (DEC-688)")?;
    let args: Vec<&str> = shard.map(|s| vec!["--shard", s]).unwrap_or_default();
    run(&format!("{SCHEMA_DIR}/mutate_schemas.py"), &args)
}

/// Runs the Python script at `path`, from the repository root, in the environment
/// `reference/mandate/requirements.txt` pins: the reference implementations' and the workspace API
/// schema checkers' (DEC-688).
fn pinned_python(path: &str, rest: &[&str]) -> Result<()> {
    let mut full = vec![
        "run",
        "--no-project",
        "--python",
        "3.14",
        "--with-requirements",
        "reference/mandate/requirements.txt",
        "python",
        path,
    ];
    full.extend_from_slice(rest);
    sh("uv", &full)
}

/// The anchor-only check of `reference/mandate/mutants.py` (#443 round 3): every mutant's `old`
/// text must still occur in `ref.py`, which the sweep asserts before its first run. Only the
/// nightly runs the sweep, so an anchor an edit to `ref.py` left behind passed every per-PR job
/// until this check; it runs in well under a second from the `python/` workspace, which lints and
/// tests it (`python/mandate_tools/tests/test_mutation_anchors.py`).
fn mutation_anchors() -> Result<()> {
    uv_tools(&[
        "python",
        "-m",
        "mandate_tools.mutation_anchors",
        "../reference/mandate",
    ])
    .context(
        "a mutation anchor in reference/mandate/mutants.py no longer matches ref.py; re-anchor it, or the nightly's mutants.py fails before its first run",
    )
}

/// Why this xtask may not run where it was invoked: the checkout it was built from, `built`, is not
/// the one it runs in, `invoked` (the invoking directory's git toplevel), which happens when two
/// checkouts share one `CARGO_TARGET_DIR`, and so one xtask binary rooted at whichever built last
/// (lane NE, 2026-10-26). Every check would then read the other tree, and pass or fail for it.
/// `None` when they are the same directory, or when either cannot be resolved (no git here).
fn root_mismatch(built: &Path, invoked: Option<&Path>) -> Option<String> {
    let invoked = invoked?;
    let (Ok(built_real), Ok(invoked_real)) = (fs::canonicalize(built), fs::canonicalize(invoked))
    else {
        return None;
    };
    (built_real != invoked_real).then(|| {
        format!(
            "this xtask was built from the checkout at {} but runs in {}, so it would check the \
             other tree: two checkouts share one CARGO_TARGET_DIR (give this one its own: unset \
             CARGO_TARGET_DIR, or point it at a directory only this checkout uses, and run it \
             again), or this tree sits inside another git repository, which git answered for",
            built_real.display(),
            invoked_real.display()
        )
    })
}

fn repo_root() -> Result<PathBuf> {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    manifest_dir
        .parent()
        .map(Path::to_path_buf)
        .context("xtask has no parent directory")
}

#[derive(Deserialize)]
struct Metadata {
    packages: Vec<Package>,
    workspace_members: Vec<String>,
    /// The members a cargo invocation selects when it names no package: `default-members`, or
    /// every member when the workspace sets none. A live-only package counts in a build only
    /// when the build's selected packages reach it (DEC-868 item 2).
    workspace_default_members: Vec<String>,
}

#[derive(Deserialize)]
struct Package {
    id: String,
    name: String,
    manifest_path: PathBuf,
    dependencies: Vec<Dependency>,
    targets: Vec<Target>,
    /// The package's `[features]`: each name with what it enables.
    #[serde(default)]
    features: BTreeMap<String, Vec<String>>,
}

#[derive(Deserialize)]
struct Dependency {
    name: String,
    kind: Option<String>,
    path: Option<PathBuf>,
    /// The features this dependency turns on in the crate it names.
    #[serde(default)]
    features: Vec<String>,
    /// Whether the crate it names keeps its default features.
    #[serde(default = "keeps_defaults")]
    uses_default_features: bool,
}

/// What cargo assumes when a dependency says nothing of its default features: they stay on.
fn keeps_defaults() -> bool {
    true
}

#[derive(Deserialize)]
struct Target {
    kind: Vec<String>,
}

fn metadata() -> Result<Metadata> {
    metadata_in(Path::new("."))
}

fn metadata_in(dir: &Path) -> Result<Metadata> {
    let json = output_in(
        dir,
        "cargo",
        &["metadata", "--format-version", "1", "--no-deps", "--locked"],
    )?;
    serde_json::from_str(&json).context("parsing cargo metadata")
}

fn workspace_packages(meta: &Metadata) -> Vec<&Package> {
    let members: BTreeSet<&str> = meta.workspace_members.iter().map(String::as_str).collect();
    meta.packages
        .iter()
        .filter(|p| members.contains(p.id.as_str()))
        .collect()
}

/// Every workspace package with the workspace packages it is built on, itself included. A test
/// exercises exactly the code its own package links, so this is what turns the reference
/// harness's dependency list into the full set of packages its suites can fail on (DEC-497),
/// without anyone auditing which call reaches which layer.
fn workspace_closure(meta: &Metadata) -> BTreeMap<String, BTreeSet<String>> {
    let dirs = member_dirs(meta);
    let direct: BTreeMap<&str, Vec<&str>> = workspace_packages(meta)
        .into_iter()
        .map(|pkg| {
            let deps = pkg
                .dependencies
                .iter()
                .filter(|dep| on_member(dep, &dirs))
                .map(|dep| dep.name.as_str())
                .collect();
            (pkg.name.as_str(), deps)
        })
        .collect();
    direct
        .keys()
        .map(|package| {
            let mut reached = BTreeSet::new();
            let mut pending = vec![*package];
            while let Some(next) = pending.pop() {
                if reached.insert(next.to_owned()) {
                    pending.extend(direct.get(next).into_iter().flatten().copied());
                }
            }
            ((*package).to_owned(), reached)
        })
        .collect()
}

/// Each workspace member's directory, by name: where a path dependency on it must point.
fn member_dirs(meta: &Metadata) -> BTreeMap<&str, &Path> {
    workspace_packages(meta)
        .into_iter()
        .filter_map(|pkg| Some((pkg.name.as_str(), pkg.manifest_path.parent()?)))
        .collect()
}

/// Whether `dep` is a path dependency on the workspace member it names, by that member's
/// directory, not by name alone: a crate outside the workspace can take a member's name (DEC-525).
fn on_member(dep: &Dependency, dirs: &BTreeMap<&str, &Path>) -> bool {
    dep.path
        .as_deref()
        .is_some_and(|path| dirs.get(dep.name.as_str()) == Some(&path))
}

#[derive(Deserialize)]
struct Layers {
    impure_crates: Vec<String>,
    /// Crates planned but not yet created, which a `forbidden_internal` list may already name
    /// (DEC-525).
    #[serde(default)]
    planned: Vec<String>,
    /// The two process groups of a workspace deployment, which meet only in the journal (E21-42,
    /// DEC-986).
    #[serde(default)]
    process_groups: ProcessGroups,
    crates: BTreeMap<String, CratePolicy>,
}

/// The crates of each side of a workspace deployment: the workspace services (the API, the
/// control services, the dispatcher, `cp-agent`) and the agent processes (the runtime's host, the
/// executor and its connectors). No crate of one side may reach a crate of the other through any
/// chain of path dependencies, so the two can meet only in the journal (E21-42, DEC-986). A crate
/// in neither list is a shared library or a tool.
#[derive(Deserialize, Default)]
struct ProcessGroups {
    #[serde(default)]
    workspace_services: Vec<String>,
    #[serde(default)]
    agent_process: Vec<String>,
}

#[derive(Deserialize)]
struct CratePolicy {
    layer: toml::Value,
    safety_critical: bool,
    pure: bool,
    #[serde(default)]
    allowed_external: Vec<String>,
    /// Workspace crates this crate may never reach, directly or through any chain of path
    /// dependencies, dev-dependencies included, whatever the layers allow (DEC-525).
    #[serde(default)]
    forbidden_internal: Vec<String>,
    /// When set, the only workspace crates that may depend on this crate, by a dependency of any
    /// kind: an allowlist, so a crate added later is refused until it is named (DEC-642 item 7).
    #[serde(default)]
    allowed_dependents: Option<Vec<String>>,
    /// Whether every workspace crate that depends on this one must do so as a dev-dependency, as
    /// test support must (DEC-645).
    #[serde(default)]
    dev_only: bool,
    /// The one crate that may declare a `live` cargo feature: the deployment runner (ES-23 as
    /// DEC-529 item 3 narrows it). No crate is marked until the runner's G1a slice marks it.
    #[serde(default)]
    live_feature: bool,
}

enum Layer {
    Product(i64),
    Tool,
}

fn layer_of(policy: &CratePolicy, name: &str) -> Result<Layer> {
    match &policy.layer {
        toml::Value::Integer(n) => Ok(Layer::Product(*n)),
        toml::Value::String(s) if s == "tool" => Ok(Layer::Tool),
        other => bail!("xtask/layers.toml: `{name}` has invalid layer {other}"),
    }
}

fn layers() -> Result<()> {
    eprintln!("    layers: checking xtask/layers.toml against cargo metadata");
    let policy: Layers = toml::from_str(&fs::read_to_string("xtask/layers.toml")?)
        .context("parsing xtask/layers.toml")?;
    let mut problems = layer_problems(&policy, &metadata()?)?;
    problems.extend(codeowners_problems(
        &fs::read_to_string("CODEOWNERS").context("reading CODEOWNERS")?,
        &policy,
    ));
    report(problems, "layers")
}

/// Every way the CODEOWNERS text `text` breaks `policy` (ADR-0001 ES-13, DEC-2600 item 5): a
/// safety-critical crate with no `/crates/<name>/` line, crate lines out of sorted order, which
/// would send two PRs adding two crates to the same place in the file, and a crate line kept
/// twice, which a union merge of two edits to one line leaves.
fn codeowners_problems(text: &str, policy: &Layers) -> Vec<String> {
    let lines: Vec<&str> = text
        .lines()
        .filter_map(|line| line.split_whitespace().next())
        .filter(|path| path.starts_with("/crates/"))
        .collect();
    let mut problems = Vec::new();
    for (name, own) in &policy.crates {
        let path = format!("/crates/{name}/");
        if own.safety_critical && !lines.contains(&path.as_str()) {
            problems.push(format!(
                "safety-critical crate `{name}` has no `{path}` line in CODEOWNERS"
            ));
        }
    }
    for pair in lines.windows(2) {
        if let [before, after] = pair
            && after <= before
        {
            problems.push(if after == before {
                format!("CODEOWNERS: `{after}` has two lines; keep one")
            } else {
                format!(
                    "CODEOWNERS: `{after}` must come before `{before}`; keep the crate lines sorted"
                )
            });
        }
    }
    problems
}

/// Every way the workspace in `meta` breaks `policy`.
fn layer_problems(policy: &Layers, meta: &Metadata) -> Result<Vec<String>> {
    let packages = workspace_packages(meta);
    let names: BTreeSet<&str> = packages.iter().map(|p| p.name.as_str()).collect();
    let closure = workspace_closure(meta);
    let dirs = member_dirs(meta);
    let mut problems = Vec::new();

    for listed in policy.crates.keys() {
        if !names.contains(listed.as_str()) {
            problems.push(format!(
                "`{listed}` is in layers.toml but is not a workspace member"
            ));
        }
    }
    for (listed, own) in &policy.crates {
        let unknown = own
            .forbidden_internal
            .iter()
            .filter(|name| !names.contains(name.as_str()) && !policy.planned.contains(name));
        problems.extend(unknown.map(|name| {
            format!(
                "`{listed}` forbids `{name}`, which is neither a workspace member nor in `planned`, \
                 so a misspelt name would guard nothing (DEC-525)"
            )
        }));
    }
    for (listed, own) in &policy.crates {
        let unknown = own
            .allowed_dependents
            .iter()
            .flatten()
            .filter(|name| !names.contains(name.as_str()) && !policy.planned.contains(name));
        problems.extend(unknown.map(|name| {
            format!(
                "`{listed}` allows `{name}` as a dependent, which is neither a workspace member nor \
                 in `planned` (DEC-642 item 7)"
            )
        }));
    }
    problems.extend(process_group_problems(policy, &names, &closure));
    for pkg in &packages {
        let Some(own) = policy.crates.get(&pkg.name) else {
            problems.push(format!("`{}` has no entry in xtask/layers.toml", pkg.name));
            continue;
        };
        let own_layer = layer_of(own, &pkg.name)?;
        if let Some(reached) = closure.get(&pkg.name) {
            problems.extend(forbidden_reached(
                &pkg.name,
                &own.forbidden_internal,
                reached,
            ));
        }
        for dep in &pkg.dependencies {
            if let Some(path) = dep.path.as_deref()
                && !on_member(dep, &dirs)
            {
                problems.push(format!(
                    "`{}` has a path dependency on `{}`, which is not a workspace member at {}, so \
                     the layers cannot see what it reaches (DEC-525)",
                    pkg.name,
                    dep.name,
                    path.display()
                ));
                continue;
            }
            let internal = dep.path.is_some() && names.contains(dep.name.as_str());
            if internal {
                let Some(dep_policy) = policy.crates.get(&dep.name) else {
                    continue;
                };
                if dep_policy.dev_only && dep.kind.as_deref() != Some("dev") {
                    problems.push(format!(
                        "`{}` depends on `{}`, which is dev-only in xtask/layers.toml, other than as \
                         a dev-dependency (DEC-645)",
                        pkg.name, dep.name
                    ));
                }
                if let Some(allowed) = &dep_policy.allowed_dependents
                    && !allowed.contains(&pkg.name)
                {
                    problems.push(format!(
                        "`{}` depends on `{}`, whose allowed_dependents in xtask/layers.toml does \
                         not name it (DEC-642 item 7)",
                        pkg.name, dep.name
                    ));
                }
                match (&own_layer, layer_of(dep_policy, &dep.name)?) {
                    (Layer::Product(_), Layer::Tool) => {
                        problems.push(format!(
                            "`{}` depends on tool crate `{}`",
                            pkg.name, dep.name
                        ));
                    }
                    (Layer::Product(a), Layer::Product(b))
                        if b >= *a && dep.kind.as_deref() != Some("dev") =>
                    {
                        problems.push(format!("`{}` (layer {a}) depends on `{}` (layer {b}); dependencies must point to lower layers", pkg.name, dep.name));
                    }
                    _ => {}
                }
                continue;
            }
            if own.pure && policy.impure_crates.contains(&dep.name) {
                problems.push(format!(
                    "pure crate `{}` depends on `{}`",
                    pkg.name, dep.name
                ));
            }
            if own.safety_critical
                && dep.kind.as_deref() != Some("dev")
                && !own.allowed_external.contains(&dep.name)
            {
                problems.push(format!("safety-critical crate `{}` depends on `{}`, which is not in its allowed_external list", pkg.name, dep.name));
            }
        }
        if own.safety_critical {
            let lib = pkg
                .manifest_path
                .parent()
                .map(|d| d.join("src/lib.rs"))
                .context("manifest without a directory")?;
            let text =
                fs::read_to_string(&lib).with_context(|| format!("reading {}", lib.display()))?;
            if !text.contains(REQUIRED_HEADER) {
                problems.push(format!(
                    "{} must contain the safety-critical lint header (xtask REQUIRED_HEADER)",
                    lib.display()
                ));
            }
        }
    }
    Ok(problems)
}

/// A problem for each crate in `forbidden` that `name` reaches, `reached` being every workspace
/// crate it is built on through path dependencies of any kind (DEC-525).
fn forbidden_reached(name: &str, forbidden: &[String], reached: &BTreeSet<String>) -> Vec<String> {
    forbidden
        .iter()
        .filter(|crate_name| reached.contains(*crate_name))
        .map(|crate_name| {
            format!(
                "`{name}` reaches `{crate_name}`, which its forbidden_internal list in \
                 xtask/layers.toml rules out (DEC-525)"
            )
        })
        .collect()
}

/// A problem for each workspace-services crate that reaches an agent-process crate, and each
/// agent-process crate that reaches a workspace-services crate, through path dependencies of any
/// kind (`closure`); for each group name that is neither a member of `names` nor planned; and for
/// each crate named in both groups (E21-42, DEC-986).
fn process_group_problems(
    policy: &Layers,
    names: &BTreeSet<&str>,
    closure: &BTreeMap<String, BTreeSet<String>>,
) -> Vec<String> {
    let groups = &policy.process_groups;
    let services = ("workspace services", &groups.workspace_services);
    let agents = ("agent process", &groups.agent_process);
    let mut problems = Vec::new();
    for (key, own) in [
        ("workspace_services", services.1),
        ("agent_process", agents.1),
    ] {
        problems.extend(
            own.iter()
                .filter(|name| !names.contains(name.as_str()) && !policy.planned.contains(name))
                .map(|name| {
                    format!(
                        "`{name}` is in process group `{key}` but is neither a workspace member \
                         nor in `planned` (DEC-986)"
                    )
                }),
        );
    }
    problems.extend(
        groups
            .workspace_services
            .iter()
            .filter(|name| groups.agent_process.contains(name))
            .map(|name| {
                format!(
                    "`{name}` is in both process groups, so it would sit on both sides of the \
                     boundary (DEC-986)"
                )
            }),
    );
    for ((own_label, own), (other_label, other)) in [(services, agents), (agents, services)] {
        for name in own {
            let Some(reached) = closure.get(name) else {
                continue;
            };
            problems.extend(
                other
                    .iter()
                    .filter(|crossed| *crossed != name && reached.contains(*crossed))
                    .map(|crossed| {
                        format!(
                            "`{name}` ({own_label}) reaches `{crossed}` ({other_label}); \
                             workspace services and agent processes meet only in the journal \
                             (E21-42, DEC-986)"
                        )
                    }),
            );
        }
    }
    problems
}

/// The `(ecosystem, name)` of every row of the registry text `text`.
fn registry(text: &str) -> BTreeSet<(String, String)> {
    registry_rows(text)
        .into_iter()
        .map(|row| (row.ecosystem, row.name))
        .collect()
}

/// What a cargo row's "Used by" cell says (DEC-2600 item 4): the crates are derived from `cargo
/// metadata` by `cargo xtask deps --used-by`, so no PR edits a shared list to add its crate.
const USED_BY_DERIVED: &str = "`cargo xtask deps --used-by`";

/// One row of the registry's table: its name, ecosystem, and "Used by" cell.
struct RegistryRow {
    name: String,
    ecosystem: String,
    used_by: String,
}

/// The rows of the registry text `text` shaped `| `name` | ecosystem | used by | ...`.
fn registry_rows(text: &str) -> Vec<RegistryRow> {
    let mut rows = Vec::new();
    for line in text.lines() {
        let cells: Vec<&str> = line.split('|').map(str::trim).collect();
        if let [_, name, ecosystem, used_by, ..] = cells.as_slice()
            && let Some(name) = name.strip_prefix('`').and_then(|n| n.strip_suffix('`'))
        {
            rows.push(RegistryRow {
                name: name.to_owned(),
                ecosystem: (*ecosystem).to_owned(),
                used_by: (*used_by).to_owned(),
            });
        }
    }
    rows
}

/// Every way the registry text `text` breaks its shape (DEC-2600 item 4): a name registered twice
/// in one ecosystem, which a union merge of two edits to one row would leave, and a cargo row whose
/// "Used by" cell is not [`USED_BY_DERIVED`].
fn registry_problems(text: &str) -> Vec<String> {
    let mut counts: BTreeMap<(&str, &str), usize> = BTreeMap::new();
    let rows = registry_rows(text);
    let mut problems = Vec::new();
    for row in &rows {
        *counts.entry((&row.ecosystem, &row.name)).or_default() += 1;
        if row.ecosystem == "cargo" && row.used_by != USED_BY_DERIVED {
            problems.push(format!(
                "cargo dependency `{}`'s Used by cell must be {USED_BY_DERIVED}, which derives it \
                 from cargo metadata, not a hand-kept list",
                row.name
            ));
        }
    }
    for ((ecosystem, name), count) in counts {
        if count > 1 {
            problems.push(format!(
                "{ecosystem} dependency `{name}` has {count} rows; keep one"
            ));
        }
    }
    problems
}

/// Each external cargo dependency of the workspace in `meta` with the workspace crates that use
/// it, a crate that uses it only as a dev- or build-dependency marked `(dev)` or `(build)`.
fn used_by(meta: &Metadata) -> BTreeMap<String, BTreeSet<String>> {
    let packages = workspace_packages(meta);
    let internal: BTreeSet<&str> = packages.iter().map(|p| p.name.as_str()).collect();
    let mut kinds: BTreeMap<&str, BTreeMap<&str, Option<&str>>> = BTreeMap::new();
    for pkg in &packages {
        for dep in pkg
            .dependencies
            .iter()
            .filter(|d| !internal.contains(d.name.as_str()))
        {
            let kind = kinds
                .entry(dep.name.as_str())
                .or_default()
                .entry(pkg.name.as_str())
                .or_insert(dep.kind.as_deref());
            if dep.kind.is_none() {
                *kind = None;
            }
        }
    }
    kinds
        .into_iter()
        .map(|(dep, users)| {
            let users = users
                .into_iter()
                .map(|(user, kind)| match kind {
                    Some(kind) => format!("{user} ({kind})"),
                    None => user.to_owned(),
                })
                .collect();
            (dep.to_owned(), users)
        })
        .collect()
}

/// `cargo xtask deps --used-by`: the registry's "Used by" column for every cargo row, derived.
fn deps_used_by() -> Result<()> {
    for (dep, users) in used_by(&metadata()?) {
        println!(
            "{dep}: {}",
            users.into_iter().collect::<Vec<_>>().join(", ")
        );
    }
    Ok(())
}

/// The uv workspace root and every member listed in its `[tool.uv.workspace].members`.
fn python_manifests() -> Result<Vec<String>> {
    let root = "python/pyproject.toml";
    let doc: toml::Value =
        toml::from_str(&fs::read_to_string(root)?).with_context(|| format!("parsing {root}"))?;
    let members = doc
        .get("tool")
        .and_then(|t| t.get("uv"))
        .and_then(|u| u.get("workspace"))
        .and_then(|w| w.get("members"))
        .and_then(toml::Value::as_array)
        .context("python/pyproject.toml has no [tool.uv.workspace].members")?;
    let mut manifests = vec![root.to_owned()];
    for member in members {
        let dir = member
            .as_str()
            .context("a uv workspace member is not a string")?;
        manifests.push(format!("python/{dir}/pyproject.toml"));
    }
    Ok(manifests)
}

fn python_direct_dependencies() -> Result<BTreeSet<String>> {
    let mut found = BTreeSet::new();
    let mut workspace_members = BTreeSet::new();
    for manifest in python_manifests()? {
        let doc: toml::Value = toml::from_str(&fs::read_to_string(&manifest)?)
            .with_context(|| format!("parsing {manifest}"))?;
        if let Some(sources) = doc
            .get("tool")
            .and_then(|t| t.get("uv"))
            .and_then(|u| u.get("sources"))
            .and_then(toml::Value::as_table)
        {
            workspace_members.extend(
                sources
                    .iter()
                    .filter(|(_, source)| {
                        source.get("workspace").and_then(toml::Value::as_bool) == Some(true)
                    })
                    .map(|(name, _)| name.to_lowercase()),
            );
        }
        let mut lists = Vec::new();
        if let Some(deps) = doc
            .get("project")
            .and_then(|p| p.get("dependencies"))
            .and_then(toml::Value::as_array)
        {
            lists.push(deps.clone());
        }
        if let Some(groups) = doc.get("dependency-groups").and_then(toml::Value::as_table) {
            lists.extend(groups.values().filter_map(toml::Value::as_array).cloned());
        }
        for spec in lists.iter().flatten().filter_map(toml::Value::as_str) {
            let name: String = spec
                .chars()
                .take_while(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.'))
                .collect();
            if !name.is_empty() && !workspace_members.contains(&name.to_lowercase()) {
                found.insert(name.to_lowercase());
            }
        }
    }
    Ok(found)
}

fn deps() -> Result<()> {
    eprintln!("    deps: checking direct dependencies against docs/dependencies.md");
    let text =
        fs::read_to_string("docs/dependencies.md").context("reading docs/dependencies.md")?;
    let registered = registry(&text);
    let meta = metadata()?;
    let packages = workspace_packages(&meta);
    let internal: BTreeSet<&str> = packages.iter().map(|p| p.name.as_str()).collect();
    let mut problems = registry_problems(&text);
    for pkg in &packages {
        for dep in pkg
            .dependencies
            .iter()
            .filter(|d| !internal.contains(d.name.as_str()))
        {
            if !registered.contains(&("cargo".to_string(), dep.name.clone())) {
                problems.push(format!(
                    "cargo dependency `{}` (used by `{}`) has no entry in docs/dependencies.md",
                    dep.name, pkg.name
                ));
            }
        }
    }
    for name in python_direct_dependencies()? {
        if !registered.contains(&("python".to_string(), name.clone())) {
            problems.push(format!(
                "python dependency `{name}` has no entry in docs/dependencies.md"
            ));
        }
    }
    report(problems, "deps")
}

fn refcases(write: bool) -> Result<()> {
    if write {
        return uv_tools(&[
            "python",
            "-m",
            "mandate_tools.export_refcases",
            "--out",
            "../fixtures/refcases",
        ]);
    }
    let tmp = unique_temp_path("mandate-refcases", "");
    fs::create_dir_all(&tmp)?;
    let tmp_str = tmp.to_str().context("non-UTF-8 temp path")?;
    uv_tools(&[
        "python",
        "-m",
        "mandate_tools.export_refcases",
        "--out",
        tmp_str,
    ])?;
    let mut problems = Vec::new();
    let expected: BTreeSet<String> = fs::read_dir(&tmp)?
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .collect();
    let committed: BTreeSet<String> = fs::read_dir("fixtures/refcases")
        .map(|rd| {
            rd.filter_map(|e| e.ok())
                .map(|e| e.file_name().to_string_lossy().into_owned())
                .collect()
        })
        .unwrap_or_default();
    for name in expected.union(&committed) {
        let fresh = fs::read(tmp.join(name)).ok();
        let saved = fs::read(Path::new("fixtures/refcases").join(name)).ok();
        if fresh != saved {
            problems.push(format!(
                "fixtures/refcases/{name} is out of date; run `cargo xtask refcases --write`"
            ));
        }
    }
    fs::remove_dir_all(&tmp).ok();
    report(problems, "refcases")
}

/// Where proptest saves a failing case as a seed beside the test that produced it, in both
/// shapes it writes: `proptest-regressions/<file>.txt` at the crate root, its default, and
/// `<file>.proptest-regressions` next to the source. Git pathspecs, so `*` crosses directories.
const PROPTEST_SEED_PATHSPECS: [&str; 2] = ["*.proptest-regressions", "*proptest-regressions/*"];

/// Every proptest failure seed in the tree at `dir`, tracked or untracked, ignored or not.
/// Proptest replays a saved seed before it draws fresh cases, so a seed left by an earlier run, on
/// other code or under a planted bug, changes which cases every later run tries (DEC-164); a
/// committed one does that in every checkout (#449 review, M1).
fn proptest_seeds_in(dir: &Path) -> Result<Vec<String>> {
    let mut args = vec!["ls-files", "--cached", "--others", "--"];
    args.extend_from_slice(&PROPTEST_SEED_PATHSPECS);
    Ok(output_in(dir, "git", &args)?
        .lines()
        .map(str::to_owned)
        .collect())
}

/// `.gitignore` keeps a seed out of a commit made with `git add -A`; this check also fails on one
/// that was added by name or was left in the working tree (DEC-381).
fn proptest_seeds() -> Result<()> {
    eprintln!("    proptest-seeds: checking for saved proptest failure seeds");
    let problems = proptest_seeds_in(Path::new("."))?
        .into_iter()
        .map(|file| {
            format!(
                "{file}: a saved proptest failure seed; delete it, since proptest replays it \
                 before drawing fresh cases (DEC-164, DEC-381)"
            )
        })
        .collect();
    report(problems, "proptest-seeds")
}

/// Debt markers get copied as precedent, `#[ignore]` without a pending story hides a test forever,
/// and plain comments become the justification agents copy for workarounds (AGENTS.md, "The trust
/// ladder"; DEC-80).
fn markers() -> Result<()> {
    eprintln!(
        "    markers: checking for debt markers, unexplained #[ignore], and ungated pending tests"
    );
    let debt = [
        concat!("TO", "DO"),
        concat!("FIX", "ME"),
        concat!("X", "XX"),
        concat!("HA", "CK"),
    ];
    let files = output(
        "git",
        &[
            "ls-files",
            "--cached",
            "--others",
            "--exclude-standard",
            "--",
            "crates",
            "xtask/src",
        ],
    )?;
    let mut problems = Vec::new();
    for file in files.lines().filter(|f| f.ends_with(".rs")) {
        let Ok(text) = fs::read_to_string(file) else {
            continue;
        };
        for n in plain_comment_lines(&text) {
            problems.push(format!(
                "{file}:{n}: plain comment; put the reason in a name, a type, a test, an assertion \
                 message, or the item's doc comment (DEC-80)"
            ));
        }
        for (n, line) in (1..).zip(text.lines()) {
            for word in debt.iter().filter(|w| contains_word(line, w)) {
                problems.push(format!(
                    "{file}:{n}: `{word}` marker; fix it now or add a backlog item instead"
                ));
            }
            if line.trim_start().starts_with("#[ignore") && !is_pending_marker(line) {
                problems.push(format!(
                    "{file}:{n}: #[ignore] must be `#[ignore = \"pending E<n>-<n>\"]` (DEC-77)"
                ));
            }
        }
        for (n, why) in generated_pending_markers(&text) {
            problems.push(format!(
                "{file}:{n}: a pending marker {why}; the pending gate reads the source, so a \
                 pending test must be written out as a plain function or it is never gated \
                 (DEC-110, DEC-137)"
            ));
        }
    }
    report(problems, "markers")
}

/// Line numbers (1-based) where a plain `//` or `/* */` comment starts, skipping doc comments
/// (`///`, `//!`, `/** */`, `/*! */`) and anything inside string, raw-string, or char literals.
fn plain_comment_lines(src: &str) -> Vec<usize> {
    let chars: Vec<char> = src.chars().collect();
    let at = |i: usize| chars.get(i).copied();
    let is_ident = |c: Option<char>| c.is_some_and(|c| c.is_alphanumeric() || c == '_');
    let raw_prefix = |before: Option<char>, before_that: Option<char>| {
        !is_ident(before) || (before == Some('b') && !is_ident(before_that))
    };
    let mut found = Vec::new();
    let (mut i, mut line) = (0, 1);
    while let Some(c) = at(i) {
        match (c, at(i + 1)) {
            ('\n', _) => line += 1,
            ('/', Some('/')) => {
                let doc =
                    (at(i + 2) == Some('/') && at(i + 3) != Some('/')) || at(i + 2) == Some('!');
                if !doc {
                    found.push(line);
                }
                while at(i).is_some_and(|c| c != '\n') {
                    i += 1;
                }
                continue;
            }
            ('/', Some('*')) => {
                let doc =
                    (at(i + 2) == Some('*') && at(i + 3) != Some('/')) || at(i + 2) == Some('!');
                if !doc {
                    found.push(line);
                }
                let mut depth = 0usize;
                while let Some(c) = at(i) {
                    match (c, at(i + 1)) {
                        ('/', Some('*')) => {
                            depth += 1;
                            i += 1;
                        }
                        ('*', Some('/')) => {
                            depth -= 1;
                            i += 1;
                            if depth == 0 {
                                i += 1;
                                break;
                            }
                        }
                        ('\n', _) => line += 1,
                        _ => {}
                    }
                    i += 1;
                }
                continue;
            }
            ('r', _)
                if raw_prefix(i.checked_sub(1).and_then(at), i.checked_sub(2).and_then(at)) =>
            {
                let mut j = i + 1;
                while at(j) == Some('#') {
                    j += 1;
                }
                if at(j) == Some('"') {
                    let closing: Vec<char> = std::iter::once('"')
                        .chain(std::iter::repeat_n('#', j - i - 1))
                        .collect();
                    i = j + 1;
                    while i < chars.len() && !chars[i..].starts_with(&closing) {
                        if chars[i] == '\n' {
                            line += 1;
                        }
                        i += 1;
                    }
                    i += closing.len();
                    continue;
                }
            }
            ('"', _) => {
                i += 1;
                while let Some(c) = at(i) {
                    match c {
                        '\\' => i += 1,
                        '"' => break,
                        '\n' => line += 1,
                        _ => {}
                    }
                    i += 1;
                }
            }
            ('\'', Some('\\')) => {
                i += 2;
                while at(i).is_some_and(|c| c != '\'') {
                    i += 1;
                }
            }
            ('\'', Some(_)) if at(i + 2) == Some('\'') => i += 2,
            _ => {}
        }
        i += 1;
    }
    found
}

fn contains_word(line: &str, word: &str) -> bool {
    let is_word = |c: char| c.is_alphanumeric() || c == '_';
    line.match_indices(word).any(|(i, _)| {
        let before = line[..i].chars().next_back().is_none_or(|c| !is_word(c));
        let after = line[i + word.len()..]
            .chars()
            .next()
            .is_none_or(|c| !is_word(c));
        before && after
    })
}

fn is_pending_marker(line: &str) -> bool {
    line.trim()
        .strip_prefix("#[ignore = \"")
        .and_then(|rest| rest.strip_suffix("\"]"))
        .is_some_and(is_pending_reason)
}

/// `pending E<n>-<n>`, the only reason an `#[ignore]` may give (DEC-77).
fn is_pending_reason(reason: &str) -> bool {
    let Some(story) = reason.strip_prefix("pending E") else {
        return false;
    };
    matches!(story.split_once('-'), Some((epic, n))
        if !epic.is_empty() && !n.is_empty()
            && epic.chars().chain(n.chars()).all(|c| c.is_ascii_digit()))
}

/// The feature map names every crate and reference-case suite, and every path it names exists.
fn feature_map() -> Result<()> {
    eprintln!("    feature-map: checking {FEATURE_MAP} against the workspace");
    report(
        feature_map_problems(Path::new("."), &metadata()?)?,
        "feature-map",
    )
}

/// Every feature file of the map under `root`, sorted by name, with its text: every `.md` file in
/// [`FEATURE_MAP`] but its README.
fn feature_files(root: &Path) -> Result<Vec<(String, String)>> {
    let mut files = Vec::new();
    for entry in
        fs::read_dir(root.join(FEATURE_MAP)).with_context(|| format!("reading {FEATURE_MAP}"))?
    {
        let path = entry?.path();
        let name = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or_default()
            .to_owned();
        if name.ends_with(".md") && name != "README.md" {
            let text = fs::read_to_string(&path)
                .with_context(|| format!("reading {FEATURE_MAP}/{name}"))?;
            files.push((name, text));
        }
    }
    files.sort();
    Ok(files)
}

/// The map's drift against the workspace under `root`, the checks the single `feature-map.md` had:
/// every workspace crate is named in some feature as `` `crate` ``, every reference-case fixture
/// as its path, and every repository path a feature names exists. Each feature file must also open
/// with its `# ` title, which is what `--index` lists.
fn feature_map_problems(root: &Path, meta: &Metadata) -> Result<Vec<String>> {
    let files = feature_files(root)?;
    let mut problems = Vec::new();
    if files.is_empty() {
        problems.push(format!("{FEATURE_MAP} has no feature files"));
    }
    let text: String = files
        .iter()
        .map(|(_, text)| text.as_str())
        .collect::<Vec<_>>()
        .join("\n");
    for pkg in workspace_packages(meta) {
        if !text.contains(&format!("`{}`", pkg.name)) {
            problems.push(format!("crate `{}` has no entry", pkg.name));
        }
    }
    for entry in fs::read_dir(root.join("fixtures/refcases"))? {
        let name = entry?.file_name().to_string_lossy().into_owned();
        if !text.contains(&format!("fixtures/refcases/{name}")) {
            problems.push(format!("fixtures/refcases/{name} has no entry"));
        }
    }
    for (name, text) in &files {
        if feature_title(text).is_none() {
            problems.push(format!(
                "{FEATURE_MAP}/{name} does not open with a `# ` title"
            ));
        }
        for path in backticked_paths(text) {
            if !root.join(path).exists() {
                problems.push(format!("{name} names `{path}`, which does not exist"));
            }
        }
    }
    Ok(problems)
}

/// A feature file's title: its first line, when that is a `# ` heading.
fn feature_title(text: &str) -> Option<&str> {
    text.lines().next()?.strip_prefix("# ")
}

/// `cargo xtask feature-map --index`: the map's table of contents, derived from the files, so no
/// hand-kept list can drift or become a file every feature PR edits.
fn feature_map_index() -> Result<()> {
    for (name, text) in feature_files(Path::new("."))? {
        println!("{name}: {}", feature_title(&text).unwrap_or("(no title)"));
    }
    Ok(())
}

/// The text a [`CiFile`] holds when its file cannot be read as UTF-8 (a dangling symlink, a
/// non-UTF-8 build file), which [`live_feature_problems`] refuses rather than aborting on it.
const UNREADABLE: &str = "\0";

/// One of the [`ci_files`], by its path in the repository, with its text.
struct CiFile {
    path: String,
    text: String,
}

/// Every file that decides what CI or a release builds, each of which may be absent: workflows,
/// scripts and actions under `.github`, `deploy`'s scripts, `.cargo/config.toml`, the
/// [`build_files`] anywhere in the repository, and `web/package.json`, whose scripts `npm run`
/// runs (B7).
fn ci_files(root: &Path) -> Result<Vec<CiFile>> {
    let mut files = build_files(root)?;
    for (dir, extensions) in [
        (".github/workflows", &["yml", "yaml"][..]),
        (".github/scripts", &["sh"][..]),
        (".github/actions", &["yml", "yaml"][..]),
        ("deploy", &["sh"][..]),
    ] {
        let dir = root.join(dir);
        if dir.is_dir() {
            files.extend(files_by_extension(&dir, extensions)?);
        }
    }
    for single in [".cargo/config.toml", ".cargo/config", "web/package.json"] {
        let single = root.join(single);
        if single.is_file() {
            files.push(single);
        }
    }
    files.sort();
    files.dedup();
    files
        .into_iter()
        .map(|file| {
            let text = fs::read_to_string(&file).unwrap_or_else(|_| UNREADABLE.to_owned());
            let path = file
                .strip_prefix(root)
                .unwrap_or(&file)
                .display()
                .to_string();
            Ok(CiFile { path, text })
        })
        .collect()
}

/// The build files under `root` (DEC-851, the eleventh-round ruling): `Makefile`, `makefile`,
/// `GNUmakefile`, `*.mk`, `justfile`, `Justfile`, `Dockerfile*` and `docker-compose*.yml` or
/// `.yaml`, at any depth. Only what is not the repository's own is skipped: `.git`,
/// `node_modules`, and a directory a `CACHEDIR.TAG` marks as a cache, as cargo's target is.
fn build_files(root: &Path) -> Result<Vec<PathBuf>> {
    let mut files = Vec::new();
    let mut pending = vec![root.to_path_buf()];
    while let Some(dir) = pending.pop() {
        for entry in fs::read_dir(&dir).with_context(|| format!("reading {}", dir.display()))? {
            let entry = entry?;
            let (path, name) = (entry.path(), entry.file_name());
            let name = name.to_string_lossy();
            if entry.file_type()?.is_dir() {
                if !matches!(name.as_ref(), ".git" | "node_modules")
                    && !path.join("CACHEDIR.TAG").is_file()
                {
                    pending.push(path);
                }
            } else if matches!(
                name.as_ref(),
                "Makefile" | "makefile" | "GNUmakefile" | "justfile" | "Justfile"
            ) || name.ends_with(".mk")
                || (matches!(name.as_ref(), "config" | "config.toml")
                    && dir.file_name().is_some_and(|parent| parent == ".cargo"))
                || name.starts_with("Dockerfile")
                || (name.starts_with("docker-compose")
                    && (name.ends_with(".yml") || name.ends_with(".yaml")))
            {
                files.push(path);
            }
        }
    }
    Ok(files)
}

/// [`live_feature_problems`] and [`resolved_live_problems`] over the repository at `root`, as
/// `cargo xtask live-feature` and the lint job run it.
fn live_feature_in(root: &Path) -> Result<()> {
    eprintln!("    live-feature: checking that only the runner may build `live` (ES-23, DEC-529)");
    let policy: Layers = toml::from_str(&fs::read_to_string(root.join("xtask/layers.toml"))?)
        .context("parsing xtask/layers.toml")?;
    let files = ci_files(root)?;
    let meta = metadata_in(root)?;
    let mut problems = live_feature_problems(&policy, &meta, &files)?;
    problems.extend(resolved_live_problems(&policy, &meta, &files, &|words| {
        cargo_resolve(root, words)
    })?);
    report(problems, "live-feature")
}

/// Every way the workspace and its CI break ES-23's ban on a `live` build, as DEC-529 item 3
/// narrows it for the founder's one live order (E7-26, X1): at most one crate is marked
/// `live_feature` in `policy`, and only it may declare a `live` feature; no other feature of it
/// (`default` included) and no dependency or feature of another crate turns `live` on; and CI
/// never passes `--all-features`, and passes `live` only in at most one `cargo check` of the
/// marked crate, so the feature compiles but no live build is ever produced or run, and in at most
/// one workflow line that tests the marked crate in the `live,rh-sim` build (DEC-964), whose
/// binaries hold no Robinhood host and dial loopback alone (DEC-922).
fn live_feature_problems(policy: &Layers, meta: &Metadata, ci: &[CiFile]) -> Result<Vec<String>> {
    let mut problems = Vec::new();
    let packages = workspace_packages(meta);
    let names: BTreeSet<&str> = packages.iter().map(|p| p.name.as_str()).collect();
    let marked: Vec<&str> = policy
        .crates
        .iter()
        .filter(|(_, crate_policy)| crate_policy.live_feature)
        .map(|(name, _)| name.as_str())
        .collect();
    if marked.len() > 1 {
        let listed: Vec<String> = marked.iter().map(|name| format!("`{name}`")).collect();
        problems.push(format!(
            "{} are marked `live_feature`; at most one crate, the runner, may be",
            listed.join(", ")
        ));
    }
    for name in &marked {
        if !names.contains(name) {
            problems.push(format!(
                "`{name}` is marked `live_feature` but is not a workspace member"
            ));
        }
    }
    let runner = match marked.as_slice() {
        [only] if names.contains(only) => Some(*only),
        _ => None,
    };
    for pkg in &packages {
        let is_runner = runner == Some(pkg.name.as_str());
        if pkg.features.contains_key(LIVE) && !is_runner {
            problems.push(format!(
                "`{}` declares a `{LIVE}` feature; only the crate marked `live_feature` may",
                pkg.name
            ));
        }
        for (feature, enables) in &pkg.features {
            for enabled in enables {
                let turns_on_own = is_runner && feature != LIVE && enabled == LIVE;
                let turns_on_other = enabled
                    .rsplit_once('/')
                    .is_some_and(|(_, feature)| feature == LIVE);
                if turns_on_own || turns_on_other {
                    problems.push(format!(
                        "`{}`'s feature `{feature}` turns on `{enabled}`; only an explicit \
                         `--features {LIVE}` may",
                        pkg.name
                    ));
                }
            }
        }
        for dep in &pkg.dependencies {
            if dep.features.iter().any(|f| f == LIVE) {
                problems.push(format!(
                    "`{}` turns on `{LIVE}` in its dependency on `{}`",
                    pkg.name, dep.name
                ));
            }
            if dep.features.iter().any(|f| f == REHEARSAL) {
                problems.push(format!(
                    "`{}` turns on `{REHEARSAL}` in its dependency on `{}`; only `cargo xtask ci \
                     test-rh-sim`'s explicit flag may (DEC-922)",
                    pkg.name, dep.name
                ));
            }
        }
        for (feature, enables) in &pkg.features {
            let rehearsal = enables.iter().find(|enabled| {
                *enabled == REHEARSAL
                    || enabled
                        .rsplit_once('/')
                        .is_some_and(|(_, feature)| feature == REHEARSAL)
            });
            if let Some(enabled) = rehearsal {
                problems.push(format!(
                    "`{}`'s feature `{feature}` turns on `{enabled}`; only `cargo xtask ci \
                     test-rh-sim`'s explicit flag may (DEC-922)",
                    pkg.name
                ));
            }
        }
    }
    let (mut compile_only_seen, mut rehearsal_seen) = (false, false);
    for file in ci {
        if file.text.contains('\0') {
            problems.push(format!(
                "{}: cannot be read as text, so the check cannot judge it",
                file.path
            ));
            continue;
        }
        let yaml = file.path.ends_with(".yml") || file.path.ends_with(".yaml");
        let (run_lines, with_lines) = (
            block_lines(&file.text, "run"),
            block_lines(&file.text, "with"),
        );
        let lines = logical_lines(&file.path, &file.text);
        let text_lines = text_only_lines(&lines, yaml);
        let Definitions {
            variables,
            arrays,
            runs_positional,
        } = definitions(&lines);
        for ((number, line), text_only) in lines.iter().zip(text_lines) {
            let at = format!("{}:{number}", file.path);
            let ctx = LineContext {
                runner,
                cargo_config: file.path.ends_with(".cargo/config.toml"),
                expression_command: !yaml || run_lines.contains(number),
                with_value: yaml && with_lines.contains(number),
                variables: &variables,
                arrays: &arrays,
                runs_positional,
                path: &file.path,
                exact_line: PARSER_LIMITED_LINES.contains(&(file.path.as_str(), line.trim())),
                quoted_reread: false,
            };
            let flag = if text_only {
                text_line_live_flag(line, ctx)
            } else {
                live_flag(line, ctx, false)
            };
            match flag {
                LiveFlag::Absent => {}
                LiveFlag::AllFeatures => problems.push(format!(
                    "{at}: `--all-features` would build the `{LIVE}` feature"
                )),
                LiveFlag::Cfg => problems.push(format!(
                    "{at}: sets a feature through `--cfg feature=…`, which bypasses `--features`"
                )),
                LiveFlag::Unreadable => problems.push(format!(
                    "{at}: cargo words the shell expands or `xargs` gives cannot be checked"
                )),
                LiveFlag::CompileOnly if !compile_only_seen => compile_only_seen = true,
                LiveFlag::CompileOnly => problems.push(format!(
                    "{at}: a second compile-only `{LIVE}` job; CI may compile it once"
                )),
                LiveFlag::RehearsalTest if !rehearsal_seen => rehearsal_seen = true,
                LiveFlag::RehearsalTest => problems.push(format!(
                    "{at}: a second run of the rehearsal's tests with `{LIVE}`; CI may run them \
                     once (DEC-964)"
                )),
                LiveFlag::Build => problems.push(format!(
                    "{at}: passes `{LIVE}` outside the one `cargo check -p <runner>` CI may run"
                )),
            }
        }
    }
    Ok(problems)
}

/// `cargo metadata`'s `resolve`: the packages one build resolves (E7-28).
#[derive(Deserialize)]
struct Resolve {
    nodes: Vec<ResolvedNode>,
}

/// A [`Resolve`]'s package by id, its features turned on, and the ids it depends on, of any kind.
#[derive(Deserialize)]
struct ResolvedNode {
    id: String,
    #[serde(default)]
    features: Vec<String>,
    #[serde(default)]
    dependencies: Vec<String>,
}

/// `cargo metadata`'s output with its resolve, which `--no-deps` leaves out.
#[derive(Deserialize)]
struct ResolvedMetadata {
    resolve: Option<Resolve>,
}

/// Every CI build that resolves `live`, from what cargo resolves: DEC-851 item 6's artifact-level
/// check (E7-28, DEC-868). `resolve_for` resolves an invocation's words, `[]` the default build.
/// Neither it nor any cargo invocation of a `.github/workflows/` job's `run:` (up to a shell
/// operator) may turn `live` on, hold a live-only package (`dep:<name>` in the runner's `live`) or
/// pass `--all-features`, but one `cargo check -p <runner>` with only `live` may turn it on in the
/// runner, and so may one `cargo nextest run -p <runner>` with exactly `live` and `rh-sim`, in the
/// job [`REHEARSAL_LIVE_JOB`] of [`REHEARSAL_LIVE_WORKFLOW`] alone and only as
/// [`rehearsal_job_problems`] allows it (DEC-964); that run may hold no live-only package.
/// Problems name the file and job, the package with each package turning `live` on or depending
/// on it; a failed resolve or an expanding word is a problem, not an abort.
fn resolved_live_problems(
    policy: &Layers,
    meta: &Metadata,
    workflows: &[CiFile],
    resolve_for: &dyn Fn(&[String]) -> Result<Resolve>,
) -> Result<Vec<String>> {
    let runner = live_runner(policy, meta);
    let live_only: BTreeSet<&str> = meta
        .packages
        .iter()
        .filter(|pkg| runner == Some(pkg.name.as_str()))
        .filter_map(|pkg| pkg.features.get(LIVE))
        .flatten()
        .filter_map(|enabled| enabled.strip_prefix("dep:"))
        .collect();
    let mut builds = vec![("the default build".to_owned(), Vec::new(), true, false)];
    let mut problems = Vec::new();
    let mut aliases = Aliases::new();
    let scripts: BTreeMap<String, Option<String>> = READ_SCRIPTS
        .iter()
        .map(|script| {
            let why = script_unread(script, workflows, &mut BTreeSet::new());
            ((*script).to_owned(), why)
        })
        .collect();
    for file in workflows {
        let Some(root) = cargo_config(&file.path) else {
            continue;
        };
        let unread = |why: String| {
            format!(
                "{}: {why}, so its aliases cannot be read and the check cannot judge the builds \
                 they name (DEC-868 item 3)",
                file.path
            )
        };
        let (read, why) = cargo_aliases(&file.text);
        problems.extend(why.into_iter().map(unread));
        if !root && !read.is_empty() {
            problems.push(unread(
                "has an `[alias]` below the repository root, which a directory change picks up"
                    .to_owned(),
            ));
            continue;
        }
        for (name, words) in read {
            if aliases.insert(name.clone(), words).is_some() {
                problems.push(unread(format!("defines the alias `{name}` twice")));
            }
        }
    }
    for file in workflows
        .iter()
        .filter(|file| file.path.starts_with(".github/workflows/"))
    {
        let (invocations, unread) = read_workflow(file, workflows, &scripts);
        let mut guard_read = false;
        for (number, job, why) in unread {
            problems.push(format!(
                "{}:{number}: {job}: {why}, so the line cannot be read and the check cannot judge \
                 it (DEC-868 item 3)",
                file.path
            ));
        }
        for invocation in invocations {
            let at = format!(
                "{}: job `{}`, `cargo {}`",
                file.path,
                invocation.job,
                invocation.words.join(" ")
            );
            let rehearsal_form =
                runner.is_some_and(|runner| is_rehearsal_test(&invocation.words, runner));
            let in_job =
                file.path == REHEARSAL_LIVE_WORKFLOW && invocation.job == REHEARSAL_LIVE_JOB;
            if rehearsal_form && !in_job {
                problems.push(format!(
                    "{at}: runs the rehearsal's tests with `{LIVE}` outside the job \
                     `{REHEARSAL_LIVE_JOB}` of {REHEARSAL_LIVE_WORKFLOW} (DEC-964)"
                ));
            }
            if let Some(runner) = runner.filter(|_| rehearsal_form && in_job && !guard_read) {
                problems.extend(rehearsal_job_problems(file, runner));
                guard_read = true;
            }
            match expand_alias(&invocation.words, &aliases) {
                Ok(None) => {}
                Ok(Some(expanded)) => {
                    builds.push((format!("{at}, its alias expanded"), expanded, false, false));
                }
                Err(()) => problems.push(format!(
                    "{at}: an alias chain that does not end cannot be read, so the check cannot \
                     judge it (DEC-868 item 3)"
                )),
            }
            builds.push((at, invocation.words, false, rehearsal_form && in_job));
        }
    }
    let (mut compile_only_seen, mut rehearsal_seen) = (false, false);
    for (at, words, default_build, rehearsal_job) in builds {
        if words.iter().any(|word| word.contains(['$', '`'])) {
            problems.push(format!("{at}: words the shell expands cannot be resolved"));
            continue;
        }
        if words.iter().any(|word| word == "--all-features") {
            problems.push(format!(
                "{at}: `--all-features` would resolve the `{LIVE}` feature"
            ));
        }
        let resolve = match resolve_for(&words) {
            Ok(resolve) => resolve,
            Err(err) => {
                problems.push(format!(
                    "{at}: cannot be resolved, so the check cannot judge it: {err:#}"
                ));
                continue;
            }
        };
        let compile_only_form = runner.is_some_and(|runner| is_compile_only(&words, runner));
        let compile_only = compile_only_form && !compile_only_seen;
        if compile_only_form && compile_only_seen {
            problems.push(format!(
                "{at}: a second compile-only `{LIVE}` job; CI may compile it once"
            ));
        }
        compile_only_seen |= compile_only;
        let rehearsal = rehearsal_job && !rehearsal_seen;
        if rehearsal_job && rehearsal_seen {
            problems.push(format!(
                "{at}: a second run of the rehearsal's tests with `{LIVE}`; CI may run them once \
                 (DEC-964)"
            ));
        }
        rehearsal_seen |= rehearsal;
        let reached = reached_ids(
            &resolve,
            &selected_ids(meta, &resolve, &words, default_build),
        );
        for node in &resolve.nodes {
            let name = node_name(meta, &node.id);
            let runner_allowed = (compile_only || rehearsal) && runner == Some(name);
            if node.features.iter().any(|feature| feature == LIVE) && !runner_allowed {
                let by = turned_on_by(meta, &resolve, name);
                problems.push(format!(
                    "{at}: resolves `{LIVE}` in `{name}`{}",
                    listed(", turned on by", &by)
                ));
            }
            if live_only.contains(name) && !compile_only && reached.contains(node.id.as_str()) {
                let by: BTreeSet<&str> = resolve
                    .nodes
                    .iter()
                    .filter(|other| reached.contains(other.id.as_str()))
                    .filter(|other| other.dependencies.contains(&node.id))
                    .map(|other| node_name(meta, &other.id))
                    .collect();
                problems.push(format!(
                    "{at}: holds the live-only `{name}`{}",
                    listed(", depended on by", &by)
                ));
            }
        }
    }
    Ok(problems)
}

/// Every way the rehearsal job of `file` could hand a broker or data credential to the runner's
/// tests in the `live,rh-sim` build (DEC-964): a line of the job, or of the workflow's top-level
/// `env:`, that names `secrets` or the workflow's token (`github.token`), an `env:` name there that
/// holds one of [`CREDENTIAL_NAME_PARTS`] in any case, and a job that does not run the tests as
/// [`rehearsal_live_run`] spells it, with the [`CREDENTIAL_GUARD`] first in the same shell.
fn rehearsal_job_problems(file: &CiFile, runner: &str) -> Vec<String> {
    let sections = workflow_sections(&file.text);
    let env_lines = block_lines(&file.text, "env");
    let run = rehearsal_live_run(runner);
    let mut problems = Vec::new();
    let mut guarded = false;
    for (number, line) in (1_usize..).zip(file.text.lines()) {
        let Some((top, job)) = sections.get(&number) else {
            continue;
        };
        let in_job = top == "jobs" && job.as_deref() == Some(REHEARSAL_LIVE_JOB);
        if !in_job && top != "env" {
            continue;
        }
        let code = uncommented(line);
        let at = format!("{}:{number}: job `{REHEARSAL_LIVE_JOB}`", file.path);
        let lower = code.to_ascii_lowercase();
        let name = code
            .trim_start_matches([' ', '-'])
            .split_once(':')
            .map(|(name, _)| name.trim().to_ascii_uppercase())
            .filter(|_| env_lines.contains(&number));
        if lower.contains("secrets") || lower.contains("github.token") {
            problems.push(format!(
                "{at}: names a secret or the workflow's token, which no step of the job may hold \
                 (DEC-964)"
            ));
        } else if let Some(name) =
            name.filter(|name| CREDENTIAL_NAME_PARTS.iter().any(|part| name.contains(part)))
        {
            problems.push(format!(
                "{at}: sets `{name}`, a name that could carry a broker or data credential \
                 (DEC-964)"
            ));
        }
        guarded |= in_job
            && code
                .trim()
                .trim_start_matches("- ")
                .strip_prefix("run: ")
                .is_some_and(|step| step.trim() == run);
    }
    if !guarded {
        problems.push(format!(
            "{}: job `{REHEARSAL_LIVE_JOB}` runs the rehearsal's tests with `{LIVE}` but not as \
             `{run}`, so the credential guard `{CREDENTIAL_GUARD}` does not run first (DEC-964)",
            file.path
        ));
    }
    problems
}

/// The ids of `resolve` an invocation's `words` select, which a build starts from: each package
/// `-p`/`--package` names, every member less each `--exclude` under `--workspace` or `--all`, and
/// otherwise every member. Only the check's own `default_build`, run at the root, selects `meta`'s
/// default members (DEC-868 item 2): a workflow's cargo may run in any directory (a `cd`, a
/// `working-directory`, an alias), and cargo then builds the package there, so no directory change
/// can narrow a selection (#1169 round 2 review, major; DEC-176 tightening). A selection the check
/// cannot match to a node (a pattern or an unknown name) and `--manifest-path` select every member
/// too, so each can only refuse more; `cargo install --path` names no package, so it does.
fn selected_ids<'a>(
    meta: &'a Metadata,
    resolve: &'a Resolve,
    words: &[String],
    default_build: bool,
) -> BTreeSet<&'a str> {
    let (mut named, mut excluded, mut whole) = (Vec::new(), Vec::new(), false);
    let members = || meta.workspace_members.iter().map(String::as_str).collect();
    let elsewhere =
        |word: &String| word == "--manifest-path" || word.starts_with("--manifest-path=");
    if words.iter().take_while(|word| *word != "--").any(elsewhere) {
        return members();
    }
    let mut rest = words.iter().map(String::as_str);
    while let Some(word) = rest.next() {
        match word {
            "--" => break,
            "--workspace" | "--all" => whole = true,
            "-p" | "--package" => named.extend(rest.next()),
            "--exclude" => excluded.extend(rest.next()),
            _ => {
                if let Some(package) = word.strip_prefix("--package=") {
                    named.push(package);
                } else if let Some(package) = word.strip_prefix("--exclude=") {
                    excluded.push(package);
                } else {
                    match short_cluster(word) {
                        Some(ShortCluster::Package(Some(package))) => named.push(package),
                        Some(ShortCluster::Package(None)) => named.extend(rest.next()),
                        Some(ShortCluster::Unread) => return members(),
                        Some(ShortCluster::Plain) | None => {}
                    }
                }
            }
        }
    }
    if whole {
        let mut all: BTreeSet<&str> = members();
        all.retain(|id| !excluded.contains(&node_name(meta, id)));
        return all;
    }
    if named.is_empty() && default_build {
        return meta
            .workspace_default_members
            .iter()
            .map(String::as_str)
            .collect();
    }
    if named.is_empty() {
        return members();
    }
    let mut ids = BTreeSet::new();
    for spec in named {
        let name = spec.split(['@', ':']).next().unwrap_or(spec);
        let matching: Vec<&str> = resolve
            .nodes
            .iter()
            .map(|node| node.id.as_str())
            .filter(|id| node_name(meta, id) == name)
            .collect();
        if matching.is_empty() {
            return members();
        }
        ids.extend(matching);
    }
    ids
}

/// The ids of `resolve` that `roots` reach through its dependency edges, `roots` included.
fn reached_ids<'a>(resolve: &'a Resolve, roots: &BTreeSet<&'a str>) -> BTreeSet<&'a str> {
    let mut reached = roots.clone();
    let mut pending: Vec<&str> = roots.iter().copied().collect();
    while let Some(id) = pending.pop() {
        let Some(node) = resolve.nodes.iter().find(|node| node.id == id) else {
            continue;
        };
        for dep in &node.dependencies {
            if reached.insert(dep.as_str()) {
                pending.push(dep);
            }
        }
    }
    reached
}

/// The workspace member marked `live_feature` in `policy`, when exactly one is.
fn live_runner<'a>(policy: &'a Layers, meta: &Metadata) -> Option<&'a str> {
    let mut marked = policy
        .crates
        .iter()
        .filter(|(_, crate_policy)| crate_policy.live_feature)
        .map(|(name, _)| name.as_str());
    let only = marked.next().filter(|_| marked.next().is_none())?;
    workspace_packages(meta)
        .iter()
        .any(|pkg| pkg.name == only)
        .then_some(only)
}

/// The name of the package whose id is `id`: the workspace's, or else the one the id spells
/// (`registry+…#name@1.0.0`, `path+file:///…/name#1.0.0`, or `name 1.0.0 (…)`).
fn node_name<'a>(meta: &'a Metadata, id: &'a str) -> &'a str {
    if let Some(pkg) = meta.packages.iter().find(|pkg| pkg.id == id) {
        return &pkg.name;
    }
    match id.split_once('#') {
        Some((_, fragment)) if fragment.contains('@') => {
            fragment.split('@').next().unwrap_or(fragment)
        }
        Some((url, _)) => url.rsplit('/').next().unwrap_or(url),
        None => id.split(' ').next().unwrap_or(id),
    }
}

/// The packages of `resolve` that turn `live` on in `target`: through a dependency on it listing
/// `live`, or a feature the build turns on in them that names `<target>/live` or `<target>?/live`.
fn turned_on_by<'a>(meta: &'a Metadata, resolve: &'a Resolve, target: &str) -> BTreeSet<&'a str> {
    let names_live = |enabled: &String| {
        enabled
            .split_once('/')
            .is_some_and(|(dep, feature)| dep.trim_end_matches('?') == target && feature == LIVE)
    };
    resolve
        .nodes
        .iter()
        .filter_map(|node| {
            let name = node_name(meta, &node.id);
            let pkg = meta.packages.iter().find(|pkg| pkg.name == name)?;
            let by_dependency = pkg
                .dependencies
                .iter()
                .any(|dep| dep.name == target && dep.features.iter().any(|f| f == LIVE));
            let by_feature = node
                .features
                .iter()
                .filter_map(|feature| pkg.features.get(feature))
                .flatten()
                .any(names_live);
            (name != target && (by_dependency || by_feature)).then_some(name)
        })
        .collect()
}

/// `label` and each of `names` in backticks, or nothing when there are none.
fn listed(label: &str, names: &BTreeSet<&str>) -> String {
    if names.is_empty() {
        return String::new();
    }
    let quoted: Vec<String> = names.iter().map(|name| format!("`{name}`")).collect();
    format!("{label} {}", quoted.join(", "))
}

/// A cargo invocation's selected packages and the items of the feature lists it passes, each
/// item with a `<runner>/` prefix taken off, or `None` when it selects otherwise than by `-p`
/// alone: a whole-workspace selection, `--exclude`, `--all-features`, `--manifest-path`, or a
/// `-p` glued or in a short-flag cluster.
fn runner_selection<'a>(words: &'a [String], runner: &str) -> Option<(Vec<&'a str>, Vec<&'a str>)> {
    let mut packages = Vec::new();
    let mut features = Vec::new();
    let mut rest = words.iter().map(String::as_str);
    while let Some(word) = rest.next() {
        match word {
            "--workspace" | "--all" | "--exclude" | "--all-features" | "--manifest-path" => {
                return None;
            }
            "-p" | "--package" => packages.extend(rest.next()),
            "--features" | "-F" => features.extend(rest.next()),
            _ => {
                if let Some(package) = word.strip_prefix("--package=") {
                    packages.push(package);
                } else if let Some(list) = word
                    .strip_prefix("--features=")
                    .or_else(|| cluster_rest(word))
                {
                    features.push(list);
                } else if word.starts_with("-p")
                    || word.starts_with("--manifest-path=")
                    || matches!(
                        short_cluster(word),
                        Some(ShortCluster::Package(_) | ShortCluster::Unread)
                    )
                {
                    return None;
                }
            }
        }
    }
    let prefix = format!("{runner}/");
    let items = features
        .iter()
        .flat_map(|list| list.split([',', ' ']))
        .filter(|item| !item.is_empty())
        .map(|item| item.strip_prefix(prefix.as_str()).unwrap_or(item))
        .collect();
    Some((packages, items))
}

/// Whether a cargo invocation's `words` are the one compile-only form (DEC-529 item 3): `check`,
/// one package selected and it the `runner`, no whole-workspace selection, and `live` (or
/// `<runner>/live`) the only feature it passes.
fn is_compile_only(words: &[String], runner: &str) -> bool {
    let Some((packages, items)) = runner_selection(words, runner) else {
        return false;
    };
    words
        .first()
        .is_some_and(|subcommand| subcommand == "check")
        && packages == [runner]
        && !items.is_empty()
        && items.iter().all(|item| *item == LIVE)
}

/// Whether a cargo invocation's `words` are the one form that tests the runner with `live`
/// (DEC-964): `nextest run`, one package selected and it the `runner`, no whole-workspace
/// selection, and the features it passes exactly `live` and `rh-sim` (each bare or as
/// `<runner>/<feature>`), so the build is the rehearsal's, which dials loopback alone (DEC-922).
fn is_rehearsal_test(words: &[String], runner: &str) -> bool {
    let Some((packages, items)) = runner_selection(words, runner) else {
        return false;
    };
    let items: BTreeSet<&str> = items.into_iter().collect();
    words.get(..2).is_some_and(|sub| sub == ["nextest", "run"])
        && packages == [runner]
        && items == BTreeSet::from([LIVE, REHEARSAL])
}

/// Each line of a workflow by number, with the top-level key it sits under and, under the
/// top-level `jobs:`, the job key one level inside it.
fn workflow_sections(text: &str) -> BTreeMap<usize, (String, Option<String>)> {
    let mut sections = BTreeMap::new();
    let (mut top, mut job, mut column) = (String::new(), None::<String>, None);
    for (number, line) in (1_usize..).zip(text.lines()) {
        let trimmed = line.trim_start();
        let indent = line.len().saturating_sub(trimmed.len());
        let content = !trimmed.is_empty() && !trimmed.starts_with('#');
        if content && indent == 0 {
            top = trimmed
                .split(':')
                .next()
                .unwrap_or(trimmed)
                .trim()
                .to_owned();
            (job, column) = (None, None);
        } else if content && top == "jobs" {
            let at = *column.get_or_insert(indent);
            if indent == at
                && let Some((key, _)) = trimmed.split_once(':')
            {
                job = Some(key.trim().to_owned());
            }
        }
        sections.insert(number, (top.clone(), job.clone()));
    }
    sections
}

/// One cargo invocation of a workflow's `run:` steps.
struct CargoInvocation {
    /// The job it runs in.
    job: String,
    /// Its words after `cargo`.
    words: Vec<String>,
}

/// A line of a workflow the check cannot read: its number, the job it sits in (in backticks, or
/// the line), and why.
type UnreadLine = (usize, String, &'static str);

/// `line` up to a comment: a `#` that starts a word outside quotes, as YAML and the shell read it.
fn uncommented(line: &str) -> &str {
    let (mut quote, mut escaped, mut word_start) = (None, false, true);
    for (at, c) in line.char_indices() {
        match (quote, c) {
            _ if escaped => escaped = false,
            (q, '\\') if q != Some('\'') => escaped = true,
            (None, '#') if word_start => return line.get(..at).unwrap_or(line),
            (None, '"' | '\'') => quote = Some(c),
            (Some(open), _) if c == open => quote = None,
            _ => {}
        }
        word_start = quote.is_none() && c.is_whitespace();
    }
    line
}

/// The pieces of `text`, split on anything but letters, digits, `_`, `.`, `/` and `-`.
fn word_pieces(text: &str) -> impl Iterator<Item = &str> {
    text.split(|c: char| !(c.is_ascii_alphanumeric() || matches!(c, '_' | '.' | '/' | '-')))
}

/// How many [`word_pieces`] of `line`, outside its comment, are `cargo` or `cargo.exe`, by
/// themselves or at the end of a path.
fn cargo_words(line: &str) -> usize {
    word_pieces(uncommented(line))
        .filter(|piece| matches!(basename(piece), "cargo" | "cargo.exe"))
        .count()
}

/// The last `/`-separated part of `word`.
fn basename(word: &str) -> &str {
    word.rsplit('/').next().unwrap_or(word)
}

/// Whether `word` runs cargo: `cargo` or `cargo.exe`, or a `cargo-<subcommand>` binary such as
/// `cargo-nextest`, by itself or at the end of a path (#1169 round 3 review, bypass 4).
fn names_cargo(word: &str) -> bool {
    let base = basename(word);
    matches!(base, "cargo" | "cargo.exe")
        || base
            .strip_prefix("cargo-")
            .is_some_and(|sub| !sub.is_empty() && !sub.contains('.'))
}

/// What a short-flag cluster word passes for `-p`, as cargo reads it: after a `p`, the rest of
/// the cluster or else the next word is the package (`-qp rh-host`, `-vprh-host`); `F`, `j`, `Z`
/// and `C` take the rest as their own value; `v`, `q`, `r`, `h` and `V` take none. A cluster with
/// any other letter cannot be read (#1169 round 3 review, bypass 3).
enum ShortCluster<'w> {
    /// No `-p` in the cluster.
    Plain,
    /// A `-p`, with its glued value or `None` for the next word.
    Package(Option<&'w str>),
    /// A letter the check does not know.
    Unread,
}

/// `word` read as a [`ShortCluster`], when it is one: a single `-` and at least one letter.
fn short_cluster(word: &str) -> Option<ShortCluster<'_>> {
    let rest = word
        .strip_prefix('-')
        .filter(|rest| !rest.is_empty() && !rest.starts_with('-'))?;
    for (at, c) in rest.char_indices() {
        let after = rest
            .get(at.saturating_add(c.len_utf8())..)
            .unwrap_or_default();
        match c {
            'v' | 'q' | 'r' | 'h' | 'V' => {}
            'p' => return Some(ShortCluster::Package((!after.is_empty()).then_some(after))),
            'F' | 'j' | 'Z' | 'C' => return Some(ShortCluster::Plain),
            _ => return Some(ShortCluster::Unread),
        }
    }
    Some(ShortCluster::Plain)
}

/// Whether `word`, a command word's basename, is an interpreter that runs a program it is given
/// as an argument or on its input: Python, Perl, Node.js, Ruby, PHP, Deno or Bun.
fn is_interpreter(word: &str) -> bool {
    word.starts_with("python")
        || matches!(
            word,
            "perl" | "node" | "nodejs" | "ruby" | "php" | "deno" | "bun"
        )
}

/// Why a command, its command word and `args` after its wrappers, may run cargo with no `cargo`
/// word the check can see (#1169 round 3 review, bypass 6): `eval`; a shell or interpreter fed
/// by a pipe or a here-string, or given its program in an argument (a shell's `-c`, an
/// interpreter's `-c`, `-e`, `-E` or `-p`, in any short cluster, or `--eval`, `--print`,
/// `--command`); and a glob in the command word, unless the word is a `case` pattern.
fn hidden_command(
    command_word: &str,
    args: &[&str],
    fed: bool,
    case_pattern: bool,
) -> Option<&'static str> {
    let base = basename(command_word);
    if base == "eval" {
        return Some("`eval` runs a string the check cannot read");
    }
    if !case_pattern
        && !matches!(command_word, "[" | "[[")
        && command_word.contains(['*', '?', '['])
    {
        return Some("a glob in a command word");
    }
    if !(is_shell(base) || is_interpreter(base)) {
        return None;
    }
    if fed {
        return Some("a pipe or here-string into a shell or an interpreter");
    }
    let letters: &[char] = if is_shell(base) {
        &['c']
    } else {
        &['c', 'e', 'E', 'p']
    };
    let program = |arg: &&str| {
        matches!(*arg, "--eval" | "--print" | "--command")
            || arg
                .strip_prefix('-')
                .is_some_and(|rest| !rest.starts_with('-') && rest.contains(letters))
    };
    args.iter().any(program).then_some(PROGRAM_IN_AN_ARGUMENT)
}

/// [`hidden_command`]'s reason for a shell or interpreter given its program in an argument.
const PROGRAM_IN_AN_ARGUMENT: &str = "a shell or interpreter given its program in an argument";

