    /// DEC-931: every package built on a mutated one stays unoptimised, so a mutant rebuilds only
    /// what it rebuilt before at the cost it had; the layers under it and every package beside it
    /// are optimised. Shown on a fixture graph and on the repository's own: a `mandate-executor`
    /// mutant leaves the reference harness and the shell unoptimised and optimises the journal it
    /// is built on.
    #[test]
    fn only_what_a_mutant_rebuilds_stays_unoptimised() -> Result<()> {
        let set = |names: &[&str]| -> BTreeSet<String> {
            names.iter().map(|name| (*name).to_owned()).collect()
        };
        let closure = BTreeMap::from([
            ("a".to_owned(), set(&["a"])),
            ("b".to_owned(), set(&["a", "b"])),
            ("c".to_owned(), set(&["a", "b", "c"])),
            ("d".to_owned(), set(&["a", "d"])),
        ]);
        let mutants = BTreeMap::from([("b".to_owned(), 2)]);
        assert_eq!(
            unoptimised_packages(&mutants, &closure),
            set(&["b", "c"]),
            "the mutated package and the one built on it, not the one under it or beside it"
        );
        let config = unoptimised_config(&set(&["b", "c"]));
        assert_eq!(
            config,
            [
                "--config=profile.dev.package.b.opt-level=0",
                "--config=profile.test.package.b.opt-level=0",
                "--config=profile.dev.package.c.opt-level=0",
                "--config=profile.test.package.c.opt-level=0",
            ]
        );
        let preflight = preflight_args(&mutants, &["c"], &config);
        assert!(
            config.iter().all(|arg| preflight.contains(arg)),
            "the pre-flight builds under the run's configuration, so the run reuses it"
        );
        let run = mutants_args("change.diff", None, &["c"], None, &config)?;
        for arg in &config {
            assert!(
                run.contains(&format!("--cargo-arg={arg}")),
                "every cargo invocation of the run, baseline and mutants, gets {arg}"
            );
        }
        let real = workspace_closure(&metadata_in(&repo_root()?)?);
        let executor =
            unoptimised_packages(&BTreeMap::from([("mandate-executor".to_owned(), 1)]), &real);
        for kept in ["mandate-executor", REFCASES, "mandate-shell"] {
            assert!(
                executor.contains(kept),
                "{kept} is rebuilt by an executor mutant"
            );
        }
        for optimised in ["mandate-journal", "mandate-canon", "mandate-num"] {
            assert!(
                !executor.contains(optimised),
                "{optimised} is under the executor and optimised"
            );
        }
        Ok(())
    }

    /// DEC-850: the pre-flight builds every package the run tests, not only the ones its mutants
    /// are in, so no mutant's build under the sixty-second cap compiles the rest of that graph, as
    /// a `mandate-executor` mutant on #931 did; and it still lists every mutated package, whose
    /// live tests it counts.
    #[test]
    fn the_preflight_builds_every_tested_package_before_the_run_mutates_in_place() {
        let mutants = BTreeMap::from([
            ("mandate-executor".to_owned(), 3),
            ("mandate-shell".to_owned(), 1),
        ]);
        let tested = [
            "mandate-alpaca",
            "mandate-executor",
            "mandate-shell",
            "mandate-refcases",
        ];
        let args = preflight_args(&mutants, &tested, &[]);
        assert_eq!(
            args.get(..2),
            Some(&["nextest".to_owned(), "list".to_owned()][..]),
            "the pre-flight is a nextest listing, which builds the test binaries it lists"
        );
        let listed: Vec<&str> = args
            .iter()
            .filter_map(|arg| arg.strip_prefix("--package="))
            .collect();
        assert_eq!(
            listed,
            [
                "mandate-executor",
                "mandate-shell",
                "mandate-alpaca",
                "mandate-refcases"
            ],
            "every mutated package once, then every other tested package once"
        );
        let lone = preflight_args(
            &BTreeMap::from([("mandate-journal-pg".to_owned(), 1)]),
            &[],
            &[],
        );
        assert!(
            lone.contains(&"--package=mandate-journal-pg".to_owned()),
            "a mutated package is listed even if the tested set omits it, so its live tests are \
             still counted (DEC-139)"
        );
    }

    /// DEC-2367 item 2: a shard of more than one mutant writes its provisional record before
    /// cargo-mutants starts, so a job GitHub stops still leaves one; a shard of one writes none.
    #[test]
    fn a_shard_of_more_than_one_leaves_a_record_before_cargo_mutants_starts() -> Result<()> {
        let dir = env::temp_dir().join(format!("mandate-xtask-unfinished-{}", std::process::id()));
        if dir.exists() {
            fs::remove_dir_all(&dir)?;
        }
        fs::create_dir_all(&dir)?;
        let shard = crate::MutantShard { index: 0, total: 2 };
        let one = crate::launch_stop(
            &dir,
            Some(shard),
            vec!["mandate-executor".to_owned()],
            1,
            Duration::from_secs(30),
        );
        assert_eq!(one, None, "a shard of one runs to its end");
        assert!(
            !dir.join(crate::mutant_costs::COST_FILE).exists(),
            "a shard of one leaves none"
        );
        let five = crate::launch_stop(
            &dir,
            Some(shard),
            vec!["mandate-executor".to_owned()],
            5,
            Duration::from_secs(30),
        );
        assert_eq!(
            five,
            Some(Duration::from_secs(450)),
            "480 s from the gate's start"
        );
        let left: crate::mutant_costs::ShardCost = serde_json::from_str(&fs::read_to_string(
            dir.join(crate::mutant_costs::COST_FILE),
        )?)?;
        assert_eq!(
            (left.shard.as_str(), left.outcome.as_str(), left.overran),
            ("0/2", crate::mutant_costs::UNFINISHED, true)
        );
        assert_eq!(left.packages, ["mandate-executor"]);
        crate::record_shard_cost(
            &dir,
            Some(shard),
            vec!["mandate-executor".to_owned()],
            Duration::from_secs(1),
            Some(0),
            std::time::UNIX_EPOCH,
            false,
        );
        let finished: crate::mutant_costs::ShardCost = serde_json::from_str(&fs::read_to_string(
            dir.join(crate::mutant_costs::COST_FILE),
        )?)?;
        assert_eq!(
            (finished.outcome.as_str(), finished.overran),
            ("caught", false),
            "a shard that finishes replaces its provisional record"
        );
        fs::remove_dir_all(&dir)?;
        Ok(())
    }

    /// DEC-850: an in-place run that ends with a mutant still in the tree has it written back and
    /// is refused, naming the file, and a run that reverted everything passes untouched.
    #[test]
    fn an_in_place_run_that_leaves_a_mutant_behind_is_restored_and_refused() -> Result<()> {
        let dir = env::temp_dir().join(format!("mandate-xtask-unmutated-{}", std::process::id()));
        if dir.exists() {
            fs::remove_dir_all(&dir)?;
        }
        let fx = Fixture(dir);
        fx.write("crates/a/src/lib.rs", "pub fn f() -> bool { true }\n")?;
        fx.write("crates/b/src/lib.rs", "pub fn g() -> u8 { 1 }\n")?;
        let touched = [
            "crates/a/src/lib.rs".to_owned(),
            "crates/b/src/lib.rs".to_owned(),
        ];

        UnmutatedSource::read(&fx.0, &touched)?
            .restored(&fx.0)
            .context("a run that reverted every mutant passes")?;

        let unmutated = UnmutatedSource::read(&fx.0, &touched)?;
        fx.write("crates/b/src/lib.rs", "pub fn g() -> u8 { 0 }\n")?;
        let refused = unmutated
            .restored(&fx.0)
            .expect_err("a mutant left in the tree refuses the run");
        assert!(
            refused
                .to_string()
                .contains("left crates/b/src/lib.rs mutated"),
            "{refused}"
        );
        assert_eq!(
            fs::read_to_string(fx.0.join("crates/b/src/lib.rs"))?,
            "pub fn g() -> u8 { 1 }\n",
            "and the caller's checkout gets its source back"
        );
        assert_eq!(
            fs::read_to_string(fx.0.join("crates/a/src/lib.rs"))?,
            "pub fn f() -> bool { true }\n"
        );
        Ok(())
    }

    /// DEC-852: the run's test phases take a nextest configuration that starts the mutated
    /// packages' tests before every other tested package's, and only reorders: one override, a
    /// priority and an exact-package filter, and nothing that skips or times a test.
    #[test]
    fn a_shard_runs_its_mutated_packages_tests_first() -> Result<()> {
        let config: toml::Value = toml::from_str(&test_order_config(&[
            "mandate-executor".to_owned(),
            "mandate-shell".to_owned(),
        ]))?;
        let overrides = config
            .get("profile")
            .and_then(|profile| profile.get("default"))
            .and_then(|default| default.get("overrides"))
            .and_then(toml::Value::as_array)
            .context("one `profile.default.overrides` list")?;
        assert_eq!(overrides.len(), 1);
        let first = overrides[0].as_table().context("the override is a table")?;
        assert_eq!(
            first.keys().map(String::as_str).collect::<Vec<_>>(),
            ["filter", "priority"],
            "a priority and the packages it applies to, and no setting that skips, retries or \
             times a test"
        );
        assert_eq!(
            first.get("filter").and_then(toml::Value::as_str),
            Some("package(=mandate-executor) | package(=mandate-shell)"),
            "exactly the mutated packages, by exact name"
        );
        assert_eq!(
            first.get("priority").and_then(toml::Value::as_integer),
            Some(100),
            "nextest's highest priority, so they start before every other tested package"
        );

        let order = TestOrder::write(&["mandate-shell".to_owned()])?
            .context("a slice with a mutant writes its order")?;
        let path = order.0.to_str().context("non-UTF-8 temp path")?.to_owned();
        assert_eq!(
            fs::read_to_string(&order.0)?,
            test_order_config(&["mandate-shell".to_owned()])
        );
        let args = mutants_args("change.diff", None, &["mandate-shell"], Some(&order), &[])?;
        assert_eq!(
            args.windows(2)
                .filter(|pair| {
                    pair[0] == "--cargo-test-arg=--tool-config-file"
                        && pair[1] == format!("--cargo-test-arg=mandate-mutants:{path}")
                })
                .count(),
            1,
            "every test phase, the baseline's included, reads the order once"
        );
        drop(order);
        assert!(!Path::new(&path).exists(), "and the file goes with the run");
        assert!(
            TestOrder::write(&[])?.is_none(),
            "a slice with no mutant has nothing to order"
        );
        Ok(())
    }

    /// Two test orders written in one process get two files, and dropping one leaves the other:
    /// under plain `cargo test` every test thread shares the process id, so a name made of the id
    /// alone let one shard's order overwrite or remove another's.
    #[test]
    fn two_test_orders_in_one_process_never_share_a_file() -> Result<()> {
        let first = TestOrder::write(&["mandate-shell".to_owned()])?
            .context("a slice with a mutant writes its order")?;
        let second = TestOrder::write(&["mandate-executor".to_owned()])?
            .context("a slice with a mutant writes its order")?;
        assert_ne!(first.0, second.0, "each order has its own file");
        drop(first);
        assert_eq!(
            fs::read_to_string(&second.0)?,
            test_order_config(&["mandate-executor".to_owned()]),
            "and dropping one order leaves the other's file, with its own packages"
        );
        assert_ne!(
            unique_temp_path("mandate-xtask-names", ".toml"),
            unique_temp_path("mandate-xtask-names", ".toml"),
            "no two temporary paths this process names are the same"
        );
        Ok(())
    }

    /// A fixture's pending gate builds in the fixture's own `target/`, never in a
    /// `CARGO_TARGET_DIR` the caller exported: every pending fixture's crate is `fx`, and under one
    /// shared directory concurrent fixtures overwrote each other's test binaries ("`fails_by_todo`
    /// … did not run"). The gate on the repository itself keeps the caller's directory.
    #[test]
    fn only_a_fixtures_pending_gate_drops_the_callers_target_dir() {
        let args = ["nextest", "run"];
        let fixture = pending_nextest(Path::new("."), &args, BuildDir::OwnTree);
        let envs: BTreeMap<&OsStr, Option<&OsStr>> = fixture.get_envs().collect();
        assert_eq!(
            envs.get(OsStr::new(CARGO_TARGET_DIR)),
            Some(&None),
            "a fixture's run removes the caller's CARGO_TARGET_DIR"
        );
        let real = pending_nextest(Path::new("."), &args, BuildDir::Callers);
        let envs: BTreeMap<&OsStr, Option<&OsStr>> = real.get_envs().collect();
        assert_eq!(
            envs.get(OsStr::new(CARGO_TARGET_DIR)),
            None,
            "the repository's own run leaves the caller's build directory as it is"
        );
        assert_eq!(
            envs.get(OsStr::new("NEXTEST_EXPERIMENTAL_LIBTEST_JSON")),
            Some(&Some(OsStr::new("1"))),
            "and both still ask nextest for libtest JSON"
        );
    }

    /// Two gate diffs in one process get two files, and dropping one leaves the other: under plain
    /// `cargo test` every test thread shares the process id, and one gate's drop removed the diff
    /// another was about to time ("timing the diff this run reads: No such file or directory").
    #[test]
    fn two_gate_diffs_in_one_process_never_share_a_file() -> Result<()> {
        let fx = Fixture::gated("gate-diff-names")?;
        let base = fs::read_to_string(fx.0.join("base"))?;
        let base = base.trim();
        let first = gate_diff(&fx.0, Some(base))?.context("the fixture's diff changes source")?;
        let second = gate_diff(&fx.0, Some(base))?.context("the fixture's diff changes source")?;
        assert_ne!(first.file, second.file, "each diff has its own file");
        drop(first);
        assert!(
            second.file.exists(),
            "and dropping one gate's diff leaves the other's in place"
        );
        assert_ne!(gate_diff_path(), gate_diff_path());
        Ok(())
    }

    #[test]
    fn mutation_arguments_add_a_shard_once_and_leave_local_runs_complete() -> Result<()> {
        let packages = ["mandate-journal", "mandate-refcases"];
        let unsharded = mutants_args("change.diff", None, &packages, None, &[])?;
        assert!(
            !unsharded
                .iter()
                .any(|arg| arg.starts_with("--cargo-test-arg")),
            "without an order nothing is passed to nextest"
        );
        assert!(
            !unsharded.iter().any(|arg| arg == "--shard"),
            "a local `cargo xtask check` run must cover the complete diff"
        );
        assert!(unsharded.contains(&"--test-package=mandate-refcases".to_owned()));
        assert!(
            !unsharded.iter().any(|arg| arg == "-E"),
            "the reference package runs whole, so no nextest filter narrows it"
        );
        assert_eq!(
            unsharded
                .windows(2)
                .find(|pair| pair[0] == "--timeout")
                .map(|pair| pair[1].as_str()),
            Some(MUTANT_TEST_TIMEOUT),
            "the per-mutant timeout is set here, not derived from a baseline whose packages are \
             the slice's own mutants and so need not include the reference package (DEC-498)"
        );
        assert_eq!(
            unsharded
                .windows(2)
                .find(|pair| pair[0] == "--build-timeout")
                .map(|pair| pair[1].as_str()),
            Some(MUTANT_BUILD_TIMEOUT),
            "a mutated operator in a top-level `const` can grow an array and so a build; this is \
             the third of the three phases DEC-498's shard budget caps, the other two being both \
             test phases under `--timeout`"
        );
        assert_eq!(
            unsharded
                .iter()
                .filter(|arg| *arg == MUTANTS_IN_PLACE)
                .count(),
            1,
            "the run builds in the tree the pre-flight built, not in a scratch copy whose target \
             directory starts empty (DEC-850); one tree holds one mutant at a time, so a shard's \
             critical path is its mutants in a row and the timeout keeps the margin DEC-498 \
             measured"
        );
        assert!(
            !unsharded.iter().any(|arg| arg == "--jobs"),
            "cargo-mutants 27.1.0 refuses `--jobs` beside `--in-place`"
        );

        let sharded = mutants_args(
            "change.diff",
            Some(MutantShard {
                index: 6,
                total: 12,
            }),
            &packages,
            None,
            &[],
        )?;
        assert_eq!(
            sharded
                .windows(2)
                .filter(|pair| pair[0] == "--shard" && pair[1] == "6/12")
                .count(),
            1
        );
        assert_eq!(
            sharded
                .windows(2)
                .filter(|pair| pair[0] == "--sharding" && pair[1] == "slice")
                .count(),
            1
        );
        Ok(())
    }

    #[test]
    fn debt_markers_match_whole_words_only() {
        let marker = concat!("TO", "DO");
        assert!(contains_word(&format!("// {marker}: later"), marker));
        assert!(contains_word(marker, marker));
        assert!(!contains_word(&format!("{marker}S"), marker));
        assert!(!contains_word(&format!("my_{marker}"), marker));
    }

    #[test]
    fn ignore_needs_a_pending_story() {
        assert!(is_pending_marker("    #[ignore = \"pending E5-1\"]"));
        assert!(is_pending_marker("#[ignore = \"pending E12-30\"]"));
        assert!(!is_pending_marker("#[ignore]"));
        assert!(!is_pending_marker("#[ignore = \"slow\"]"));
        assert!(!is_pending_marker("#[ignore = \"pending E5\"]"));
        assert!(!is_pending_marker("#[ignore = \"pending E-1\"]"));
        assert!(!is_pending_marker("#[ignore = \"pending E5-x\"]"));
    }

    /// The single-file check as it was before the map became a directory, as an oracle: every
    /// crate named as `` `crate` ``, every fixture by its path, every backticked repository path
    /// existing, all over one text.
    fn single_file_feature_map_problems(
        root: &Path,
        text: &str,
        meta: &Metadata,
    ) -> Result<BTreeSet<String>> {
        let mut problems = BTreeSet::new();
        for pkg in workspace_packages(meta) {
            if !text.contains(&format!("`{}`", pkg.name)) {
                problems.insert(format!("crate `{}` has no entry", pkg.name));
            }
        }
        for entry in fs::read_dir(root.join("fixtures/refcases"))? {
            let name = entry?.file_name().to_string_lossy().into_owned();
            if !text.contains(&format!("fixtures/refcases/{name}")) {
                problems.insert(format!("fixtures/refcases/{name} has no entry"));
            }
        }
        for path in backticked_paths(text) {
            if !root.join(path).exists() {
                problems.insert(format!("`{path}`, which does not exist"));
            }
        }
        Ok(problems)
    }

    /// The directory's problems in the oracle's terms: a missing path is named with the file it
    /// is in, which the single file had no need to say, so that prefix is dropped to compare.
    fn without_file_names(problems: Vec<String>) -> BTreeSet<String> {
        problems
            .into_iter()
            .map(|problem| match problem.split_once(" names `") {
                Some((_, rest)) if !problem.starts_with("crate ") => format!("`{rest}"),
                _ => problem,
            })
            .collect()
    }

    /// One way a feature's text drifts from the workspace.
    type Drift = fn(&str) -> String;

    /// The feature map as a directory catches exactly the drift the single `feature-map.md` did,
    /// in a fixture workspace: a crate named nowhere, a reference-case suite named nowhere, and a
    /// path that does not exist, each with the map in one feature file and split across three, and
    /// nothing when the map is complete. A feature file without its `# ` title is refused too.
    #[test]
    fn the_feature_map_directory_catches_the_drift_the_single_file_did() -> Result<()> {
        let dir = env::temp_dir().join(format!("mandate-xtask-feature-map-{}", std::process::id()));
        if dir.exists() {
            fs::remove_dir_all(&dir)?;
        }
        let fx = Fixture(dir);
        fx.write(
            "Cargo.toml",
            "[workspace]\nmembers = [\"crates/alpha\", \"crates/beta\"]\nresolver = \"3\"\n",
        )?;
        for name in ["alpha", "beta"] {
            fx.write(
                &format!("crates/{name}/Cargo.toml"),
                &format!("[package]\nname = \"{name}\"\nversion = \"0.0.0\"\nedition = \"2024\"\n"),
            )?;
            fx.write(&format!("crates/{name}/src/lib.rs"), "")?;
        }
        fx.write("fixtures/refcases/one.json", "{}")?;
        fs::copy(
            repo_root()?.join("rust-toolchain.toml"),
            fx.0.join("rust-toolchain.toml"),
        )?;
        output_in(&fx.0, "cargo", &["generate-lockfile", "--offline"])?;
        let meta = metadata_in(&fx.0)?;

        let sections = [
            "# Alpha\n\n- **Code:** `alpha`: `crates/alpha/src/lib.rs`.\n",
            "# Beta\n\n- **Code:** `beta`: `crates/beta/src/lib.rs`.\n",
            "# Cases\n\n- **Reference cases:** `fixtures/refcases/one.json`.\n",
        ];
        let drifts: [(&str, Drift); 4] = [
            ("complete", |s| s.to_owned()),
            ("a crate named nowhere", |s| s.replace("`beta`", "beta")),
            ("a suite named nowhere", |s| {
                s.replace("`fixtures/refcases/one.json`", "the suite")
            }),
            ("a path that does not exist", |s| {
                s.replace("crates/alpha/src/lib.rs", "crates/alpha/src/gone.rs")
            }),
        ];
        let features = fx.0.join(FEATURE_MAP);
        for (drift, apply) in drifts {
            let drifted: Vec<String> = sections.iter().map(|s| apply(s)).collect();
            let expected = single_file_feature_map_problems(&fx.0, &drifted.join("\n"), &meta)?;
            assert_eq!(
                expected.is_empty(),
                drift == "complete",
                "the oracle sees {drift}: {expected:?}"
            );
            for split in [false, true] {
                if features.exists() {
                    fs::remove_dir_all(&features)?;
                }
                fx.write(&format!("{FEATURE_MAP}/README.md"), "# Feature map\n")?;
                if split {
                    for (k, text) in drifted.iter().enumerate() {
                        fx.write(&format!("{FEATURE_MAP}/f{k}.md"), text)?;
                    }
                } else {
                    let joined = drifted
                        .iter()
                        .map(|s| s.replacen("# ", "## ", 1))
                        .collect::<Vec<_>>()
                        .join("\n");
                    fx.write(
                        &format!("{FEATURE_MAP}/all.md"),
                        &format!("# All\n\n{joined}"),
                    )?;
                }
                assert_eq!(
                    without_file_names(feature_map_problems(&fx.0, &meta)?),
                    expected,
                    "{drift}, the map {}",
                    if split {
                        "split across files"
                    } else {
                        "in one file"
                    }
                );
            }
        }

        fx.write(&format!("{FEATURE_MAP}/untitled.md"), "no title\n")?;
        let untitled = feature_map_problems(&fx.0, &meta)?;
        assert!(
            untitled.contains(&format!(
                "{FEATURE_MAP}/untitled.md does not open with a `# ` title"
            )),
            "a feature file without its title is refused: {untitled:?}"
        );
        fs::remove_dir_all(&features)?;
        fx.write(&format!("{FEATURE_MAP}/README.md"), "# Feature map\n")?;
        assert!(
            feature_map_problems(&fx.0, &meta)?
                .iter()
                .any(|p| p.ends_with("has no feature files")),
            "and a map of nothing but its README is refused"
        );
        fs::remove_dir_all(&fx.0).ok();
        Ok(())
    }

    /// The repository's own map passes, and every feature has a title for the index.
    #[test]
    fn the_repository_feature_map_is_complete() -> Result<()> {
        let root = repo_root()?;
        assert_eq!(
            feature_map_problems(&root, &metadata_in(&root)?)?,
            Vec::<String>::new()
        );
        assert!(feature_files(&root)?.len() > 1);
        Ok(())
    }

