    /// A program not on the closed world's list cannot be read, and neither can a wrapper but
    /// `sudo install`, a script not on the list, or `rustup` and `gh` running anything but their
    /// listed subcommands (DEC-873 item 1).
    #[test]
    fn an_unknown_program_cannot_be_read() -> Result<()> {
        let jobs = [
            ("make", "make build"),
            ("just", "just test"),
            ("dot-slash", "./run.sh"),
            ("other-script", ".github/scripts/other.sh"),
            ("true", "true"),
            ("cd", "cd crates"),
            ("rustup-run", "rustup run nightly cargo test -p a-lib"),
            ("gh-extension", "gh extension exec x"),
            ("env-wrapper", "env FOO=1 cargo test -p a-lib"),
            ("timeout-wrapper", "timeout 5 cargo test -p a-lib"),
            ("sudo-rm", "sudo rm -rf target"),
        ];
        let mut all = jobs.to_vec();
        all.push(("lib-tests", "cargo test -p a-lib"));
        let mut flows = clean_scripts();
        flows.push(workflow(&all));
        let problems = host_problems(&flows)?;
        unreadable(&problems, &jobs.map(|(job, _)| job));
        names(&problems, &["make"], &["lib-tests"]);
        Ok(())
    }

    /// A listed repository script is read only while its whole text, comments included, holds no
    /// `cargo` word, no `.cargo` and no `CARGO_`; one that does, or one the check was not given,
    /// cannot be read, and the problem names the script (DEC-873 item 2).
    #[test]
    fn a_repository_script_is_read_only_while_it_names_no_cargo() -> Result<()> {
        let mut flows: Vec<CiFile> = clean_scripts()
            .into_iter()
            .filter(|file| !file.path.ends_with("merge-approved.sh"))
            .map(|file| match file.path.as_str() {
                ".github/scripts/docs-checks.sh" => ci_file(
                    &file.path,
                    "#!/usr/bin/env bash\nset -euo pipefail\ncargo build\n",
                ),
                ".github/scripts/start-postgres.sh" => ci_file(
                    &file.path,
                    "#!/usr/bin/env bash\n# reads CARGO_HOME\necho ok\n",
                ),
                _ => file,
            })
            .collect();
        flows.push(workflow(&[
            ("clean", ".github/scripts/docs-only.sh"),
            ("planted", ".github/scripts/docs-checks.sh"),
            ("commented", ".github/scripts/start-postgres.sh"),
            ("missing", ".github/scripts/merge-approved.sh \"$PR\""),
        ]));
        let problems = host_problems(&flows)?;
        unreadable(&problems, &["planted", "commented", "missing"]);
        for script in ["docs-checks.sh", "start-postgres.sh", "merge-approved.sh"] {
            let named = problems
                .iter()
                .any(|p| p.contains(&format!("`.github/scripts/{script}`")));
            assert!(named, "names `{script}`: {problems:?}");
        }
        names(&problems, &["planted"], &["clean"]);
        Ok(())
    }

    /// `npm` and `npx` are read only in a job whose `defaults.run.working-directory` is `web` or
    /// below it, that holds no cargo word, and beside the `package.json` of that directory; in
    /// any other job they cannot be read (DEC-873 item 3).
    #[test]
    fn npm_runs_only_in_a_web_job_without_cargo() -> Result<()> {
        let flows = [yaml_lines(&[
            "on: push",
            "jobs:",
            "  web:",
            "    defaults:",
            "      run:",
            "        working-directory: web",
            "    steps:",
            "      - run: npm ci",
            "      - run: npx playwright install-deps chromium",
            "  web-app:",
            "    defaults:",
            "      run:",
            "        working-directory: web/app",
            "    steps:",
            "      - run: npm test --if-present",
            "  root-npm:",
            "    steps:",
            "      - run: npm ci",
            "  step-web:",
            "    steps:",
            "      - working-directory: web",
            "        run: npx playwright test",
            "  web-with-cargo:",
            "    defaults:",
            "      run:",
            "        working-directory: web",
            "    steps:",
            "      - run: cargo test -p a-lib",
            "      - run: npm run build",
            "  other-dir:",
            "    defaults:",
            "      run:",
            "        working-directory: webapp",
            "    steps:",
            "      - run: npm ci",
        ])];
        let package = "{\"scripts\": {\"build\": \"next build\", \"test\": \"vitest run\"}}\n";
        let [workflow_file] = flows;
        let flows = [
            workflow_file,
            ci_file("web/package.json", package),
            ci_file("web/app/package.json", package),
        ];
        let problems = host_problems(&flows)?;
        unreadable(
            &problems,
            &["root-npm", "step-web", "web-with-cargo", "other-dir"],
        );
        names(&problems, &["root-npm"], &["web", "web-app"]);
        Ok(())
    }

    /// The one `xargs` line a person has read, `web-e2e.yml`'s removal of the Microsoft apt
    /// source, is read only byte for byte and only in that file (DEC-873 item 4).
    #[test]
    fn the_read_xargs_line_is_read_only_exactly() -> Result<()> {
        let line = "grep -rls 'packages\\.microsoft\\.com' /etc/apt/sources.list \
                    /etc/apt/sources.list.d/ | tee /dev/stderr | xargs -r sudo rm -f";
        let flow = |path: &str, run: &str| {
            ci_file(
                path,
                &format!(
                    "on: push\njobs:\n  web-e2e:\n    defaults:\n      run:\n        \
                     working-directory: web\n    steps:\n      - run: {run}\n"
                ),
            )
        };
        let read = flow(".github/workflows/web-e2e.yml", line);
        assert_eq!(host_problems(&[read])?, Vec::<String>::new());
        let changed = flow(
            ".github/workflows/web-e2e.yml",
            &line.replace("rm -f", "rm -rf"),
        );
        unreadable(&host_problems(&[changed])?, &["web-e2e"]);
        let elsewhere = flow(".github/workflows/nightly.yml", line);
        unreadable(&host_problems(&[elsewhere])?, &["web-e2e"]);
        Ok(())
    }

    /// A local action or reusable workflow, `uses: ./…` on a step or a job, quoted or not, cannot
    /// be read; a listed remote action, pinned as the repository pins it, can (DEC-873 item 6).
    #[test]
    fn a_local_action_or_workflow_cannot_be_read() -> Result<()> {
        let flows = [yaml_lines(&[
            "on: push",
            "jobs:",
            "  local-action:",
            "    steps:",
            "      - uses: ./.github/actions/setup",
            "  local-workflow:",
            "    uses: ./.github/workflows/other.yml",
            "  quoted-local:",
            "    steps:",
            "      - uses: \"./.github/actions/setup\"",
            "  remote:",
            "    steps:",
            "      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1",
            "      - run: cargo test -p a-lib",
        ])];
        let problems = host_problems(&flows)?;
        unreadable(
            &problems,
            &["local-action", "local-workflow", "quoted-local"],
        );
        names(&problems, &["local-action"], &["remote"]);
        Ok(())
    }

    /// Alias expansion finds the subcommand past a `+toolchain` and past the value of `-Z` and
    /// `--color`, so the alias behind it is expanded and its build judged (#1169 round 4 review,
    /// mutants P8 and P9).
    #[test]
    fn an_alias_is_found_past_a_toolchain_and_global_flag_values() -> Result<()> {
        let flows = [
            ci_file(
                ".cargo/config.toml",
                "[alias]\nhost = \"test -p rh-host\"\n",
            ),
            workflow(&[
                ("toolchain", "cargo +nightly host -p a-lib"),
                ("color", "cargo --color never host -p a-lib"),
                ("unstable", "cargo -Z unstable-options host -p a-lib"),
                ("lib-tests", "cargo test -p a-lib"),
            ]),
        ];
        let problems = host_problems(&flows)?;
        judged_with_host(&problems, &["toolchain", "color", "unstable"]);
        names(&problems, &["toolchain"], &["lib-tests"]);
        Ok(())
    }

    /// A command word built by a backtick substitution cannot be read, whether the substitution
    /// is the whole word or a piece of it (#1169 round 4 review, bypass 3; DEC-873 item 1).
    #[test]
    fn a_backtick_command_word_cannot_be_read() -> Result<()> {
        let flows = [yaml_lines(&[
            "on: push",
            "jobs:",
            "  backtick-piece:",
            "    steps:",
            "      - run: |",
            "          `printf ca`rgo test -p rh-host",
            "  backtick-whole:",
            "    steps:",
            "      - run: |",
            "          `echo cargo` test -p rh-host",
            "  lib-tests:",
            "    steps:",
            "      - run: cargo test -p a-lib",
        ])];
        let problems = host_problems(&flows)?;
        unreadable(&problems, &["backtick-piece", "backtick-whole"]);
        names(&problems, &["backtick-piece"], &["lib-tests"]);
        Ok(())
    }

    /// A path to cargo that the shell computes cannot be read, though its last piece reads
    /// `cargo`: brace expansion (`/usr/{bin,local}/cargo`, two words), a backtick substitution
    /// and an expansion in the path. The backtick runs only `echo`, which the closed world reads,
    /// so only its computed-word rule refuses these, and dropping `{`, `` ` `` or `$` from it is
    /// caught; a literal path to cargo is read (DEC-873 item 1).
    #[test]
    fn a_computed_path_to_cargo_cannot_be_read() -> Result<()> {
        let flows = [yaml_lines(&[
            "on: push",
            "jobs:",
            "  brace-path:",
            "    steps:",
            "      - run: /usr/{bin,local}/cargo test -p a-lib",
            "  backtick-path:",
            "    steps:",
            "      - run: |",
            "          `echo /usr/bin`/cargo test -p a-lib",
            "  dollar-path:",
            "    steps:",
            "      - run: $BIN/cargo test -p a-lib",
            "  literal-path:",
            "    steps:",
            "      - run: /usr/bin/cargo test -p a-lib",
        ])];
        let problems = host_problems(&flows)?;
        unreadable(&problems, &["brace-path", "backtick-path", "dollar-path"]);
        names(&problems, &["brace-path"], &["literal-path"]);
        Ok(())
    }

    /// The five allowed `CARGO_*` names are read only exactly: a name that extends one
    /// (`CARGO_PROFILE_DEV_DEBUG_ASSERTIONS`, `CARGO_TERM_COLORS`) or holds one after a prefix
    /// (`XCARGO_TERM_COLOR`), in job `env`, step `env` or inline, cannot be read (DEC-873 item 5).
    #[test]
    fn an_allowed_cargo_name_is_read_only_exactly() -> Result<()> {
        let flows = [yaml_lines(&[
            "on: push",
            "jobs:",
            "  extended-job-env:",
            "    env:",
            "      CARGO_PROFILE_DEV_DEBUG_ASSERTIONS: false",
            "    steps:",
            "      - run: cargo test -p a-lib",
            "  extended-step-env:",
            "    steps:",
            "      - env:",
            "          CARGO_TERM_COLORS: always",
            "        run: cargo test -p a-lib",
            "  extended-inline:",
            "    steps:",
            "      - run: CARGO_MUTANTS_VERSIONS=1 cargo test -p a-lib",
            "  prefixed:",
            "    env:",
            "      XCARGO_TERM_COLOR: always",
            "    steps:",
            "      - run: cargo test -p a-lib",
            "  exact:",
            "    env:",
            "      CARGO_TERM_COLOR: always",
            "      CARGO_PROFILE_DEV_DEBUG: 0",
            "    steps:",
            "      - run: cargo test -p a-lib",
        ])];
        let problems = host_problems(&flows)?;
        unreadable(
            &problems,
            &[
                "extended-job-env",
                "extended-step-env",
                "extended-inline",
                "prefixed",
            ],
        );
        names(&problems, &["extended-job-env"], &["exact"]);
        Ok(())
    }

    /// A listed repository script whose comment alone names `cargo` or `.cargo` cannot be read,
    /// and the problem names the script: a comment is one edit from code (DEC-873 item 2).
    #[test]
    fn a_repository_script_comment_naming_cargo_cannot_be_read() -> Result<()> {
        let flows: Vec<CiFile> = clean_scripts()
            .into_iter()
            .map(|file| match file.path.as_str() {
                ".github/scripts/docs-only.sh" => ci_file(
                    &file.path,
                    "#!/usr/bin/env bash\n# the same check cargo runs\necho ok\n",
                ),
                ".github/scripts/docs-checks.sh" => ci_file(
                    &file.path,
                    "#!/usr/bin/env bash\n# see .cargo/config.toml\necho ok\n",
                ),
                _ => file,
            })
            .chain([workflow(&[
                ("word", ".github/scripts/docs-only.sh"),
                ("dot-cargo", ".github/scripts/docs-checks.sh"),
                ("clean", ".github/scripts/start-postgres.sh"),
            ])])
            .collect();
        let problems = host_problems(&flows)?;
        unreadable(&problems, &["word", "dot-cargo"]);
        for script in ["docs-only.sh", "docs-checks.sh"] {
            let named = problems
                .iter()
                .any(|p| p.contains(&format!("`.github/scripts/{script}`")));
            assert!(named, "names `{script}`: {problems:?}");
        }
        names(&problems, &["word"], &["clean"]);
        Ok(())
    }

    /// A redirection before the command word, glued or spaced, to a file or appended, and a
    /// descriptor number before it, is skipped as the shell skips it, so the cargo word after it
    /// is judged; a `run:` value that starts with `>` is no block scalar header and cannot be read
    /// (#1169 round 5 review, B1; DEC-851 item 6's structural skip).
    #[test]
    fn a_redirection_before_the_command_word_is_skipped() -> Result<()> {
        let flows = [yaml_lines(&[
            "on: push",
            "jobs:",
            "  glued:",
            "    steps:",
            "      - run: |",
            "          >/dev/null cargo build --workspace",
            "  spaced:",
            "    steps:",
            "      - run: |",
            "          > /dev/null cargo build --workspace",
            "  to-a-file:",
            "    steps:",
            "      - run: |",
            "          >out cargo build --workspace",
            "  appended:",
            "    steps:",
            "      - run: |",
            "          >>out cargo build --workspace",
            "  descriptor:",
            "    steps:",
            "      - run: |",
            "          2>/dev/null cargo build --workspace",
            "  after-a-command:",
            "    steps:",
            "      - run: echo start; >/dev/null cargo build --workspace",
            "  inline:",
            "    steps:",
            "      - run: >/dev/null cargo build --workspace",
            "  lib-tests:",
            "    steps:",
            "      - run: |",
            "          >/dev/null cargo test -p a-lib",
        ])];
        let problems = host_problems(&flows)?;
        judged_with_host(
            &problems,
            &[
                "glued",
                "spaced",
                "to-a-file",
                "appended",
                "descriptor",
                "after-a-command",
            ],
        );
        unreadable(&problems, &["inline"]);
        names(&problems, &["glued"], &["lib-tests"]);
        Ok(())
    }

    /// An unquoted heredoc's body expands, so a command substitution in it, `$(` or a backtick,
    /// cannot be read, whatever it runs; a quoted delimiter, a parameter expansion and an escaped
    /// `\$(` can (#1169 round 5 review, B2).
    #[test]
    fn a_substitution_in_an_unquoted_heredoc_cannot_be_read() -> Result<()> {
        let flows = [yaml_lines(&[
            "on: push",
            "jobs:",
            "  substituted:",
            "    steps:",
            "      - run: |",
            "          cat > notes.txt <<EOF",
            "          $(cargo build --workspace)",
            "          EOF",
            "  backtick:",
            "    steps:",
            "      - run: |",
            "          cat > notes.txt <<EOF",
            "          `cargo build --workspace`",
            "          EOF",
            "  any-substitution:",
            "    steps:",
            "      - run: |",
            "          cat > notes.txt <<EOF",
            "          built on $(date)",
            "          EOF",
            "  dashed:",
            "    steps:",
            "      - run: |",
            "          cat > notes.txt <<-EOF",
            "          built on $(date)",
            "          EOF",
            "  read-heredocs:",
            "    steps:",
            "      - run: |",
            "          cat > a.txt <<'EOF'",
            "          $(date) and `date`",
            "          EOF",
            "          cat > b.txt <<\"EOF\"",
            "          $(date)",
            "          EOF",
            "          cat > c.txt <<EOF",
            "          ${HOME} and \\$(date)",
            "          EOF",
            "          cargo test -p a-lib",
        ])];
        let problems = host_problems(&flows)?;
        unreadable(
            &problems,
            &["substituted", "backtick", "any-substitution", "dashed"],
        );
        names(&problems, &["substituted"], &["read-heredocs"]);
        Ok(())
    }

    /// An `env:` key, at workflow, job, step or service level, and a command-prefix assignment
    /// are read only when the name is one the repository's workflows set or one of the seven
    /// `CARGO_*` names: `BASH_ENV`, `ENV`, `PATH`, `LD_PRELOAD`, `RUSTUP_TOOLCHAIN` and
    /// `NODE_OPTIONS`, in any case, cannot be read, nor can a listed name in another case, an
    /// inline `env:` mapping, an
    /// uppercase name assigned by a command of its own or a `for` loop, or `printf -v`; a
    /// lowercase local can (#1169 round 5 review, B3).
    #[test]
    fn an_environment_name_off_the_list_cannot_be_read() -> Result<()> {
        let job_env = |job: &str, name: &str| {
            format!(
                "  {job}:\n    env:\n      {name}: x\n    steps:\n      - run: cargo test -p a-lib\n"
            )
        };
        let step_env = |job: &str, name: &str| {
            format!(
                "  {job}:\n    steps:\n      - env:\n          {name}: x\n        run: cargo test -p \
                 a-lib\n"
            )
        };
        let mut text = String::from("on: push\njobs:\n");
        for (job, name) in [
            ("job-bash-env", "BASH_ENV"),
            ("job-env", "ENV"),
            ("job-toolchain", "RUSTUP_TOOLCHAIN"),
            ("job-lowercase", "bash_env"),
            ("job-listed-lowercase", "gh_token"),
        ] {
            text.push_str(&job_env(job, name));
        }
        for (job, name) in [
            ("step-path", "PATH"),
            ("step-preload", "LD_PRELOAD"),
            ("step-node", "NODE_OPTIONS"),
            ("step-mixed-case", "Path"),
        ] {
            text.push_str(&step_env(job, name));
        }
        for (job, run) in [
            ("prefix-path", "PATH=/tmp/bin cargo test -p a-lib"),
            ("prefix-lowercase", "path=/tmp/bin cargo test -p a-lib"),
            (
                "prefix-toolchain",
                "RUSTUP_TOOLCHAIN=nightly cargo test -p a-lib",
            ),
            ("prefix-bash-env", "BASH_ENV=x.txt cargo test -p a-lib"),
            (
                "prefix-listed-lowercase",
                "cargo_term_color=never cargo test -p a-lib",
            ),
            ("standalone", "PATH=/tmp/bin; cargo test -p a-lib"),
            (
                "loop-variable",
                "for PATH in /tmp/bin; do cargo test -p a-lib; done",
            ),
            ("printf-variable", "printf -v PATH '%s' /tmp/bin"),
        ] {
            text.push_str(&format!("  {job}:\n    steps:\n      - run: {run}\n"));
        }
        text.push_str(
            "  service-env:\n    services:\n      db:\n        image: \
             postgres:17.11@sha256:d74eeac9a635390a49bc21bd49fccd973de707e2a53a76ac49b552b8712ec46f\n        \
             env:\n          LD_PRELOAD: x\n    steps:\n      - run: cargo test -p a-lib\n",
        );
        text.push_str(
            "  allowed:\n    env:\n      MANDATE_PG_URL: postgres://localhost/x\n      \
             CARGO_TERM_COLOR: always\n    services:\n      db:\n        image: \
             postgres:17.11@sha256:d74eeac9a635390a49bc21bd49fccd973de707e2a53a76ac49b552b8712ec46f\n        \
             env:\n          POSTGRES_PASSWORD: postgres\n    steps:\n      - env:\n          \
             GH_TOKEN: x\n        run: MANDATE_TEST_PARTITION=1/2 cargo test -p a-lib\n      - run: \
             |\n          failed=0\n          for pr in 1 2; do echo \"$pr\"; done\n",
        );
        let flows = [
            ci_file(".github/workflows/ci.yml", &text),
            ci_file(
                ".github/workflows/top.yml",
                "on: push\nenv:\n  BASH_ENV: x.txt\njobs:\n  a:\n    steps:\n      - run: echo ok\n",
            ),
            ci_file(
                ".github/workflows/inline.yml",
                "on: push\nenv: { NODE_OPTIONS: x }\njobs:\n  b:\n    steps:\n      - run: echo ok\n",
            ),
        ];
        let problems = host_problems(&flows)?;
        unreadable(
            &problems,
            &[
                "job-bash-env",
                "job-env",
                "job-toolchain",
                "job-lowercase",
                "job-listed-lowercase",
                "step-path",
                "step-preload",
                "step-node",
                "step-mixed-case",
                "prefix-path",
                "prefix-lowercase",
                "prefix-toolchain",
                "prefix-bash-env",
                "prefix-listed-lowercase",
                "standalone",
                "loop-variable",
                "printf-variable",
                "service-env",
            ],
        );
        unreadable_file(&problems, ".github/workflows/top.yml");
        unreadable_file(&problems, ".github/workflows/inline.yml");
        names(&problems, &["job-env"], &["allowed"]);
        Ok(())
    }

    /// Every `CARGO_*` name but the seven the workflows need cannot be read, as an `env:` key or
    /// as a prefix assignment, so adding any one of these to the list is caught (#1169 round 5
    /// review, mutant M04; DEC-873 item 5). The two optimisation levels DEC-931 added are the
    /// `dev` and `test` profiles' only; the release profile's, and every name that could turn
    /// debug assertions or overflow checks off, stay refused.
    #[test]
    fn every_cargo_name_but_the_seven_cannot_be_read() -> Result<()> {
        let names_refused = [
            "CARGO_HOME",
            "CARGO_TARGET_DIR",
            "CARGO_BUILD_TARGET",
            "CARGO_BUILD_TARGET_DIR",
            "CARGO_BUILD_RUSTC",
            "CARGO_BUILD_RUSTC_WRAPPER",
            "CARGO_BUILD_RUSTFLAGS",
            "CARGO_ENCODED_RUSTFLAGS",
            "CARGO_BUILD_JOBS",
            "CARGO_INCREMENTAL",
            "CARGO_NET_OFFLINE",
            "CARGO_HTTP_PROXY",
            "CARGO_REGISTRIES_CRATES_IO_PROTOCOL",
            "CARGO_UNSTABLE_BUILD_STD",
            "CARGO_PROFILE_RELEASE_DEBUG",
            "CARGO_PROFILE_RELEASE_OPT_LEVEL",
            "CARGO_PROFILE_DEV_DEBUG_ASSERTIONS",
            "CARGO_PROFILE_TEST_DEBUG_ASSERTIONS",
            "CARGO_PROFILE_DEV_OVERFLOW_CHECKS",
            "CARGO_PROFILE_TEST_OVERFLOW_CHECKS",
            "CARGO_TERM_VERBOSE",
            "CARGO_TERM_QUIET",
            "CARGO_FEATURE_LIVE",
            "CARGO_CFG_FEATURE",
            "CARGO_MAKEFLAGS",
            "CARGO_LOG",
            "CARGO_CACHE_RUSTC_INFO",
            "CARGO_ALIAS_B",
            "CARGO_INSTALL_ROOT",
            "CARGO_MUTANTS_JOBS",
            "CARGO_TARGET_X86_64_UNKNOWN_LINUX_GNU_RUNNER",
            "CARGO_TARGET_X86_64_UNKNOWN_LINUX_GNU_LINKER",
        ];
        let mut text = String::from("on: push\njobs:\n");
        let mut jobs = Vec::new();
        for name in names_refused {
            let job = name.to_ascii_lowercase().replace('_', "-");
            text.push_str(&format!(
                "  env-{job}:\n    env:\n      {name}: x\n    steps:\n      - run: echo ok\n"
            ));
            text.push_str(&format!(
                "  prefix-{job}:\n    steps:\n      - run: {name}=x cargo test -p a-lib\n"
            ));
            jobs.push(format!("env-{job}"));
            jobs.push(format!("prefix-{job}"));
        }
        text.push_str(
            "  allowed:\n    env:\n      CARGO_TERM_COLOR: always\n      CARGO_MUTANTS_VERSION: \
             1\n      CARGO_MUTANTS_SHA256: x\n      CARGO_PROFILE_DEV_DEBUG: 0\n      \
             CARGO_PROFILE_TEST_DEBUG: 0\n    steps:\n      - run: CARGO_TERM_COLOR=never cargo \
             test -p a-lib\n",
        );
        let problems = host_problems(&[ci_file(".github/workflows/ci.yml", &text)])?;
        let jobs: Vec<&str> = jobs.iter().map(String::as_str).collect();
        unreadable(&problems, &jobs);
        names(&problems, &["env-cargo-home"], &["allowed"]);
        Ok(())
    }

    /// A step's or a default `shell:` is read only as exactly `bash`, the form the repository
    /// uses: one with any argument (`bash -c …`, `bash --rcfile x {0}`, `bash -e {0}`, `sh -c
    /// …`), a bare `sh` and a quoted `"bash"` cannot be read (#1169 round 5 review, B4).
    #[test]
    fn a_shell_with_arguments_cannot_be_read() -> Result<()> {
        let mut text = String::from("on: push\njobs:\n");
        for (job, shell) in [
            ("bash-c", "bash -c x {0}"),
            ("rcfile", "bash --rcfile x.txt {0}"),
            ("bash-e", "bash -e {0}"),
            ("sh-c", "sh -c x"),
            ("plain-sh", "sh"),
            ("quoted", "\"bash\""),
        ] {
            text.push_str(&format!(
                "  {job}:\n    steps:\n      - shell: {shell}\n        run: echo ok\n"
            ));
        }
        text.push_str(
            "  job-defaults:\n    defaults:\n      run:\n        shell: bash --noprofile {0}\n    \
             steps:\n      - run: echo ok\n",
        );
        text.push_str(
            "  plain-bash:\n    defaults:\n      run:\n        shell: bash\n    steps:\n      - \
             shell: bash\n        run: cargo test -p a-lib\n",
        );
        let flows = [
            ci_file(".github/workflows/ci.yml", &text),
            ci_file(
                ".github/workflows/defaults.yml",
                "on: push\ndefaults:\n  run:\n    shell: bash -c x\njobs:\n  a:\n    steps:\n      \
                 - run: echo ok\n",
            ),
        ];
        let problems = host_problems(&flows)?;
        unreadable(
            &problems,
            &[
                "bash-c",
                "rcfile",
                "bash-e",
                "sh-c",
                "plain-sh",
                "quoted",
                "job-defaults",
            ],
        );
        unreadable_file(&problems, ".github/workflows/defaults.yml");
        names(&problems, &["bash-c"], &["plain-bash"]);
        Ok(())
    }

    /// A write to a build input cannot be read, by any writer the closed world reads: a
    /// redirection, `tee`, `curl -o`, a `tar` member, `cp`, `mv`, `install` and a heredoc `cat`
    /// writes, to `Cargo.toml`, `Cargo.lock`, `rust-toolchain*`, `config.toml`, `build.rs` or a
    /// path under `crates/` or `xtask/`; nor can `curl -O`, `--remote-name`, `--output-dir` or
    /// `-K`, whose targets are not named, `tar` with no member or a flag, or a write to a hidden
    /// file (#1169 round 5 review, B5 and mutants M05, M10 and M11).
    #[test]
    fn a_write_to_a_build_input_cannot_be_read() -> Result<()> {
        let jobs = [
            ("redirect-manifest", "echo x > Cargo.toml"),
            ("append-lock", "echo x >> Cargo.lock"),
            ("toolchain-file", "echo x > rust-toolchain"),
            ("toolchain-toml", "echo x > rust-toolchain.toml"),
            ("config-toml", "echo x > config.toml"),
            ("build-script", "echo x > build.rs"),
            ("under-crates", "echo x > crates/a-lib/src/lib.rs"),
            ("under-xtask", "echo x >> xtask/src/main.rs"),
            ("tee-manifest", "echo x | tee Cargo.toml"),
            ("tee-append", "echo x | tee -a build.rs"),
            (
                "curl-output",
                "curl -sSfL -o Cargo.toml https://example.com/x",
            ),
            (
                "curl-long-output",
                "curl -sSfL --output build.rs https://example.com/x",
            ),
            ("curl-glued", "curl -sSfLobuild.rs https://example.com/x"),
            (
                "curl-remote-cluster",
                "curl -sSfLO https://example.com/Cargo.toml",
            ),
            ("curl-remote", "curl -O https://example.com/x"),
            (
                "curl-remote-long",
                "curl --remote-name https://example.com/x",
            ),
            (
                "curl-output-dir",
                "curl --output-dir crates -o x https://example.com/x",
            ),
            ("curl-config", "curl -K curl.txt https://example.com/x"),
            (
                "curl-config-long",
                "curl --config curl.txt https://example.com/x",
            ),
            ("tar-manifest", "tar xzf t.tgz Cargo.toml"),
            ("tar-build-script", "tar xzf t.tgz build.rs"),
            ("tar-path", "tar xzf t.tgz src/lib.rs"),
            ("tar-directory", "tar xzf t.tgz crates"),
            ("tar-no-members", "tar xzf t.tgz"),
            ("tar-flags", "tar xzf t.tgz -C crates tool"),
            ("unzip-manifest", "unzip t.zip Cargo.toml"),
            ("unzip-path", "unzip t.zip src/lib.rs"),
            ("unzip-no-members", "unzip t.zip"),
            ("unzip-flags", "unzip -d crates t.zip tool"),
            ("hidden-unzip", "unzip t.zip .profile"),
            ("hidden-redirect", "echo x > .npmrc"),
            ("hidden-tee", "echo x | tee .profile"),
            ("hidden-curl", "curl -sSfL -o .bashrc https://example.com/x"),
            ("hidden-tar", "tar xzf t.tgz .profile"),
            ("copy", "cp x.txt Cargo.toml"),
            ("move", "mv x.txt build.rs"),
            ("install", "install x.txt crates/a-lib/build.rs"),
        ];
        let mut all = jobs.to_vec();
        all.push((
            "writes",
            "echo x > notes.txt && curl -sSfL -o tool.tgz https://example.com/x && tar xzf \
             tool.tgz tool && unzip tool.zip tool && echo x | tee -a \"$GITHUB_OUTPUT\" && \
             cargo test -p a-lib",
        ));
        let flows = [
            workflow(&all),
            ci_file(
                ".github/workflows/heredoc.yml",
                "on: push\njobs:\n  heredoc-build-script:\n    steps:\n      - run: |\n          \
                 cat > build.rs <<'EOF'\n          fn main() {}\n          EOF\n",
            ),
        ];
        let problems = host_problems(&flows)?;
        let mut refused: Vec<&str> = jobs.iter().map(|(job, _)| *job).collect();
        refused.push("heredoc-build-script");
        unreadable(&problems, &refused);
        names(&problems, &["redirect-manifest"], &["writes"]);
        Ok(())
    }

    /// A non-local `uses:` is read only when it names an action the repository's workflows use,
    /// pinned as they pin it, and the tag-pinned CodeQL actions only in `codeql.yml`: another
    /// action, another pin, a quoted pin, a `docker://` image and a remote reusable workflow cannot
    /// be read, nor can a job `container:` or a `services:` image off the list (#1169 round 5
    /// review, B6; DEC-873 item 6).
    #[test]
    fn a_remote_action_or_image_off_the_list_cannot_be_read() -> Result<()> {
        let postgres = "postgres:17.11@sha256:d74eeac9a635390a49bc21bd49fccd973de707e2a53a76ac49b552b8712ec46f";
        let service = format!("        image: {postgres}");
        let flows = [
            yaml_lines(&[
                "on: push",
                "jobs:",
                "  unpinned:",
                "    steps:",
                "      - uses: actions/checkout@v4",
                "  other-action:",
                "    steps:",
                "      - uses: someone/action@3d3c42e5aac5ba805825da76410c181273ba90b1",
                "  other-pin:",
                "    steps:",
                "      - uses: actions/checkout@0000000000000000000000000000000000000000",
                "  docker:",
                "    steps:",
                "      - uses: docker://alpine:3.20",
                "  quoted-pin:",
                "    steps:",
                "      - uses: \"actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1\"",
                "  codeql-tag:",
                "    steps:",
                "      - uses: actions/checkout@v7",
                "  remote-workflow:",
                "    uses: someone/repo/.github/workflows/build.yml@main",
                "  container-inline:",
                "    container: node:22",
                "    steps:",
                "      - run: echo ok",
                "  container-image:",
                "    container:",
                "      image: node:22",
                "    steps:",
                "      - run: echo ok",
                "  service-image:",
                "    services:",
                "      db:",
                "        image: postgres:16",
                "    steps:",
                "      - run: echo ok",
                "  listed:",
                "    services:",
                "      db:",
                &service,
                "    steps:",
                "      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1",
                "      - uses: Swatinem/rust-cache@6323deb102c322ba6fcbdcafc7e3dddab59af2b6 # v2.9.2",
                "      - run: cargo test -p a-lib",
            ]),
            ci_file(
                ".github/workflows/codeql.yml",
                "on: push\njobs:\n  analyze:\n    steps:\n      - uses: \
                 actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1\n      - uses: \
                 github/codeql-action/init@6f2ac81f5cd81fe351a197ba0b00d91d03cd2aee\n      - uses: \
                 github/codeql-action/analyze@6f2ac81f5cd81fe351a197ba0b00d91d03cd2aee\n",
            ),
        ];
        let problems = host_problems(&flows)?;
        unreadable(
            &problems,
            &[
                "unpinned",
                "other-action",
                "other-pin",
                "docker",
                "quoted-pin",
                "codeql-tag",
                "remote-workflow",
                "container-inline",
                "container-image",
                "service-image",
            ],
        );
        names(&problems, &["unpinned"], &["listed", "analyze"]);
        Ok(())
    }

    /// In a `web` job, `npm` runs only as `npm ci` (with `--ignore-scripts` or nothing), `npm run <script>` of a script its
    /// `package.json` holds, and `npm test`, and `npx` only in the forms the repository uses:
    /// `npx`, `npm exec`, `npm pkg set`, `npm config set`, `npm install`, a missing script, a
    /// script given arguments and a `package.json` naming cargo cannot be read. Working
    /// directories are resolved first, so `web/..`, `web/../`, `../crates` and `web/../crates`
    /// are not under `web`, and neither is a step's own `working-directory: .`, while
    /// `./web/app/..` is `web` (#1169 round 5 review, B7; DEC-873 item 3).
    #[test]
    fn npm_and_npx_run_only_in_the_repository_forms() -> Result<()> {
        let job = |name: &str, dir: &str, run: &str| {
            format!(
                "  {name}:\n    defaults:\n      run:\n        working-directory: {dir}\n    \
                 steps:\n      - run: {run}\n"
            )
        };
        let refused = [
            ("npx-other", "web", "npx cowsay hi"),
            (
                "npx-other-version",
                "web",
                "npx --yes impeccable@4.2.0 detect src/",
            ),
            ("npx-playwright-test", "web", "npx playwright test"),
            ("npm-exec", "web", "npm exec cowsay"),
            ("npm-pkg-set", "web", "npm pkg set scripts.build=x"),
            (
                "npm-config-set",
                "web",
                "npm config set registry https://example.com",
            ),
            ("npm-install", "web", "npm install left-pad"),
            ("npm-ci-other-flag", "web", "npm ci --foreground-scripts"),
            ("npm-run-missing", "web", "npm run nope"),
            ("npm-run-arguments", "web", "npm run build -- --debug"),
            ("package-naming-it", "web/app", "npm run build"),
            ("dir-up", "web/..", "npm ci"),
            ("dir-up-slash", "web/../", "npm ci"),
            ("dir-crates", "../crates", "npm ci"),
            ("dir-through", "web/../crates", "npm ci"),
        ];
        let mut text = String::from("on: push\njobs:\n");
        for (name, dir, run) in refused {
            text.push_str(&job(name, dir, run));
        }
        text.push_str(
            "  step-root:\n    defaults:\n      run:\n        working-directory: web\n    steps:\n      \
             - working-directory: .\n        run: npm ci\n",
        );
        text.push_str(
            "  web-ok:\n    defaults:\n      run:\n        working-directory: web\n    steps:\n      \
             - run: npm ci\n      - run: npm ci --ignore-scripts\n      - run: npm run build\n      - run: npm run lint\n      - run: npm \
             test --if-present\n      - run: npx playwright install --with-deps --only-shell \
             chromium\n      - run: npx playwright install-deps chromium\n      - run: npx --yes \
             impeccable@4.1.0 detect src/\n      - working-directory: web\n        run: npm ci\n",
        );
        text.push_str(&job("dir-resolved", "./web/app/..", "npm ci"));
        let flows = [
            ci_file(".github/workflows/ci.yml", &text),
            ci_file(
                "web/package.json",
                "{\"scripts\": {\"build\": \"next build\", \"lint\": \"eslint\", \"test\": \"vitest \
                 run\"}}\n",
            ),
            ci_file(
                "web/app/package.json",
                "{\"scripts\": {\"build\": \"cargo build --workspace\"}}\n",
            ),
        ];
        let problems = host_problems(&flows)?;
        let mut jobs: Vec<&str> = refused.iter().map(|(name, ..)| *name).collect();
        jobs.push("step-root");
        unreadable(&problems, &jobs);
        names(&problems, &["npx-other"], &["web-ok", "dir-resolved"]);
        Ok(())
    }

    /// A listed repository script is read with every repository script it runs, by
    /// `"$(dirname "$0")/<name>"`, transitively and under the same rules: a callee that names
    /// cargo, is missing, writes a build input or runs an interpreter makes the caller unreadable,
    /// and so does a call the check cannot resolve to a file (`../`, `./`, an expansion) and an
    /// `eval`, `bash -c` or `awk` in the script itself; a clean chain, and a cycle, can be read
    /// (#1169 round 5 review, B8; DEC-873 item 2).
    #[test]
    fn a_repository_script_is_read_with_the_scripts_it_runs() -> Result<()> {
        let run = |docs_only: &str, base_ref: Option<&str>| {
            let mut flows: Vec<CiFile> = clean_scripts()
                .into_iter()
                .map(|file| {
                    if file.path == ".github/scripts/docs-only.sh" {
                        ci_file(&file.path, docs_only)
                    } else {
                        file
                    }
                })
                .collect();
            if let Some(text) = base_ref {
                flows.push(ci_file(".github/scripts/base-ref.sh", text));
            }
            flows.push(workflow(&[("docs", ".github/scripts/docs-only.sh")]));
            host_problems(&flows)
        };
        let calls = "#!/usr/bin/env bash\nset -euo pipefail\nbase=$(\"$(dirname \"$0\")/base-ref.sh\")\necho \"$base\"\n";
        let clean = "#!/usr/bin/env bash\necho main\n";
        assert_eq!(run(calls, Some(clean))?, Vec::<String>::new());
        let cycle = "#!/usr/bin/env bash\n\"$(dirname \"$0\")/docs-only.sh\"\n";
        assert_eq!(run(calls, Some(cycle))?, Vec::<String>::new());
        for (case, base_ref) in [
            (
                "callee-cargo",
                Some("#!/usr/bin/env bash\ncargo build --workspace\n"),
            ),
            ("callee-missing", None),
            (
                "callee-interpreter",
                Some("#!/usr/bin/env bash\npython3 x.py\n"),
            ),
            (
                "callee-write",
                Some("#!/usr/bin/env bash\necho x > Cargo.toml\n"),
            ),
            (
                "callee-environment",
                Some("#!/usr/bin/env bash\necho \"RUSTFLAGS=x\" >> \"$GITHUB_ENV\"\n"),
            ),
        ] {
            let problems = run(calls, base_ref)?;
            unreadable(&problems, &["docs"]);
            let named = problems
                .iter()
                .any(|p| p.contains("`.github/scripts/base-ref.sh"));
            assert!(named, "{case} names base-ref.sh: {problems:?}");
        }
        for (case, docs_only) in [
            (
                "climbing",
                "#!/usr/bin/env bash\n\"$(dirname \"$0\")/../base-ref.sh\"\n",
            ),
            ("dot-slash", "#!/usr/bin/env bash\n./helper.sh\n"),
            ("expansion", "#!/usr/bin/env bash\n\"$TOOL\" run\n"),
            ("eval", "#!/usr/bin/env bash\neval \"$X\"\n"),
            ("bash-c", "#!/usr/bin/env bash\nbash -c 'echo x'\n"),
            ("awk", "#!/usr/bin/env bash\nawk '{ print }' x.txt\n"),
        ] {
            let problems = run(docs_only, Some(clean))?;
            unreadable(&problems, &["docs"]);
            let named = problems
                .iter()
                .any(|p| p.contains("`.github/scripts/docs-only.sh"));
            assert!(named, "{case} names docs-only.sh: {problems:?}");
        }
        Ok(())
    }

    /// The two `awk` programs of `merge-approved.sh` a person has read are read only byte for
    /// byte and only in that script: the same text in another script, or one changed by a
    /// word, cannot be read (#1169 round 5 review, B8).
    #[test]
    fn the_read_script_lines_are_read_only_exactly() -> Result<()> {
        let approvals = r##"approvals=$(awk '/^[[:space:]]*(```|~~~)/ { fenced = !fenced; next } !fenced' <<<"$body" |
  sed -nE 's/^[[:space:]]*([-*][[:space:]]+)?Coordinator-approved-head:[[:space:]]*([0-9a-fA-F]{40})[[:space:]]*$/\2/p' |
  tr 'A-F' 'a-f')"##;
        let kept = r##"kept=$(awk '
  /^<!-- CURSOR_AGENT_PR_BODY_BEGIN -->$/ { inside = 1; marked = 1; next }
  /^<!-- CURSOR_AGENT_PR_BODY_END -->$/ { inside = 0; next }
  { line[++n] = $0; kept[n] = inside }
  END { for (i = 1; i <= n; i++) if (!marked || kept[i]) print line[i] }
' <<<"$body")"##;
        let run = |script: &str, text: &str| {
            let mut flows: Vec<CiFile> = clean_scripts()
                .into_iter()
                .map(|file| {
                    if file.path == script {
                        ci_file(&file.path, text)
                    } else {
                        file
                    }
                })
                .collect();
            flows.push(workflow(&[
                ("merge", ".github/scripts/merge-approved.sh \"$PR\""),
                ("checks", ".github/scripts/docs-checks.sh"),
            ]));
            host_problems(&flows)
        };
        let both = format!("#!/usr/bin/env bash\nbody=x\n{approvals}\n{kept}\necho ok\n");
        assert_eq!(
            run(".github/scripts/merge-approved.sh", &both)?,
            Vec::<String>::new()
        );
        let elsewhere = run(".github/scripts/docs-checks.sh", &both)?;
        unreadable(&elsewhere, &["checks"]);
        names(&elsewhere, &["checks"], &["merge"]);
        let changed = both.replace("print line[i]", "system(line[i])");
        let changed = run(".github/scripts/merge-approved.sh", &changed)?;
        unreadable(&changed, &["merge"]);
        Ok(())
    }

    /// A here-string feeds only `jq` and a heredoc only `cat`: a here-string into `cat` and a
    /// heredoc into `echo` cannot be read (#1169 round 5 review, mutants M03 and M20).
    #[test]
    fn a_heredoc_or_here_string_feeds_only_its_one_program() -> Result<()> {
        let flows = [yaml_lines(&[
            "on: push",
            "jobs:",
            "  here-string-cat:",
            "    steps:",
            "      - run: cat <<< \"$X\"",
            "  heredoc-echo:",
            "    steps:",
            "      - run: |",
            "          echo <<EOF",
            "          text",
            "          EOF",
            "  fed:",
            "    steps:",
            "      - run: |",
            "          more=$(jq -r '.[]' <<< \"$X\")",
            "          cat > notes.txt <<'EOF'",
            "          text",
            "          EOF",
            "          cargo test -p a-lib",
        ])];
        let problems = host_problems(&flows)?;
        unreadable(&problems, &["here-string-cat", "heredoc-echo"]);
        names(&problems, &["here-string-cat"], &["fed"]);
        Ok(())
    }

    /// `rustup` is read only as the repository runs it, `rustup show active-toolchain` and a bare
    /// `rustup toolchain install`: `rustup run`, `default`, `override`, `toolchain link`, a named
    /// install and any other form cannot be read (#1169 round 5 review, mutant M07).
    #[test]
    fn rustup_runs_only_in_the_repository_forms() -> Result<()> {
        let jobs = [
            ("run", "rustup run stable echo x"),
            ("default", "rustup default nightly"),
            ("override", "rustup override set nightly"),
            ("link", "rustup toolchain link dev /tmp/dev"),
            ("named-install", "rustup toolchain install nightly"),
            ("show-home", "rustup show home"),
            ("bare", "rustup"),
        ];
        let mut all = jobs.to_vec();
        all.push((
            "repository",
            "rustup show active-toolchain || rustup toolchain install",
        ));
        let problems = host_problems(&[workflow(&all)])?;
        unreadable(&problems, &jobs.map(|(job, _)| job));
        names(&problems, &["run"], &["repository"]);
        Ok(())
    }

    /// `--all-features` beside the compile-only form makes it no compile-only job: it resolves
    /// `live` in the runner, which is named, and the one plain compile-only job after it is still
    /// the first and passes (#1169 round 5 review, mutant M13).
    #[test]
    fn all_features_never_counts_as_the_compile_only_form() -> Result<()> {
        let flows = [workflow(&[
            (
                "check-all-features",
                "cargo check -p the-runner --features live --all-features",
            ),
            ("check-live", COMPILE_ONLY),
        ])];
        let problems = check(&live_policy(), with_runner(vec![]), &flows, by_flags)?;
        let resolves = problems
            .iter()
            .any(|p| p.contains("`check-all-features`") && p.contains("resolves `live`"));
        assert!(resolves, "the all-features job resolves live: {problems:?}");
        names(&problems, &["check-all-features"], &["check-live"]);
        Ok(())
    }

    /// `sudo install` is read only into exactly `/usr/local/bin/`: a sibling such as
    /// `/usr/local/bin2/`, a directory below it, a path that climbs out of it and a name sharing
    /// its prefix cannot be read (#1169 round 5 review, mutant M18).
    #[test]
    fn sudo_install_writes_only_into_usr_local_bin() -> Result<()> {
        let jobs = [
            ("sibling", "sudo install tool /usr/local/bin2/"),
            ("below", "sudo install tool /usr/local/bin/sub/"),
            ("climbing", "sudo install tool /usr/local/bin/../lib/"),
            ("prefix", "sudo install tool /usr/local/binx"),
        ];
        let mut all = jobs.to_vec();
        all.push(("listed", "sudo install tool /usr/local/bin/"));
        let problems = host_problems(&[workflow(&all)])?;
        unreadable(&problems, &jobs.map(|(job, _)| job));
        names(&problems, &["sibling"], &["listed"]);
        Ok(())
    }

    /// `--manifest-path`, in either spelling and on either side of `-p`, makes the build select
    /// every member even beside a `-p` naming another crate, so it holds the live-only member
    /// (#1169 round 5 review, mutant M19).
    #[test]
    fn a_manifest_path_beside_a_package_selects_every_member() -> Result<()> {
        let flows = [workflow(&[
            (
                "after-package",
                "cargo test -p a-lib --manifest-path crates/rh-host/Cargo.toml",
            ),
            (
                "glued-after-package",
                "cargo test -p a-lib --manifest-path=crates/rh-host/Cargo.toml",
            ),
            (
                "before-package",
                "cargo test --manifest-path crates/rh-host/Cargo.toml -p a-lib",
            ),
            ("lib-tests", "cargo test -p a-lib"),
        ])];
        let problems = host_problems(&flows)?;
        judged_with_host(
            &problems,
            &["after-package", "glued-after-package", "before-package"],
        );
        names(&problems, &["after-package"], &["lib-tests"]);
        Ok(())
    }

    /// A flow sequence under `jobs:` is read only when it is flat: one that holds a `:`, a nested
    /// `[`, `{` or `]`, or an `&`, `*` or `!`, even inside a quoted scalar, cannot be read. One
    /// case for each character, so dropping any one from the rule is caught (#1169 round 3
    /// review, bypass 7).
    #[test]
    fn a_flow_sequence_that_is_not_flat_cannot_be_read() -> Result<()> {
        let cases = [
            ("pair", "[a: b]"),
            ("nested-sequence", "[a, [b]]"),
            ("nested-mapping", "[a, {b: c}]"),
            ("quoted-colon", "[\"a:b\"]"),
            ("bare-brace", "[a, {b}]"),
            ("quoted-open", "[\"a[\"]"),
            ("quoted-close", "[\"a]\"]"),
            ("alias-item", "[*a]"),
            ("anchor-item", "[&a b]"),
            ("tagged-item", "[!!str a]"),
        ];
        let mut text = String::from("on: push\njobs:\n  setup:\n    steps:\n      - run: echo\n");
        for (job, flow) in cases {
            text.push_str(&format!(
                "  {job}:\n    needs: {flow}\n    steps:\n      - run: echo\n"
            ));
        }
        text.push_str("  lib-tests:\n    needs: [setup]\n    steps:\n      - run: echo\n");
        let problems = host_problems(&[ci_file(".github/workflows/ci.yml", &text)])?;
        unreadable(&problems, &cases.map(|(job, _)| job));
        names(&problems, &["pair"], &["lib-tests", "setup"]);
        Ok(())
    }

    /// A resolve that fails, or an invocation word the shell expands, is a problem naming the job
    /// rather than an abort, and so is a default build that cannot be resolved (DEC-868 item 3).
    #[test]
    fn a_job_that_cannot_be_resolved_fails_closed() -> Result<()> {
        let flows = [workflow(&[
            ("broken", "cargo test --features broken"),
            ("expands", "cargo build $FLAGS"),
            ("plain", "cargo test"),
        ])];
        let meta = workspace(live_workspace());
        let problems = resolved_live_problems(&live_policy(), &meta, &flows, &|w| {
            if w.iter().any(|word| word == "broken") {
                bail!("cargo metadata failed")
            }
            Ok(three(&[]))
        })?;
        names(&problems, &["broken", "expands"], &["plain"]);
        let default = resolved_live_problems(&live_policy(), &meta, &[], &|_| bail!("no resolve"))?;
        assert_ne!(default, Vec::<String>::new());
        Ok(())
    }

    /// The repository as it stands: cargo's resolve of the default build holds every workspace
    /// member, the check asks it for `ci.yml`'s `cargo xtask ci lint` (one of the jobs DEC-871 split
    /// `ci fast` into), and nothing resolves `live`.
    #[test]
    fn the_repository_resolves_no_live_build() -> Result<()> {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
        let meta = metadata_in(&root)?;
        let ids: BTreeSet<String> = cargo_resolve(&root, &[])?
            .nodes
            .into_iter()
            .map(|node| node.id)
            .collect();
        assert!(meta.workspace_members.iter().all(|m| ids.contains(m)) && !ids.is_empty());
        let policy: Layers = toml::from_str(&fs::read_to_string(root.join("xtask/layers.toml"))?)?;
        let asked = RefCell::new(Vec::new());
        let problems = resolved_live_problems(&policy, &meta, &ci_files(&root)?, &|w| {
            asked.borrow_mut().push(w.to_vec());
            cargo_resolve(&root, w)
        })?;
        assert_eq!(problems, Vec::<String>::new());
        assert!(asked.into_inner().contains(&words("xtask ci lint")));
        Ok(())
    }

    /// Each way a line can build or run `live` while looking like the compile-only form, or
    /// without naming `live` the plain way, is refused once, naming the file and line (#738
    /// review, finding 1): a second command after `&&`, `||`, `;` or `|` is judged on its own; a
    /// `<crate>/live` or `<crate>?/live` feature; a list split on spaces; `-Flive`; a feature list
    /// the shell expands (`$` or a backtick), which cannot be read; and `--cfg feature="live"`,
    /// which sets the feature without `--features`. A flag right after a list, a lone opening
    /// quote, `--all` and `--workspace` are read too, and a quoted list ends at its closing quote,
    /// so a flag inside it is not read as a feature (#738's mutants).
    ///
    /// A command is read whole, not a physical line at a time (#738 review, second round): a
    /// backslash continuation, or a YAML folded `>` scalar, that carries `--features live` on a
    /// later line is refused; so is `--cfg feature = "live"` with spaces or tabs around the
    /// `=`, in a command, `RUSTFLAGS` or `rustflags`; and so is a cargo command that takes
    /// arguments from a variable, `${...}`, `$(...)` or a backtick (`cargo build $FLAGS`), which
    /// cannot be read. A cargo command in a CI file is
    /// read word by word. Only the separators `|`, `;`, `&&`, `||` and a single `&` end its
    /// words, and a cargo command after one is judged on its own. A redirection (`>`, `>>`,
    /// `2>`, `<`, `2>&1`, `>/dev/null`, `&>`) does not end them: the operator and its one target
    /// word are skipped and the words after it are still checked. A `$` or backtick is allowed
    /// only inside a redirect target word, so `cargo xtask ci mutants --plan >> "$GITHUB_OUTPUT"`
    /// and `cargo build 2> "$LOG" -p x` are allowed, and any other word with one is refused,
    /// because a variable can carry a `--features` or `--cfg` flag past a line-based scan: even
    /// `--target $TARGET`, `--target "$TARGET"`, `--target ${TARGET}` and `> out $FLAGS` are
    /// refused (the coordinator's rulings under DEC-176: they only refuse more).
    ///
    /// The forms #738 handles, pinned so none can be dropped (#738 review, third round): every
    /// redirection form skips just its one target (`>|`, `1>`, `2>>`, `&>>`, `>&`, `<<<`, `<>`,
    /// `>out`, `2>&-`, `>&2`, and a here-doc's `<<EOF`), and a here-doc's body lines are read as
    /// commands; a command after a newline in a `run: |` block, `|&`, `(`, `{`, `!`, `if`, `then`,
    /// `do` or `else` is judged on its own; a cargo command wrapped in `env`, `$(...)`, a backtick
    /// or `bash -c "..."` is read, and one `xargs` feeds cannot be; every `-p` is read; `cargo` is
    /// also named by its path; a cargo configuration array is read item by item; and `deploy/`'s
    /// scripts are checked like CI's. A wrapper over a cargo command without `live`, and a
    /// here-doc without cargo, stay allowed.
    ///
    /// The live-token backstop (#738 review, fourth and fifth rounds, the coordinator's rulings
    /// under DEC-176): beside the word scan, every word of every file the check reads that is not
    /// in a comment, a YAML scalar value included, is refused when its item list holds the token
    /// `live`. The word is read lexed, after its quotes and backslashes are removed (`l\ive`,
    /// `li"ve"`), and a substitution's text is read by the same backstop. Items split on `,`,
    /// `=`, `/`, `?`, whitespace and quotes, and match `live` exactly but in any case, so
    /// `liveness` is another item and `the-runner/live` and `the-runner?/live` hold it. In an
    /// item of the form `-<letters>F<rest>`, a short-flag cluster such as `-qFlive`, the part
    /// after the first `F` is read as an item list too. The one exemption is per word and per
    /// command, never per line: only the feature list of the one allowed compile-only command is
    /// exempt, so another command on its line (`&& make FEATURES=live`) is still read.
    ///
    /// A command whose command word holds a `$` or a backtick (`$c`, `"${CARGO:-cargo}"`,
    /// `$(which cargo)`) may be cargo, so its other words that hold a `$` or a backtick cannot be
    /// read and are refused (`--features $A$B`, `$'\x6cive'`, `$(echo li)ve`); so are the lines
    /// of a here-doc fed to `sh`. This closes what a cargo-word scan cannot see: `-F=live`, a
    /// cluster, a command named through a variable, a `cargo-<tool>` binary, a `with:` input,
    /// `make FEATURES=live`, `LIVE`, and an assignment such as `FLAGS="--features live"`, which is
    /// refused on its own line beside the command that expands it. A quoted list holding
    /// `--features=live` is refused with it. A line is refused once, however many of its words
    /// hold the token. The pins that need no `cargo` word are listed apart from those with one.
    ///
    /// The cargo-word rule closes what a known non-executing command can still run (`awk`'s
    /// `system` or `getline`, `sed`'s `e` flag, a `git -c alias.x=!…`, `tee >(sh)`, a script
    /// written and then run, a command held in a scalar; the coordinator's tenth-round ruling
    /// under DEC-176). In every position, whatever the command, a word, quoted or not, holding
    /// the token `cargo` (a run of letters, digits, `_`, `-` and `.` that is `cargo`, so
    /// `!cargo` holds it and `.cargo` and `cargo-nextest` do not) is refused when it also holds
    /// a `$`, a backtick or a `%`
    /// format directive; when it holds `--all-features`; or when it holds `--features` or `-F`
    /// whose value in the same word is not a complete literal of `[a-z0-9_,-]` without the
    /// token `live` (cut off by a closing quote, empty, or followed by an expansion). A script
    /// fetched or written at run time (`curl … | sh`, a generated file) cannot be read by a
    /// static scan; the cargo-word rule is what leaves such a script no way to carry a computed
    /// feature, and the live-token backstop no way to carry `live` itself.
    ///
    /// The final round (the coordinator's eleventh-round rulings under DEC-176). The value rule
    /// applies to every feature flag, with or
    /// without `cargo`: `--features`, `--features=`, `FEATURES=` and `--all-features` are feature
    /// flags in any word, and `-F` only in a command whose command word is `cargo` or may be
    /// cargo (it holds `$`, a backtick or `${{`, or is a whole-array expansion), or in a re-read
    /// word holding the token `cargo`, so `awk -F:` and `gh api -F owner="$o"` are no feature
    /// flags. A YAML `with:` value has no command word, so it may be cargo: `-F` and a short-flag
    /// cluster holding `F` (`-qF…`) are feature flags there, while `run:` values and scripts keep
    /// the rule above. Outside the one compile-only form, `--all-features` is refused, and so is
    /// a value that is not a complete literal of `[a-z0-9_,-]` without the token `live`, which
    /// any value holding `$`, a backtick or `${{` is not. Out of reach: Rust sources (`xtask/`,
    /// `build.rs`), which code review and the layers check cover, and scripts that exist only at
    /// run time. Where a word is read as a command is pinned by
    /// [`commands_are_read_fail_closed_where_a_word_may_execute`], arrays by
    /// [`array_expansions_are_read_through_their_definitions`] (X1 tests correction 5).
    ///
    /// The backstop's match ignores case, so a bare `LIVE` or `Live` word is refused in a command
    /// without `cargo`, and an empty feature value (`--features ""`, `--features=` with nothing
    /// after it) is no complete literal, so it is refused (X1 tests correction 6, #923 review).
    ///
    /// A command is compile-only only when its subcommand, the word right after its cargo word
    /// and before any `--`, is `check` (X1 tests correction 8, #923 review): a `cargo check` or a
    /// `check` after `--`, which go to the program `run` or `test` builds, and a `check` that is
    /// the value of an option before the subcommand (`cargo --config check run`) leave the command
    /// a build, so its `live` is refused, once, at its line. The compile-only form CI runs stays
    /// allowed.
    #[test]
    fn the_backstop_and_the_feature_value_rules_refuse_ci_bypasses() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let allowed = [
            "cargo check -p the-runner -Flive",
            "cargo check -p the-runner --features the-runner/live",
            "cargo check -p the-runner --features 'other live'",
            "cargo check -p the-runner --features \"other\" --target x86_64-unknown-linux-gnu",
            "            cargo xtask ci mutants --plan >> \"$GITHUB_OUTPUT\"",
            "cargo build -p x 2> \"$LOG\"",
            "cargo build -p a-lib < \"$IN\" | tee \"$LOG\"",
            "cargo build 2> \"$LOG\" -p x",
            "env RUST_LOG=info cargo test -p x",
            "bash -c \"cargo test -p x\"",
            "cargo build --features paper,sim",
            "echo \"cargo test -p x\"",
            "      - run: cargo check -p the-runner --features live",
            "      - run: cargo check --locked -p the-runner --features=live",
        ];
        for line in allowed {
            let files = [ci_file(".github/workflows/ci.yml", line)];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{line}"
            );
        }
        let refused = [
            "cargo check -p the-runner --features live && cargo run -p the-runner --features live",
            "cargo check -p the-runner --features live || cargo build -p the-runner -F live",
            "cargo check -p the-runner --features live; cargo test -p the-runner --features live",
            "cargo check -p the-runner --features live | cargo run -p the-runner --features=live",
            "cargo run -p a-lib --features the-runner/live",
            "cargo check -p a-lib --features the-runner?/live",
            "cargo build -p the-runner --features \"other live\"",
            "cargo build -p the-runner -Flive",
            "cargo check -p the-runner --features $FEATURES",
            "cargo check -p the-runner --features `cat features.txt`",
            "RUSTFLAGS=\"--cfg feature=\\\"live\\\"\" cargo build -p the-runner",
            "cargo rustc -p the-runner -- --cfg 'feature=\"live\"'",
            "rustflags = [\"--cfg\", 'feature=\"live\"']",
            "ship = \"run -p the-runner --features live\"",
            "cargo build -p the-runner --features other -F live",
            "cargo build -p the-runner --features \" live\"",
            "cargo check -p the-runner --all --features live",
            "cargo check -p the-runner --workspace --features live",
            "ship = [\"run\", \"-p\", \"the-runner\", \"--features\", \"live\"]",
        ];
        for line in refused {
            let files = [ci_file(".cargo/config.toml", &format!("[alias]\n{line}\n"))];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{line}: {problems:?}");
            assert!(
                problems[0].contains(".cargo/config.toml:2"),
                "names the file and line: {problems:?}"
            );
        }
        let refused_across_lines = [
            (
                ".github/scripts/build.sh",
                "set -e\ncargo build --release \\\n  --features live\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo build -p the-runner \\\n  --features \\\n  live\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo run -p the-runner \\\n  -F live\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - run: |\n      cargo build --release \\\n        --features live\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - run: >\n      cargo build --release\n      --features live\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - run: >-\n      cargo test -p the-runner\n      --features other,live\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - run: cargo build -p the-runner\n      --features live\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo build -p the-runner $EXTRA_ARGS\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo build -p the-runner \"$@\"\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo build -p the-runner `cat flags.txt`\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo build -p the-runner $(cat flags.txt)\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo build -p x > out \\\n  $FLAGS\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo check -p the-runner --target \"$TARGET\"\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo check -p the-runner --target ${TARGET}\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo check -p the-runner --features \"other\" --target $TARGET\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncargo build -p x <<EOF $F\nhello\nEOF\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncat <<EOF\ncargo build --features live\nEOF\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - run: |\n      cargo check -p the-runner --features live\n      cargo build $F\n",
            ),
            ("deploy/run.sh", "set -e\ncargo build --features live\n"),
        ];
        for (path, text) in refused_across_lines {
            let files = [ci_file(path, text)];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{text}: {problems:?}");
            assert!(problems[0].contains(path), "names the file: {problems:?}");
        }
        let refused_by_words_before_an_operator = [
            "cargo build $FLAGS >> out",
            "cargo build --target $T | tee log",
            "cargo build -p a-lib $FLAGS 2> \"$LOG\"",
            "cargo build -p a-lib --target \"$T\" < in",
            "cargo build ; cargo build --features live",
            "cargo build -p a-lib > \"$OUT\" ; cargo run -p the-runner --features live",
            "cargo check -p the-runner --features live && cargo build -p the-runner $FLAGS",
            "cargo check -p the-runner --features live ; cargo build -p the-runner $FLAGS",
            "cargo build -p a-lib || cargo test -p the-runner --features live",
            "cargo build -p a-lib >> \"$OUT\" && cargo build -p the-runner --features live",
            "cargo build -p a-lib > out $FLAGS",
            "cargo build 2>&1 $FLAGS",
            "cargo build < in --target \"$T\"",
            "cargo build >/dev/null $(cat f)",
            "cargo build & cargo build -p the-runner --features live",
            "cargo build -p a-lib &> out $FLAGS",
            "cargo build -p x >| out $F",
            "cargo build -p x 1> out $F",
            "cargo build -p x 2>> out $F",
            "cargo build -p x &>> out $F",
            "cargo build -p x >& out $F",
            "cargo build -p x <<< in $F",
            "cargo build -p x <> f $F",
            "cargo build -p x >out $F",
            "cargo build -p x 2>&- $F",
            "cargo build -p x >&2 $F",
            "cargo build -p x > $X --features live",
            "true |& cargo build $F",
            "( cargo build $F )",
            "{ cargo build $F; }",
            "! cargo build $F",
            "if cargo build $F; then",
            "if true; then cargo build $F; fi",
            "for i in 1; do cargo build $F; done",
            "if true; then :; else cargo build $F; fi",
            "env VAR=1 cargo build $F",
            "xargs cargo build",
            "echo $(cargo build --features live)",
            "echo `cargo build --features live`",
            "bash -c \"cargo build -p x $F\"",
            "cargo build -p a -p b --features live",
            "cargo check -p the-runner -p a-lib --features live",
            "/usr/bin/cargo build --features live",
            "cargo build -p a-lib --features \"other --features=live\"",
            "cargo run -F=live",
            "cargo run -qFlive",
            "cargo run -vFlive",
            "cargo build -p the-runner --features LIVE",
            "cargo build --features \"\"",
            "cargo build --features=",
            "cargo check -p the-runner --features live && make build FEATURES=live",
            "cargo check -p the-runner --features live; c=cargo; $c run -Flive",
        ];
        let refused_with_no_cargo_word = [
            "cargo-nextest nextest run --features live",
            "cargo-mutants mutants --features live",
            "make build FEATURES=live",
            "FEATURES=\"a,live\"",
            "make FEATURES=the-runner/live",
            "make FLAGS=-qFlive",
            "l\\ive",
            "--features=li\"ve\"",
            "--features $(echo live)",
            "echo LIVE",
            "echo Live",
        ];
        let refused_through_a_command_word_that_may_be_cargo = [
            "c=cargo; $c build --features live",
            "\"${CARGO:-cargo}\" build --features live",
            "$(which cargo) build --features live",
            "c=cargo; $c build --features the-runner?/live",
            "$c build -qFthe-runner/live",
            "c=cargo; A=li; B=ve; $c build --features $A$B",
            "$c build --features $'\\x6cive'",
            "$c build --features $(echo li)ve",
        ];
        let refused_by_the_cargo_word_rule = [
            "awk 'BEGIN{system(\"cargo build --features \" a b)}' a=li b=ve",
            "awk 'BEGIN{\"cargo build --features \" a b | getline}' a=li b=ve",
            "sed -e \"s/x/cargo build --features $A$B/e\"",
            "git -c \"alias.b=!cargo build --features $A$B\" b",
            "echo \"cargo build --features $A$B\" | tee >(sh)",
            "printf 'cargo build --features %s%s\\n' $A $B > x.sh; sh x.sh",
            "echo \"cargo build --features $A$B\" > x.sh; bash x.sh",
            "cmd=\"cargo build --features $A$B\"; $cmd",
            "read -r cmd <<< \"cargo build --features $A$B\"; $cmd",
        ];
        let refused_where_check_is_not_the_subcommand = [
            "cargo run -p the-runner --features live -- cargo check",
            "cargo test -p the-runner --features live -- cargo check",
            "cargo build -p the-runner --features live -- check",
            "cargo +nightly run -p the-runner --features live -- cargo check",
            "cargo --locked run -p the-runner --features live -- check",
            "cargo --locked run -p the-runner --features live -- cargo check",
            "cargo run --features live -- cargo check -p the-runner",
            "/usr/bin/cargo run -p the-runner --features live -- /usr/bin/cargo check",
            "cargo --config check run -p the-runner --features live",
        ];
        let refused_at_line_two = refused_with_no_cargo_word
            .iter()
            .chain(&refused_through_a_command_word_that_may_be_cargo)
            .chain(&refused_by_the_cargo_word_rule)
            .chain(&refused_where_check_is_not_the_subcommand);
        for line in refused_at_line_two {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{line}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{line}: {problems:?}");
            assert!(
                problems[0].contains(".github/scripts/build.sh:2"),
                "names the file and line: {problems:?}"
            );
        }
        for line in refused_by_words_before_an_operator {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{line}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{line}: {problems:?}");
            assert!(
                problems[0].contains(".github/scripts/build.sh:2"),
                "names the file and line: {problems:?}"
            );
        }
        let refused_spaced_cfg = [
            "cargo rustc -p the-runner -- --cfg 'feature = \"live\"'",
            "cargo rustc -p the-runner -- --cfg 'feature  =  \"live\"'",
            "cargo rustc -p the-runner -- --cfg \"feature =\\\"live\\\"\"",
            "RUSTFLAGS=\"--cfg feature = \\\"live\\\"\" cargo build -p the-runner",
            "RUSTFLAGS='--cfg feature =\"live\"' cargo build -p the-runner",
            "rustflags = [\"--cfg\", 'feature = \"live\"']",
            "rustflags = [\"--cfg\", \"feature = \\\"live\\\"\"]",
            "rustflags = [\"--cfg\", 'feature\t=\t\"live\"']",
        ];
        let allowed_in_a_script = [
            (
                ".github/scripts/build.sh",
                "set -e\ncat <<EOF\nno build here\nEOF\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\n# the live lane supplies its binary\ncargo build -p a-lib\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  # the live lane supplies its binary\n  - run: cargo build -p a-lib\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\ncurl -fsS http://localhost/liveness\ncargo test -p a-lib liveness\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - name: liveness\n    run: ./probe.sh --liveness\n",
            ),
            (".github/scripts/build.sh", "set -e\nawk -F: '{print $1}'\n"),
            (
                ".github/scripts/build.sh",
                "set -e\ngh api -F owner=\"$o\"\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - uses: an/action@v1\n    with:\n      key: x-${{ runner.os }}\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - uses: an/action@v1\n    with:\n      key: x-${{ runner.os }}-${{ steps.v.outputs.version }}\n",
            ),
        ];
        for (path, text) in allowed_in_a_script {
            let files = [ci_file(path, text)];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{text}"
            );
        }
        let refused_inputs_with_no_cargo_word = [
            (
                ".github/workflows/ci.yml",
                "steps:\n  - uses: an/action@v1\n    with:\n      args: --features live\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - uses: an/action@v1\n    with:\n      command: build --features live\n",
            ),
            (
                ".github/actions/build/action.yml",
                "runs:\n  using: composite\n  steps:\n    - uses: an/action@v1\n      with:\n        args: --features live\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - uses: an/action@v1\n    with:\n      args: --features the-runner/live\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - uses: an/action@v1\n    with:\n      args: -qFlive\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - uses: an/action@v1\n    with:\n      args: --features ${{ matrix.a }}${{ matrix.b }}\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - uses: an/action@v1\n    with:\n      args: build -F ${{ matrix.a }}${{ matrix.b }}\n",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - uses: an/action@v1\n    with:\n      args: -qF${{ matrix.a }}${{ matrix.b }}\n",
            ),
        ];
        for (path, text) in refused_inputs_with_no_cargo_word {
            let files = [ci_file(path, text)];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{text}: {problems:?}");
            assert!(problems[0].contains(path), "names the file: {problems:?}");
        }
        let refused_on_two_lines = [
            (
                ".github/scripts/build.sh",
                "set -e\nFLAGS=\"--features live\"\ncargo build $FLAGS\n",
                [":2", ":3"],
            ),
            (
                ".github/scripts/build.sh",
                "set -e\nFLAGS='-F live'\ncargo build -p the-runner ${FLAGS}\n",
                [":2", ":3"],
            ),
            (
                ".github/workflows/ci.yml",
                "env:\n  FLAGS: --features live\nsteps:\n  - run: cargo build $FLAGS\n",
                [":2", ":4"],
            ),
            (
                ".github/scripts/build.sh",
                "set -e\nTARGET=\"x86_64-unknown-linux-gnu --features live\"\ncargo check -p the-runner --target $TARGET\n",
                [":2", ":3"],
            ),
        ];
        for (path, text, lines) in refused_on_two_lines {
            let files = [ci_file(path, text)];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 2, "{text}: {problems:?}");
            for (problem, line) in problems.iter().zip(lines) {
                assert!(
                    problem.contains(&format!("{path}{line}")),
                    "the assignment and the expansion are each refused: {problems:?}"
                );
            }
        }
        for line in refused_spaced_cfg {
            let files = [ci_file(".cargo/config.toml", &format!("[build]\n{line}\n"))];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{line}: {problems:?}");
            assert!(
                problems[0].contains(".cargo/config.toml:2"),
                "names the file and line: {problems:?}"
            );
        }
        Ok(())
    }

    /// Where a word is read as a command fails closed (the coordinator's seventh-round ruling
    /// under DEC-176), split out of the bypass test so X1's step 3b un-ignores it (X1 tests
    /// correction 5).
    ///
    /// A known non-executing command is one of `echo`, `printf`, `cat`, `jq`, `awk`, `sed`, `grep`,
    /// `tr`, `cut`, `sort`, `uniq`, `head`, `tail`, `tee`, `wc`, `test`, `[`, `true`, `false`,
    /// `read`, `basename`, `dirname`, `date`, `mkdir`, `rm`, `cp`, `mv`, `ls`, `chmod`, `curl`,
    /// `git`, and `gh api` alone, which main's `merge-approved.sh` needs for its multi-line GraphQL
    /// query; every other command executes, any other `gh` subcommand (`gh alias set --shell`),
    /// unknown ones, `source`, `.`, `exec`, `watch`, `parallel`, every shell and every wrapper
    /// included. A quoted word holding a space, `cargo` or a `$` is re-read as a command line
    /// unless its command is known non-executing, every later stage of its pipeline is too, and it
    /// is not inside a `$( … )` `<( … )` or `>( … )` whose consumer executes (`echo "…" | sh`,
    /// `source <(echo "…")`, `tee >(sh)`); a bare assignment captures its `$( … )` and does not
    /// execute it. A here-doc's lines and a here-string's (`<<<`) target are read as commands
    /// unless their command is known non-executing, so `cat <<EOF` holding `$F` is allowed.
    /// `$(( … ))` is arithmetic and `${#x[@]}` a length, neither read as a command; `if`, `then`, `else`,
    /// `elif`, `do`, `while`, `until`, `!` and `time` are skipped when finding the command word,
    /// and the word after one is still read (`if cargo build …; then`). The lines inside a
    /// single-quoted string that spans lines are not read as commands only when its command is
    /// known non-executing and nothing pipes it onward. A word holding `${{ … }}` in command
    /// position is possibly cargo inside a `run:` value only (`run: ${{ inputs.cmd }} build $F`),
    /// and not in a job name, an `env:` value, a `with:` input or a cache key. The live-token
    /// backstop still reads every word of every line. An `awk` word holding `system(` or `getline`,
    /// a `sed` word with an `e` command or an `/e` flag, and a `git` with `-c alias.*=!` or a `!`
    /// alias make that command executing, so its words are re-read; an executing `awk` or `sed`
    /// program builds a command no static reading can follow, so it is refused outright (round
    /// eleven).
    ///
    /// The pins of `refused_only_by_reading_fail_closed` hold no `cargo` token, no `live` and no
    /// feature flag, so only this reading refuses them, never the backstop or the cargo-word rule
    /// (X1 tests correction 7, step 3b's planted bugs).
    ///
    /// A here-doc's body, or the lines of a single-quoted string that spans lines, inside a
    /// `<( … )` or `$( … )` is text only when that substitution's consumer is known non-executing
    /// or a bare assignment: fed to `bash <( … )` its lines are commands, captured by `x=$( … )`
    /// they are text (X1 tests correction 9, `read_as_text`'s consumer branch).
    #[test]
    fn commands_are_read_fail_closed_where_a_word_may_execute() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let refused_through_an_executing_command_at_line_two = [
            "echo \"cargo build --features $A$B\" | sh",
            "printf '%s' \"c=cargo; $c build --features $A$B\" | bash",
            "source <(echo \"cargo build --features $A$B\")",
            ". <(printf '%s\\n' \"cargo build --features $A$B\")",
            "sh <<< \"cargo build --features $A$B\"",
            "watch \"cargo build --features $A$B\"",
            "parallel \"cargo build --features $A$B\" ::: x",
            "frobnicate \"cargo build $F\"",
            "if cargo build --features \"$A$B\"; then",
            "gh alias set --shell x \"cargo build --features $A$B\"",
            "ssh h \"cargo build $F\"",
            "sudo sh -c \"cargo build $F\"",
            "awk 'BEGIN{system(\"c\" \"argo build --features \" a b)}' a=li b=ve",
            "echo a | sed \"s/a/c&rgo build --features $A$B/e\"",
            "git -c 'alias.b=!sh -c \"$0\"' b \"$c $A\"",
            "make build FEATURES=$A$B",
            "$C build -F \"$A$B\"",
        ];
        let refused_only_by_reading_fail_closed = [
            "awk 'BEGIN{system(c)}' c=\"$RUN\"",
            "echo \"$X\" | sed e",
            "sed 's/^/x/e' \"$F\"",
            "sh <(echo \"$C $A\")",
            "\"$(printf %s \"$C $A\")\" x",
            "while $C \"$A\"; do :; done",
            "until $C \"$A\"; do :; done",
            "! $C \"$A\"",
            "time $C \"$A\"",
            "for i in 1; do $C \"$A\"; done",
            "echo \"$C $A\" | xargs sh",
            "echo \"$C $A\" | env sh",
        ];
        for line in refused_through_an_executing_command_at_line_two
            .iter()
            .chain(&refused_only_by_reading_fail_closed)
        {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{line}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{line}: {problems:?}");
            assert!(
                problems[0].contains(".github/scripts/build.sh:2"),
                "names the file and line: {problems:?}"
            );
        }
        let here_doc_fed_to_sh = [ci_file(
            ".github/scripts/build.sh",
            "set -e\nsh <<'EOF'\nc=cargo; A=li; B=ve; $c build --features $A$B\nEOF\n",
        )];
        let problems = live_feature_problems(&policy, &meta(), &here_doc_fed_to_sh)?;
        assert_eq!(problems.len(), 1, "a here-doc fed to sh: {problems:?}");
        assert!(
            problems[0].contains(".github/scripts/build.sh:3"),
            "names the file and the here-doc's line: {problems:?}"
        );
        let allowed_in_a_script = [
            (".github/scripts/build.sh", "set -e\necho \"$a $b\"\n"),
            (
                ".github/scripts/build.sh",
                "set -e\ncat <<EOF\ncargo build $F\nEOF\n",
            ),
            (".github/scripts/build.sh", "set -e\njq -n '\n$a $b\n'\n"),
            (
                ".github/scripts/build.sh",
                "set -e\nx=$(cat <<EOF\n$C \"$A\"\nEOF\n)\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\nx=$(echo '\n$C \"$A\"\n')\n",
            ),
        ];
        for (path, text) in allowed_in_a_script {
            let files = [ci_file(path, text)];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{text}"
            );
        }
        let refused_through_an_executing_command = [
            (
                ".github/scripts/build.sh",
                "set -e\nsetsid sh <<'EOF'\ncargo build --features $A$B\nEOF\n",
                ":3",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\necho '\ncargo build $F\n' | sh\n",
                ":3",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\nbash -c '\ncargo build $F\n'\n",
                ":3",
            ),
            (
                ".github/workflows/ci.yml",
                "steps:\n  - run: ${{ inputs.cmd }} build $F\n",
                ":2",
            ),
        ];
        for (path, text, line) in refused_through_an_executing_command {
            let files = [ci_file(path, text)];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{text}: {problems:?}");
            assert!(
                problems[0].contains(&format!("{path}{line}")),
                "names the file and line: {problems:?}"
            );
        }
        Ok(())
    }

    /// `eval`, and `sh`, `bash` or `zsh` given `-c` (alone or in a short-flag cluster) or a
    /// here-string, run their argument as a command line, so one that expands (`$` or a backtick)
    /// is refused, by any path, after a keyword, and inside a re-read word (DEC-851 item 1, the
    /// coordinator's ruling under DEC-176; X1 tests correction 9). A shell given a script file,
    /// and an `eval` or `-c` whose argument expands nothing, stay allowed.
    #[test]
    fn eval_and_shells_given_an_expanding_command_line_are_refused() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let refused = [
            "eval \"$C\"",
            "eval \"$(cat x)\"",
            "sh -c \"$C\"",
            "bash <<< \"$C\"",
            "zsh -c \"$X $Y\"",
            "sh <<<\"$C\"",
            "/bin/bash -c \"$C\"",
            "bash -ec \"$C\"",
            "bash -e -c `cat x`",
            "if eval \"$C\"; then :; fi",
            "echo 'eval \"$C\"' | sh",
        ];
        for line in refused {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{line}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{line}: {problems:?}");
            assert!(
                problems[0].contains(".github/scripts/build.sh:2"),
                "names the file and line: {problems:?}"
            );
        }
        let allowed = [
            "bash .github/scripts/docs-only.sh \"$A\"",
            "sh -c 'exit 0'",
            "eval 'set -e'",
            "bash -e .github/scripts/x.sh",
        ];
        for line in allowed {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{line}\n"),
            )];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{line}"
            );
        }
        Ok(())
    }

    /// Arrays (the coordinator's eighth- and ninth-round rulings under DEC-176).
    ///
    /// Defining an array (`x=( … )`, one word) is never refused beyond the live-token backstop and
    /// the cargo-word rule, so `a=(cargo build --features "$A$B")` is refused on its own line
    /// beside `run_it "${a[@]}"`; a command word that expands a whole array (`"${x[@]}"`,
    /// `${x[*]}`) is refused when any definition of that array in the file holds `cargo` or an
    /// expansion, or the file defines no such array (eighth round). A re-read word that is exactly one whole-array expansion in argument position is
    /// read as the array's defined elements, which stay arguments of the outer command
    /// (`parse_flags "${flags[@]}"`), unless a definition of that array, `+=` appends included,
    /// holds the literal `cargo` or the token `live`, which is refused (ninth round). Split out of
    /// the bypass test so X1's step 3c un-ignores it (X1 tests correction 5).
    #[test]
    fn array_expansions_are_read_through_their_definitions() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let refused_at_line_two = [
            "x=(cargo build --features \"$A$B\"); \"${x[@]}\"",
            "x=($C build --features $A$B); \"${x[@]}\"",
            "\"${undefined[@]}\" build",
        ];
        for line in refused_at_line_two {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{line}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{line}: {problems:?}");
            assert!(
                problems[0].contains(".github/scripts/build.sh:2"),
                "names the file and line: {problems:?}"
            );
        }
        let allowed_in_a_script = [
            (
                ".github/scripts/build.sh",
                "set -e\nflags=()\nfor arg in \"$@\"; do flags+=(\"$arg\"); done\nparse_flags \"${flags[@]}\"\n",
            ),
            (
                ".github/scripts/build.sh",
                "set -e\nshards=(\"$A\" \"$A/tmp\")\n",
            ),
        ];
        for (path, text) in allowed_in_a_script {
            let files = [ci_file(path, text)];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{text}"
            );
        }
        let refused_on_two_lines = [(
            ".github/scripts/build.sh",
            "set -e\na=(cargo build --features \"$A$B\")\nrun_it \"${a[@]}\"\n",
            [":2", ":3"],
        )];
        for (path, text, lines) in refused_on_two_lines {
            let files = [ci_file(path, text)];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 2, "{text}: {problems:?}");
            for (problem, line) in problems.iter().zip(lines) {
                assert!(
                    problem.contains(&format!("{path}{line}")),
                    "the assignment and the expansion are each refused: {problems:?}"
                );
            }
        }
        Ok(())
    }

    /// Every definition of an array is read, and both whole-array forms are (X1 tests correction
    /// 12, after #979's planted bug A4; DEC-851 item 2). An `x+=( … )` append counts as a
    /// definition of `x`, so `x=(echo)` then `x+=(cargo build --features live)` is refused at
    /// the expansion, not only at the append. An array `mapfile` sets beside an `x=( … )` cannot
    /// be read, so its whole-array command word is refused. The token `live` in a definition
    /// refuses the expansion as a command word and inside a re-read word, as `cargo` does. And
    /// `${x[*]}` is read as `${x[@]}` is, for a defined and an undefined array.
    #[test]
    fn every_array_definition_and_both_whole_array_forms_are_read() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let refused = [
            (
                "x=(echo)\nx+=(cargo build --features live)\n\"${x[@]}\"",
                &[3, 4][..],
            ),
            ("x=(echo)\nmapfile -t x < f\n\"${x[@]}\"", &[4][..]),
            ("x=(echo)\nx+=(--features live)\n\"${x[@]}\"", &[4][..]),
            ("x=(--features live)\nrun_it \"${x[@]}\"", &[3][..]),
            ("x=(cargo build)\n\"${x[*]}\"", &[3][..]),
            ("x=(cargo build)\nrun_it \"${x[*]}\"", &[3][..]),
            ("\"${undefined[*]}\" build", &[2][..]),
        ];
        for (text, lines) in refused {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{text}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            let expected: Vec<String> = lines
                .iter()
                .map(|line| format!(".github/scripts/build.sh:{line}:"))
                .collect();
            assert_eq!(problems.len(), expected.len(), "{text}: {problems:?}");
            for (problem, at) in problems.iter().zip(&expected) {
                assert!(problem.starts_with(at), "{text}: {problems:?}");
            }
        }
        let allowed = [
            "x=(echo)\nx+=(hi)\n\"${x[@]}\"",
            "x=(echo hi)\n\"${x[*]}\"",
            "mapfile -t x < f\nrun_it \"${x[@]}\"",
        ];
        for text in allowed {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{text}\n"),
            )];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{text}"
            );
        }
        Ok(())
    }

    /// A command word that is solely the expansion of a scalar variable (`$C`, `"$C"`, `${C}`)
    /// the file assigns (`C=…`, `C+=…`) is read through those definitions, concatenated in order,
    /// as arrays are: it is refused when that value builds or runs `live`, and when a definition
    /// cannot be read statically because it expands (DEC-851 item 2; X1 tests correction 10). A
    /// quoted word a shell runs (`echo "$C" | sh`) is read through the same definitions. A
    /// variable `read` sets is a definition whose value cannot be read, so it is refused as a
    /// command word and allowed as an argument (the coordinator's ruling on #970). `export`,
    /// `declare`, `local`, `readonly`, `typeset` and `printf -v` define too: a readable value is
    /// read through and an unreadable one is unreadable, and a wrapper before a bare variable
    /// command word (`env $C`, `sudo $C`, `xargs $C`) is read as `$C` alone (#970's review; X1
    /// tests correction 11).
    /// An expansion of a variable the file never assigns, `"$@"`, a positional parameter or an
    /// environment input, is not refused by this rule, and a clean definition stays allowed.
    #[test]
    fn variable_command_words_are_read_through_their_definitions() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let built_across_lines =
            "C=ca; C+=rgo; C+=\" build -\"; C+=\"-feat\"; C+=\"ures l\"; C+=ive";
        let refused_at_the_expansion = [
            format!("{built_across_lines}\n$C"),
            format!("{built_across_lines}\n\"$C\""),
            format!("{built_across_lines}\n${{C}} -p the-runner"),
            "C=$(cat cmd.txt)\n$C".to_owned(),
            "C=echo\nC+=\" $X\"\n\"$C\"".to_owned(),
            "read -r C < f\n$C".to_owned(),
            "while read -r C; do $C; done < f".to_owned(),
            format!("{built_across_lines}\necho \"$C\" | sh"),
            "export C=$(cat f)\n$C".to_owned(),
            "declare C=$(cat f)\n$C".to_owned(),
            "local C=$(cat f)\n$C".to_owned(),
            "readonly C=$(cat f)\n$C".to_owned(),
            "typeset C=$(cat f)\n$C".to_owned(),
            "printf -v C %s \"$X\"\n$C".to_owned(),
            format!("export {built_across_lines}\n$C"),
            format!("declare -x {built_across_lines}\n$C"),
            "C=$(cat f)\nenv $C".to_owned(),
            "C=$(cat f)\nsudo $C".to_owned(),
            "C=$(cat f)\nxargs $C".to_owned(),
        ];
        for text in refused_at_the_expansion {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{text}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{text}: {problems:?}");
            assert!(
                problems[0].contains(&format!(
                    ".github/scripts/build.sh:{}",
                    text.lines().count().saturating_add(1)
                )),
                "names the file and the expansion's line: {problems:?}"
            );
        }
        let allowed = [
            "\"$@\"",
            "C=echo; $C hi",
            "C=echo\nC+=\" hi\"\n$C",
            "read -r C < f\necho \"$C\"",
            "export C=echo\n$C hi",
            "export PATH=\"$PATH:/opt/bin\"\necho \"$PATH\"",
            "C=echo\nenv $C hi",
        ];
        for text in allowed {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{text}\n"),
            )];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{text}"
            );
        }
        Ok(())
    }

    /// DEC-851 item 1 reads through a wrapper: `env` (with `-i`, `-u X` and `VAR=val`),
    /// `command`, `exec`, `xargs`, `sudo` (each with its options), `nice`, `nohup` and
    /// `timeout N` are skipped to find the command that runs an expanding command line, and `.`
    /// or `source` of a process substitution or a here-string that expands is refused too (the
    /// coordinator's ruling on #962's review, under DEC-176; X1 tests correction 10). A `{` is
    /// skipped like a keyword, and `dash`, `ksh` and `mksh` are shells too (#969's review).
    /// `stdbuf` (with its options), `builtin` and `time` are wrappers too, and `env --`,
    /// `exec -a name`, a bare `nice` and a `-lc` cluster are pinned (#970's review; X1 tests
    /// correction 11). A wrapped script, and `.` of a file path built by a substitution, stay
    /// allowed.
    #[test]
    fn wrapped_shells_and_sourced_expansions_are_refused() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let refused = [
            "env bash -c \"$C\"",
            "command sh -c \"$C\"",
            "exec sh -c \"$C\"",
            "xargs sh -c \"$C\"",
            "sudo sh -c \"$C\"",
            ". <(echo \"$C\")",
            "source /dev/stdin <<< \"$C\"",
            "env -i PATH=/bin bash -c \"$C\"",
            "env -u X sh -c \"$C\"",
            "xargs -r -n 1 sh -c \"$C\"",
            "sudo -u root -E sh -c \"$C\"",
            "nice -n 5 bash -c \"$C\"",
            "nohup sh -c \"$C\"",
            "timeout 5 bash -c \"$C\"",
            "command eval \"$C\"",
            "source <(echo \"$C\")",
            "{ eval \"$C\"; }",
            "{ bash -c \"$C\"; }",
            "dash -c \"$C\"",
            "ksh -c \"$C\"",
            "mksh -c \"$C\"",
            "/bin/dash -c \"$C\"",
            "stdbuf -o0 sh -c \"$C\"",
            "builtin eval \"$C\"",
            "time sh -c \"$C\"",
            "env -- bash -c \"$C\"",
            "exec -a name sh -c \"$C\"",
            "nice sh -c \"$C\"",
            "bash -lc \"$C\"",
        ];
        for line in refused {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{line}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{line}: {problems:?}");
            assert!(
                problems[0].contains(".github/scripts/build.sh:2"),
                "names the file and line: {problems:?}"
            );
        }
        let allowed = [
            "sudo -u x ./script.sh",
            ". \"$(dirname \"${BASH_SOURCE[0]}\")/lib.sh\"",
            "source ./lib.sh",
            "env FOO=1 bash script.sh \"$A\"",
            "timeout 5 ./x.sh \"$A\"",
            "xargs -r sudo rm -f",
            "stdbuf -o0 ./x.sh \"$A\"",
        ];
        for line in allowed {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{line}\n"),
            )];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{line}"
            );
        }
        Ok(())
    }

    /// A marked crate that is not a workspace member is no runner, so even the compile-only form
    /// naming it is refused, beside the membership problem (#738 review, finding 2: the
    /// membership test of the runner).
    #[test]
    fn a_marked_crate_outside_the_workspace_compiles_nothing() -> Result<()> {
        let crates = vec![member("a-lib", &[]), member("a-tool", &[])];
        let files = [ci_file(
            ".github/workflows/ci.yml",
            "      - run: cargo check -p the-runner --features live",
        )];
        let problems = live_feature_problems(&live_policy(), &workspace(crates), &files)?;
        assert_eq!(problems.len(), 2, "{problems:?}");
        assert!(
            problems
                .iter()
                .any(|p| p.contains(".github/workflows/ci.yml:1")),
            "the compile-only line is refused: {problems:?}"
        );
        Ok(())
    }

    /// Only the runner's own features are read for a feature that turns `live` on: another
    /// crate's feature naming its own `live` is not counted twice beside its declaration, and a
    /// runner feature that enables something other than `live` is no problem (#738 review,
    /// finding 2: the two conditions of the runner's own feature check).
    #[test]
    fn only_the_runner_s_own_features_turn_its_live_on() -> Result<()> {
        let policy = live_policy();
        let crates = vec![
            with_features(member(RUNNER, &[]), &[("live", &[])]),
            with_features(member("a-lib", &[]), &[("live", &[]), ("go", &["live"])]),
        ];
        let problems = live_feature_problems(&policy, &workspace(crates), &[])?;
        assert_eq!(problems.len(), 1, "only the declaration: {problems:?}");
        let crates = vec![with_features(
            member(RUNNER, &[]),
            &[("live", &["a-tool/fast"]), ("other", &["a-tool/fast"])],
        )];
        assert_eq!(
            live_feature_problems(&policy, &workspace(crates), &[])?,
            Vec::<String>::new(),
            "runner features that enable something else"
        );
        Ok(())
    }

    /// The files the check reads are every file that decides a build: workflows (`.yml` and
    /// `.yaml`), scripts, composite actions under `.github/actions`, `deploy/`'s shell scripts
    /// (the demo host's runbook, DEC-822), and `.cargo/config.toml` (aliases and `rustflags`); a
    /// repository without the optional ones reads the rest (#738 review, finding 4).
    #[test]
    fn ci_files_reads_every_file_that_decides_a_build() -> Result<()> {
        let root = env::temp_dir().join(format!("mandate-xtask-ci-files-{}", std::process::id()));
        if root.exists() {
            fs::remove_dir_all(&root)?;
        }
        let write = |path: &str| -> Result<()> {
            let file = root.join(path);
            if let Some(dir) = file.parent() {
                fs::create_dir_all(dir)?;
            }
            fs::write(file, "x\n")?;
            Ok(())
        };
        write(".github/workflows/a.yml")?;
        let only_workflows = ci_files(&root)
            .map(|files| files.into_iter().map(|file| file.path).collect::<Vec<_>>());
        for path in [
            ".github/workflows/b.yaml",
            ".github/scripts/c.sh",
            ".github/actions/d/action.yml",
            ".github/actions/e/action.yaml",
            ".cargo/config.toml",
            ".github/pull_request_template.md",
            "deploy/f.sh",
            "deploy/README.md",
        ] {
            write(path)?;
        }
        let mut read: Vec<String> = ci_files(&root)?.into_iter().map(|file| file.path).collect();
        fs::remove_dir_all(&root).ok();
        read.sort();
        assert_eq!(
            only_workflows?,
            [".github/workflows/a.yml"],
            "the optional directories may be absent"
        );
        assert_eq!(
            read,
            [
                ".cargo/config.toml",
                ".github/actions/d/action.yml",
                ".github/actions/e/action.yaml",
                ".github/scripts/c.sh",
                ".github/workflows/a.yml",
                ".github/workflows/b.yaml",
                "deploy/f.sh",
            ]
        );
        Ok(())
    }

    /// The build files the check reads (the coordinator's eleventh-round ruling under DEC-176):
    /// `Makefile`, `*.mk`, `justfile`, `Dockerfile*` and `docker-compose*.yml` anywhere in the
    /// repository, beside every file [`ci_files_reads_every_file_that_decides_a_build`] names.
    /// Split out so X1's step 3c un-ignores it (X1 tests correction 5).
    #[test]
    fn ci_files_reads_the_build_files_anywhere_in_the_repository() -> Result<()> {
        let root =
            env::temp_dir().join(format!("mandate-xtask-build-files-{}", std::process::id()));
        if root.exists() {
            fs::remove_dir_all(&root)?;
        }
        let write = |path: &str| -> Result<()> {
            let file = root.join(path);
            if let Some(dir) = file.parent() {
                fs::create_dir_all(dir)?;
            }
            fs::write(file, "x\n")?;
            Ok(())
        };
        write(".github/workflows/a.yml")?;
        let only_workflows = ci_files(&root)
            .map(|files| files.into_iter().map(|file| file.path).collect::<Vec<_>>());
        for path in [
            ".github/workflows/b.yaml",
            ".github/scripts/c.sh",
            ".github/actions/d/action.yml",
            ".github/actions/e/action.yaml",
            ".cargo/config.toml",
            ".github/pull_request_template.md",
            "deploy/f.sh",
            "deploy/README.md",
            "Makefile",
            "tools/build.mk",
            "justfile",
            "docker/Dockerfile.ci",
            "docker-compose.ci.yml",
        ] {
            write(path)?;
        }
        let mut read: Vec<String> = ci_files(&root)?.into_iter().map(|file| file.path).collect();
        fs::remove_dir_all(&root).ok();
        read.sort();
        assert_eq!(
            only_workflows?,
            [".github/workflows/a.yml"],
            "the optional directories may be absent"
        );
        assert_eq!(
            read,
            [
                ".cargo/config.toml",
                ".github/actions/d/action.yml",
                ".github/actions/e/action.yaml",
                ".github/scripts/c.sh",
                ".github/workflows/a.yml",
                ".github/workflows/b.yaml",
                "Makefile",
                "deploy/f.sh",
                "docker-compose.ci.yml",
                "docker/Dockerfile.ci",
                "justfile",
                "tools/build.mk",
            ]
        );
        Ok(())
    }

    /// A fixture repository under the temporary directory, named for `name`, with `files` written
    /// as `(path, text)`, removed first if a run left it behind.
    fn fixture_repository(name: &str, files: &[(&str, &str)]) -> Result<PathBuf> {
        let root = env::temp_dir().join(format!("mandate-xtask-{name}-{}", std::process::id()));
        if root.exists() {
            fs::remove_dir_all(&root)?;
        }
        for (path, text) in files {
            let file = root.join(path);
            if let Some(dir) = file.parent() {
                fs::create_dir_all(dir)?;
            }
            fs::write(file, text)?;
        }
        Ok(root)
    }

    /// Every build-file name the check reads is judged, not only listed (X1 tests correction 12,
    /// after #979): `makefile`, `GNUmakefile`, `Justfile` and a `docker-compose*.yaml`, each
    /// holding a live build, are each refused at their own path and line.
    #[test]
    fn every_build_file_name_is_judged() -> Result<()> {
        let build = "build:\n\tcargo build --features live\n";
        let paths = [
            "makefile",
            "tools/GNUmakefile",
            "Justfile",
            "docker/docker-compose.ci.yaml",
        ];
        let files: Vec<(&str, &str)> = paths.iter().map(|path| (*path, build)).collect();
        let root = fixture_repository("build-file-names", &files)?;
        let read = ci_files(&root);
        fs::remove_dir_all(&root).ok();
        let problems = live_feature_problems(&live_policy(), &workspace(live_workspace()), &read?)?;
        assert_eq!(problems.len(), paths.len(), "{problems:?}");
        for path in paths {
            assert!(
                problems
                    .iter()
                    .any(|problem| problem.starts_with(&format!("{path}:2:"))),
                "{path} is refused at its live build: {problems:?}"
            );
        }
        Ok(())
    }

    /// The build-file walk skips only what is not the repository's own (DEC-851 item 5; X1 tests
    /// correction 12): a live build in a `Makefile` under `.git`, under `node_modules`, or in a
    /// directory a `CACHEDIR.TAG` marks as a cache is not read, while one in `tools/` beside them
    /// is, and a `CACHEDIR.TAG` marks only its own directory.
    #[test]
    fn the_build_file_walk_skips_only_git_node_modules_and_caches() -> Result<()> {
        let build = "build:\n\tcargo build --features live\n";
        let root = fixture_repository(
            "build-file-skips",
            &[
                (".git/Makefile", build),
                ("web/node_modules/x/Makefile", build),
                (
                    "target/CACHEDIR.TAG",
                    "Signature: 8a477f597d28d172789f06886806bc55\n",
                ),
                ("target/Makefile", build),
                ("target/debug/Makefile", build),
                ("cache/Makefile", build),
                ("tools/Makefile", build),
            ],
        )?;
        let read = ci_files(&root);
        fs::remove_dir_all(&root).ok();
        let mut read: Vec<String> = read?.into_iter().map(|file| file.path).collect();
        read.sort();
        assert_eq!(read, ["cache/Makefile", "tools/Makefile"]);
        Ok(())
    }

    /// A file both the `.github` scan and the build-file walk find is read once, so its live
    /// build is one problem, not two (X1 tests correction 12, after #979).
    #[test]
    fn a_file_both_scans_find_is_read_once() -> Result<()> {
        let root = fixture_repository(
            "build-file-dedup",
            &[(
                ".github/workflows/docker-compose.yml",
                "jobs:\n  a:\n    steps:\n      - run: cargo build --features live\n",
            )],
        )?;
        let read = ci_files(&root);
        fs::remove_dir_all(&root).ok();
        let read = read?;
        let paths: Vec<&str> = read.iter().map(|file| file.path.as_str()).collect();
        assert_eq!(paths, [".github/workflows/docker-compose.yml"]);
        let problems = live_feature_problems(&live_policy(), &workspace(live_workspace()), &read)?;
        assert_eq!(problems.len(), 1, "{problems:?}");
        Ok(())
    }

    /// A wrapped command word is judged against its own substitution, however many assignments
    /// the wrapper takes: `env -i A=1 B=2 "$(dirname "$0")/x.sh"` runs the script beside this
    /// one, and `env -i A=1 "$(cat cmd)/x.sh" "$(dirname "$0")/y.sh"` does not borrow the later
    /// word's `dirname` (RS's finding on DEC-851 item 6's position lookup).
    #[test]
    fn a_wrapped_command_word_reads_its_own_substitution() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let read = |text: &str| {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{text}\n"),
            )];
            live_feature_problems(&policy, &meta(), &files)
        };
        for text in [
            "env -i A=1 B=2 \"$(dirname \"$0\")/x.sh\"",
            "env -i A=1 \"$(dirname \"$0\")/x.sh\"",
            "env A=1 B=2 C=3 \"$(dirname \"$0\")/x.sh\" --flag",
        ] {
            assert_eq!(read(text)?, Vec::<String>::new(), "{text}");
        }
        for text in [
            "env -i A=1 \"$(cat cmd.txt)/x.sh\" \"$(dirname \"$0\")/y.sh\"",
            "env -i A=1 B=2 \"$(cat cmd.txt)/x.sh\" a \"$(dirname \"$0\")/y.sh\"",
        ] {
            assert_eq!(read(text)?.len(), 1, "{text}");
        }
        Ok(())
    }

    /// A command word that starts with an expansion fails closed (DEC-851 item 6; X1 tests
    /// correction 12b, after #979's review): after its wrappers and keywords, it is refused unless
    /// it is `"$@"`, a sole `$C`/`${C}` or whole array whose definitions are all readable and hold
    /// neither `cargo` nor `live`, `"$(dirname "$0")/<literal path>"`, or `"${ARR[<digits>]}"` of
    /// such an array. So the parameter operators (`${C:-}`, `${C:0}`, `${C//zz/}`, `${C@E}`), an
    /// indirection `${!n}`, a variable no definition in the file gives (`$TOOL`) and a nameref
    /// (`declare`, `local` or `typeset -n`) are refused. A pipeline that feeds a shell after an
    /// expanding word is refused, quoted or not, and so is a `set` that expands in a file that runs
    /// `"$@"`. `$(( … ))` is read whole as arithmetic, its substitutions still read, and is
    /// refused as a command word like any other expansion; an escaped `\$` expands nothing, a double-quoted string
    /// runs on across lines, and a job's `outputs:` is not a `run:` step, so the real lines those
    /// read stay allowed, as do `x+=( … )` and `x[i]=…`, which do not start with an expansion.
    /// X1 tests correction 12c (after #994's surviving mutants) adds: a `..` segment takes the
    /// `dirname` path off the allowlist; a wrapped `exec "$@"` runs `"$@"` too; a nameref in a
    /// cluster (`-rn`) is one; a key at the `outputs:` key's indent ends its block; a `#` that
    /// starts a comment ends a line however many quotes the comment holds, while one inside a
    /// double quote does not; and an escaped `\"` neither opens nor closes a quote.
    /// X1 tests correction 12d (after #994's review) adds: a line ending in `|` or `|&` runs on
    /// into the next; a numeric descriptor's redirection (`2>&1`) before the command word
    /// and `time -p` are skipped; a here-string counts as an earlier expanding word for rule 2;
    /// a wrapper is matched by basename (`/usr/bin/env sh`); a pipeline sink that starts with an
    /// expansion is refused even when its variable is clean; `zsh` is a sink; `${A[]}` and
    /// `${ARR[1x]}` are not literal indexes; a `set` with a backtick expands; a nameref needs an
    /// option holding `n`; an escaped backtick expands nothing; and `...` is not `..`.
    #[test]
    fn command_words_that_start_with_an_expansion_fail_closed() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let built_across_lines =
            "C=ca; C+=rgo; C+=\" build -\"; C+=\"-feat\"; C+=\"ures l\"; C+=ive";
        let refused_at_the_last_line = [
            format!("{built_across_lines}\n${{C:-}}"),
            format!("{built_across_lines}\n${{C:0}}"),
            format!("{built_across_lines}\n${{C//zz/}}"),
            format!("{built_across_lines}\n${{C@E}}"),
            format!("{built_across_lines}\nn=C\n${{!n}}"),
            format!("{built_across_lines}\ndeclare -n R=C\n$R"),
            format!("{built_across_lines}\nlocal -n R=C\n$R"),
            format!("{built_across_lines}\ntypeset -n R=C\n$R"),
            format!("{built_across_lines}\nset -- $C; \"$@\""),
            format!("{built_across_lines}\necho $C | sh"),
            format!("{built_across_lines}\necho \"$C\" | /bin/bash -s"),
            "$TOOL --version".to_owned(),
            "\"$(cat cmd.txt)\" build".to_owned(),
            "\"$(dirname \"$0\")/$X\"".to_owned(),
            "\"$(pwd)/x.sh\"".to_owned(),
            "\"${ARR[0]}\" build".to_owned(),
            "ARR=($X tool)\n\"${ARR[0]}\" build".to_owned(),
            "ARR=(cargo build)\n\"${ARR[1]}\" x".to_owned(),
            "\"$*\"".to_owned(),
            "n=$(( $(cargo build --features \"$F\") ))".to_owned(),
            "\"$(dirname \"$0\")/../x.sh\"".to_owned(),
            format!("{built_across_lines}\n2>&1 $C"),
            format!("{built_across_lines}\n3>&1 $C"),
            format!("{built_across_lines}\ntime -p $C"),
            "C=$(cat f)\ncat <<< \"$C\" | sh".to_owned(),
            "C=$(cat f)\ncat <<< $C | sh".to_owned(),
            "cargo check -p the-runner -F 2>x live".to_owned(),
            format!("{built_across_lines}\necho $C | /usr/bin/env sh"),
            format!("{built_across_lines}\necho $C | zsh"),
            "S=sh\ncurl $U | $S".to_owned(),
            "A=(echo hi)\n\"${A[]}\" x".to_owned(),
            "ARR=(echo hi)\n\"${ARR[1x]}\" x".to_owned(),
            "set -- `cmd`; \"$@\"".to_owned(),
            format!("{built_across_lines}\nset -- $C; exec \"$@\""),
            format!("{built_across_lines}\ndeclare -rn R=C\n$R"),
            "echo hi # see \"docs\ncargo build --features live".to_owned(),
            "\"$((1 + 2))\"".to_owned(),
            "ARR=(echo hi)\n\"${ARR[$i]}\" x".to_owned(),
        ];
        for text in refused_at_the_last_line {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{text}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{text}: {problems:?}");
            assert!(
                problems[0].starts_with(&format!(
                    ".github/scripts/build.sh:{}:",
                    text.lines().count().saturating_add(1)
                )),
                "names the file and the last line: {problems:?}"
            );
        }
        let refused_at_their_first_line = [
            format!("{built_across_lines}\necho $C |\nsh"),
            format!("{built_across_lines}\necho $C |&\nsh"),
        ];
        for text in refused_at_their_first_line {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{text}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{text}: {problems:?}");
            assert!(
                problems[0].starts_with(".github/scripts/build.sh:3:"),
                "a trailing `|` runs the pipeline on into the next line: {problems:?}"
            );
        }
        let allowed = [
            ".github/scripts/build.sh",
            "declare -r R=echo\n$R hi",
            "declare n=echo\n$n hi",
            "\\`ls\\` x",
            "\"$(dirname \"$0\")/.../x.sh\"",
            "\"$@\"",
            "C=echo\n$C hi",
            "x=(echo hi)\n\"${x[@]}\"",
            "base=$(\"$(dirname \"$0\")/base-ref.sh\")",
            "\"$(dirname \"$0\")/base-ref.sh\"",
            "ARR=(/usr/local/bin/tool sub)\n\"${ARR[0]}\" --help",
            "set -- a b; \"$@\"",
            "set -- $A\necho \"$@\"",
            "echo hi | sh",
            "echo \"$X\" | grep y",
            "a=$((10#$a))",
            "db_kb=$(($(du -sk \"$D\" | cut -f1) / 1024))",
            "m=\"${A:-}\n$(git log --format=%B \"$b..HEAD\")\"",
            "psql <<SQL\nDO \\$\\$\nBEGIN\nEND\n\\$\\$;\nSQL",
            "case \"$a\" in\n  -*) flags+=(\"$arg\") ;;\n  *) args+=(\"$arg\") ;;\nesac",
            "values[$1]=\"$2\"",
            "m=\"say \\\"hi\n$(git log --format=%B)\"",
            "m=\"a # b\n$(git log --format=%B)\"",
        ];
        for text in allowed.iter().skip(1) {
            let files = [ci_file(allowed[0], &format!("set -e\n{text}\n"))];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{text}"
            );
        }
        let outputs = ci_file(
            ".github/workflows/x.yml",
            concat!(
                "jobs:\n  a:\n    runs-on: ubuntu-latest\n    outputs:\n",
                "      run: ${{ steps.check.outputs.run }}\n",
                "    steps:\n      - run: echo hi\n",
            ),
        );
        assert_eq!(
            live_feature_problems(&policy, &meta(), &[outputs])?,
            Vec::<String>::new(),
            "a job's `outputs: run:` is not a `run:` step"
        );
        let after_outputs = ci_file(
            ".github/workflows/x.yml",
            concat!(
                "jobs:\n  a:\n    runs-on: ubuntu-latest\n    outputs:\n",
                "      run: ${{ steps.check.outputs.run }}\n",
                "    steps:\n      - run: ${{ inputs.cmd }}\n",
            ),
        );
        let problems = live_feature_problems(&policy, &meta(), &[after_outputs])?;
        assert_eq!(problems.len(), 1, "{problems:?}");
        assert!(
            problems[0].starts_with(".github/workflows/x.yml:7:"),
            "a key at the `outputs:` key's own indent ends its block, so the step's `run:` is read: {problems:?}"
        );
        Ok(())
    }

    /// A pipeline whose line expands may feed only a simple filter, and a wrapper's options are
    /// read by arity (DEC-851 item 6, the coordinator's thirteenth- and fourteenth-round rulings;
    /// X1 tests correction 12e, after the reviews of #994 and #1015). On a logical line holding
    /// `$` or a backtick, every pipeline sink after its wrappers must be one simple command:
    /// `sha256sum`, `tee`, `tr`, `sort` (without `--compress-program`), `grep`, `cut`, `tail`,
    /// `paste`, `cat`, `head`, `uniq`, `wc` or `read`, or, in `deploy/` only, `put_file` or `sql`.
    /// Any other sink (a shell, `awk`, `sed`, a variable), a compound sink (`{ … }`, a loop) and
    /// an empty one (a comment swallowed it) are refused, unless the line is on the interim
    /// exact-line list, which names the repository's own `awk`, `sed`, `while read`,
    /// `done < <( … )` and parser-limited lines by file and text. A process substitution (`<(`,
    /// `>(`) is refused on a line that expands or runs a shell. Finding the command word skips
    /// every unquoted word of a redirection (`2>&1`, `{fd}>&1`) wherever it stands before it, and
    /// each wrapper's options by their arity, `/usr/bin/time -f FMT` and `--` included; an option
    /// of unknown arity is refused. A `#` starts a comment only at a word's start, and a backslash
    /// escapes nothing inside single quotes, so those lines still run on.
    #[test]
    fn pipeline_sinks_and_wrapper_options_fail_closed() -> Result<()> {
        let policy = live_policy();
        let meta = || workspace(live_workspace());
        let built_across_lines =
            "C=ca; C+=rgo; C+=\" build -\"; C+=\"-feat\"; C+=\"ures l\"; C+=ive";
        let refused_at = [
            (format!("{built_across_lines}\necho $C | # c\nsh"), 3),
            (format!("{built_across_lines}\necho $C |\n# comment\nsh"), 3),
            (format!("{built_across_lines}\necho $C | # c \\\nsh"), 3),
            (format!("{built_across_lines}\ntime -p 2>&1 $C"), 3),
            (format!("{built_across_lines}\n{{fd}}>&1 $C"), 3),
            (format!("{built_across_lines}\necho $C | {{fd}}>&1 sh"), 3),
            (format!("{built_across_lines}\ntime -p -- $C"), 3),
            (format!("{built_across_lines}\n/usr/bin/time -f %e $C"), 3),
            (format!("{built_across_lines}\n{{ echo $C; }} | sh"), 3),
            (format!("{built_across_lines}\n( echo $C ) | sh"), 3),
            (
                format!("{built_across_lines}\nif true; then echo $C; fi | sh"),
                3,
            ),
            (
                format!("{built_across_lines}\n{{ echo $C; }} | cat | sh"),
                3,
            ),
            (
                format!("{built_across_lines}\nfor x in a; do echo $C; done | sh"),
                3,
            ),
            (format!("{built_across_lines}\necho $C | rbash"), 3),
            (format!("{built_across_lines}\necho $C | ksh93"), 3),
            ("sudo --bogus echo $X".to_owned(), 2),
            ("timeout --weird 5 echo $X".to_owned(), 2),
            ("echo a#b |\nsh -c \"$C\"".to_owned(), 2),
            ("echo 'a\\' |\nsh -c \"$C\"".to_owned(), 2),
            ("echo \"$X\" | awk '{ system($0) }'".to_owned(), 2),
            ("echo \"$X\" | sed 's/x/y/e'".to_owned(), 2),
            ("echo \"$X\" | python3".to_owned(), 2),
            ("echo \"$X\" | xargs echo".to_owned(), 2),
            ("echo \"$X\" | env".to_owned(), 2),
            ("echo \"$X\" | put_file /tmp/f 0600 root:root".to_owned(), 2),
            ("echo \"$X\" | sql db".to_owned(), 2),
            ("echo $X | { read x; sh; }".to_owned(), 2),
            ("echo $X | { head -n 0; sh -s; }".to_owned(), 2),
            (
                "printf '%s\\n' \"$X\" | while read -r a; do echo \"$a\"; done".to_owned(),
                2,
            ),
            ("echo \"$X\" | sed 's/a/b/'".to_owned(), 2),
            ("echo \"$X\" | sed 1e".to_owned(), 2),
            ("echo \"$X\" | sed \"/x/e\"".to_owned(), 2),
            ("echo \"$X\" | sed \"e;\"".to_owned(), 2),
            ("echo \"$X\" | sed -n \"p;e\"".to_owned(), 2),
            ("echo \"$X\" | sed \"s/a/b/;s/y/z/e\"".to_owned(), 2),
            ("echo \"$X\" | sed --expression=e".to_owned(), 2),
            ("echo \"$X\" | sed -f /dev/stdin".to_owned(), 2),
            ("echo \"$X\" | awk '{ print $1 }'".to_owned(), 2),
            ("echo \"$X\" | awk '{ system ($0) }'".to_owned(), 2),
            ("echo \"$X\" | awk -f /dev/stdin".to_owned(), 2),
            (
                "echo \"$X\" | awk '{ printf \"%s\", $0 | \"sh\" }'".to_owned(),
                2,
            ),
            ("echo \"$X\" | awk '{ print |& \"sh\" }'".to_owned(), 2),
            ("echo \"$X\" | tee >(sh)".to_owned(), 2),
            ("echo \"$X\" > >(sh)".to_owned(), 2),
            ("echo \"$X\" 3> >(sh)".to_owned(), 2),
            ("echo \"$X\" | sort -o >(sh)".to_owned(), 2),
            ("sh <(echo $X)".to_owned(), 2),
            ("sh < <(echo $X)".to_owned(), 2),
            ("exec 3< <(echo $X); sh <&3".to_owned(), 2),
            ("sh <(echo hi)".to_owned(), 2),
            ("echo \"$X\" | sort --compress-program=sh".to_owned(), 2),
        ];
        for (text, line) in refused_at {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{text}\n"),
            )];
            let problems = live_feature_problems(&policy, &meta(), &files)?;
            assert_eq!(problems.len(), 1, "{text}: {problems:?}");
            assert!(
                problems[0].starts_with(&format!(".github/scripts/build.sh:{line}:")),
                "{text}: {problems:?}"
            );
        }
        let allowed = [
            "echo \"$X\" | sha256sum",
            "echo \"$X\" | tee out.txt",
            "echo \"$X\" | tr a b",
            "echo \"$X\" | sort -u",
            "echo \"$X\" | grep x",
            "echo \"$X\" | cut -f1",
            "echo \"$X\" | tail -1",
            "echo \"$X\" | sort | paste -sd ' ' -",
            "echo \"$X\" | cat",
            "echo \"$X\" | head -1",
            "echo \"$X\" | uniq",
            "echo \"$X\" | wc -l",
            "diff <(echo a) <(echo b)",
            "\"2\">&1 $X",
            "2a>&1 $X",
            "export -n R=echo\n$R hi",
            "echo hi | sh",
            "time -p -- echo hi",
            "/usr/bin/time -f %e echo hi",
        ];
        for text in allowed {
            let files = [ci_file(
                ".github/scripts/build.sh",
                &format!("set -e\n{text}\n"),
            )];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "{text}"
            );
        }
        let systemd_run = concat!(
            "printf '%s' \"$answer\" | systemd-run --quiet --wait --pipe --collect \\\n",
            "  -p User=owlhead_exec -p Group=owlhead_exec -p UMask=0077 \\\n",
            "  -p LoadCredential=vault-pending-key:\"$CREDENTIALS/vault-pending-key\" \\\n",
            "  -p LoadCredential=vault-token-key:\"$CREDENTIALS/vault-token-key\" \\\n",
            "  -p EnvironmentFile=\"$EXEC_ENV\" \\\n",
            "  \"${VAULT_IMPORT[@]}\"\n",
        );
        let regex = "if [[ \"${line%%=*}\" =~ (KEY|SECRET|TOKEN|PASSWORD) ]]; then\n  echo x\nfi\n";
        let deploy_only = [
            "echo \"$X\" | put_file /tmp/f 0600 root:root\n",
            "openssl rand -base64 32 | put_file \"$C/$key\" 0600 root:root\n",
            "{ echo \"$X\"; } | sql \"$DB\"\n",
            systemd_run,
            regex,
        ];
        for text in deploy_only {
            let files = [ci_file("deploy/set-secrets.sh", text)];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?,
                Vec::<String>::new(),
                "deploy/'s own sinks and its exact parser-limited lines: {text}"
            );
        }
        for text in [systemd_run, regex] {
            let files = [ci_file("deploy/other.sh", text)];
            assert_eq!(
                live_feature_problems(&policy, &meta(), &files)?.len(),
                1,
                "an exact line is allowed only in its own file: {text}"
            );
        }
        let exact = [
            (
                "deploy/allow-egress.sh",
                "found=\"$(getent ahosts \"$host\" | awk '{ print $1 }' | sort -u)\"\n",
            ),
            (
                "deploy/allow-egress.sh",
                "printf '%s\\n' \"$allow\" | sort -u | while read -r address; do\n  echo \"$address\"\ndone\n",
            ),
            (
                "deploy/backup.sh",
                "free_kb=\"$(df -Pk \"$DEST\" | awk 'NR == 2 { print $4 }')\"\n",
            ),
            (
                "deploy/bootstrap.sh",
                "found=\"$(gpg --show-keys --with-colons \"$PGDG_KEY\" | awk -F: '$1 == \"fpr\" { print $10; exit }')\"\n",
            ),
            (
                "deploy/install-cloudflared.sh",
                "gpg --show-keys --with-colons \"$1\" 2>/dev/null | awk -F: '$1 == \"fpr\" { print $10; exit }'\n",
            ),
            (
                "deploy/lib.sh",
                "sed -n '2,/^set -euo/p' \"$0\" | sed '$d; s/^# \\{0,1\\}//'\n",
            ),
            (
                ".github/scripts/docs-only.sh",
                "while read -r f; do\n  echo \"$f\"\ndone < <(git diff --name-only \"$merge_base\" HEAD)\n",
            ),
            (
                ".github/scripts/merge-approved.sh",
                "approvals=$(awk '/^[[:space:]]*(```|~~~)/ { fenced = !fenced; next } !fenced' <<<\"$body\" | sed -nE 's/^[[:space:]]*([-*][[:space:]]+)?Coordinator-approved-head:[[:space:]]*([0-9a-fA-F]{40})[[:space:]]*$/\\2/p' | tr 'A-F' 'a-f')\n",
            ),
        ];
        for (path, text) in exact {
            assert_eq!(
                live_feature_problems(&policy, &meta(), &[ci_file(path, text)])?,
                Vec::<String>::new(),
                "{path}'s exact line: {text}"
            );
            assert_eq!(
                live_feature_problems(&policy, &meta(), &[ci_file("deploy/other.sh", text)])?.len(),
                1,
                "the same line in another file is judged: {text}"
            );
        }
        for text_into_a_shell in [
            "set -e\nbash <(cat <<EOF\n$C \"$A\"\nEOF\n)\n",
            "set -e\nbash <(echo '\n$C \"$A\"\n')\n",
        ] {
            let problems = live_feature_problems(
                &policy,
                &meta(),
                &[ci_file(".github/scripts/build.sh", text_into_a_shell)],
            )?;
            assert_eq!(problems.len(), 2, "{text_into_a_shell}: {problems:?}");
            for (problem, line) in problems.iter().zip([":2:", ":3:"]) {
                assert!(
                    problem.starts_with(&format!(".github/scripts/build.sh{line}")),
                    "the process substitution into a shell, and the line it runs: {problems:?}"
                );
            }
        }
        let edited = systemd_run.replace("--collect", "--collect sh");
        let files = [ci_file("deploy/set-secrets.sh", &edited)];
        assert_eq!(
            live_feature_problems(&policy, &meta(), &files)?.len(),
            1,
            "an edited exact line is judged again"
        );
        Ok(())
    }

    /// A build file the check cannot read as text, a dangling symlink or a file that is not
    /// UTF-8, is reported as a problem naming its path, not an error that aborts the check (X1
    /// tests correction 12b, after #979's review; DEC-851 item 6), and so is one holding a NUL
    /// byte (X1 tests correction 12c, after #994's planted NUL).
    #[test]
    fn an_unreadable_build_file_is_refused_by_path() -> Result<()> {
        let root = fixture_repository(
            "build-file-unreadable",
            &[(".github/workflows/a.yml", "x\n")],
        )?;
        symlink(root.join("missing"), root.join("Makefile"))?;
        fs::write(root.join("justfile"), [0xff_u8, 0xfe, b'\n'])?;
        fs::write(root.join("Dockerfile"), "RUN echo hi\0\n")?;
        let read = ci_files(&root);
        fs::remove_dir_all(&root).ok();
        let problems = live_feature_problems(&live_policy(), &workspace(live_workspace()), &read?)?;
        assert_eq!(problems.len(), 3, "{problems:?}");
        for path in ["Makefile", "justfile", "Dockerfile"] {
            assert!(
                problems
                    .iter()
                    .any(|problem| problem.starts_with(&format!("{path}: "))),
                "{path} is named: {problems:?}"
            );
        }
        Ok(())
    }

    /// A minimal Cargo workspace with one crate, `a`, and its layering policy, under `root`, so
    /// the lint job's checks that read the workspace can run there.
    fn fixture_workspace(root: &Path) -> Result<()> {
        fs::create_dir_all(root.join("a/src"))?;
        fs::create_dir_all(root.join("xtask"))?;
        fs::write(
            root.join("Cargo.toml"),
            "[workspace]\nmembers = [\"a\"]\nresolver = \"3\"\n",
        )?;
        fs::write(
            root.join("a/Cargo.toml"),
            "[package]\nname = \"a\"\nversion = \"0.0.0\"\nedition = \"2024\"\n",
        )?;
        fs::write(root.join("a/src/lib.rs"), "//! A fixture crate.\n")?;
        fs::write(
            root.join("Cargo.lock"),
            "version = 4\n\n[[package]]\nname = \"a\"\nversion = \"0.0.0\"\n",
        )?;
        fs::write(
            root.join("xtask/layers.toml"),
            concat!(
                "impure_crates = []\n\n",
                "[crates.a]\nlayer = 1\nsafety_critical = false\npure = false\n",
            ),
        )?;
        Ok(())
    }

    /// The lint job runs the live-feature check over its own repository (#738 review, finding
    /// 2): a fixture workspace with a clean workflow passes, and a workflow that runs `live`
    /// fails the job naming the check, before the workspace checks run. The fixture has the
    /// `deploy/` directory main's lint job runs ShellCheck over (#795), with one clean script.
    #[test]
    fn the_lint_job_runs_the_live_feature_check_on_its_repository() -> Result<()> {
        let root = env::temp_dir().join(format!("mandate-xtask-lint-live-{}", std::process::id()));
        if root.exists() {
            fs::remove_dir_all(&root)?;
        }
        fixture_workspace(&root)?;
        let workflows = root.join(".github/workflows");
        fs::create_dir_all(&workflows)?;
        fs::create_dir_all(root.join(".github/scripts"))?;
        fs::create_dir_all(root.join("deploy"))?;
        fs::create_dir_all(root.join("scripts"))?;
        fs::write(
            root.join("deploy/clean.sh"),
            "#!/usr/bin/env bash\nset -euo pipefail\necho \"deployed\"\n",
        )?;
        let workflow = |run: &str| {
            format!(
                "on: push\njobs:\n  check:\n    runs-on: ubuntu-24.04\n    steps:\n      - run: {run}\n"
            )
        };
        fs::write(workflows.join("ci.yml"), workflow("cargo check -p a"))?;
        let clean = lint(&root, None, || Ok(())).map_err(|err| format!("{err:#}"));
        fs::write(
            workflows.join("ci.yml"),
            workflow("cargo run -p a --features live"),
        )?;
        let reached = Cell::new(false);
        let planted = lint(&root, None, || {
            reached.set(true);
            Ok(())
        })
        .map_err(|err| format!("{err:#}"))
        .err();
        fs::remove_dir_all(&root).ok();
        assert_eq!(clean, Ok(()), "a clean fixture workspace passes");
        assert!(
            planted
                .as_deref()
                .is_some_and(|err| err.contains("live-feature")),
            "a workflow that runs `live` fails the lint job naming the check, got {planted:?}"
        );
        assert!(
            !reached.get(),
            "the workspace checks run only after it passes"
        );
        Ok(())
    }

